Object.assign(window.TEM8_DICTIONARY, {"bought":{"lemma":"buy","media":{"uk":"media/uk/bought__gb_1.mp3","us":"media/us/bought__us_1.mp3"}},"boxing":{"media":{"img":["media/pic/sports_comp.jpg","media/thumb/boxing.jpg"],"uk":"media/uk/boxing__gb_1.mp3","us":"media/us/boxing__us_1.mp3"},"oxford":{"phon":"ˈbɒksɪŋ","pos":"noun","senses":[{"en":"a sport in which two people fight each other with their hands, while wearing very large thick gloves (called boxing gloves)","cn":"拳击（运动）","ex":{"en":"a boxing champion/match","cn":"拳击冠军／比赛"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"拳击（运动）","en":"Boxing is a sport in which two people wearing large padded gloves fight according to special rules.","ex":{"en":"Some speakers argued that boxing was less dangerous than rugby.","cn":"一些发言者认为拳击的危险性比橄榄球运动小。"}}]},"examples":[{"en":"a boxing champion/match","cn":"拳击冠军/比赛"},{"en":"heavyweight boxing","cn":"重量级拳击"}],"base":"box"},"bolt":{"media":{"img":["media/ldoce/img/bolt.jpg","media/pic/bolt_comp.jpg"],"uk":"media/uk/bolt__gb_1.mp3","us":"media/us/bolt__us_1.mp3"},"oxford":{"phon":"bəʊlt","pos":"noun","senses":[{"en":"a long, narrow piece of metal that you slide across the inside of a door or window in order to lock it","cn":"（门窗的）闩，插销","ex":{"en":"He slid back the bolt on the door.","cn":"他把门上的插销滑回去。"}},{"en":"a piece of metal like a thick nail without a point which is used with a circle of metal (= a nut) to fasten things together","cn":"螺栓","ex":{"en":"nuts and bolts","cn":"螺帽和螺栓"}},{"en":"a sudden flash of lightning in the sky, appearing as a line","cn":"闪电"},{"en":"a short heavy arrow shot from a crossbow","cn":"弩箭"},{"en":"a long piece of cloth wound in a roll around a piece of cardboard","cn":"一匹（布）"},{"en":"to fasten something such as a door or window by sliding a bolt across; to be able to be fastened in this way","cn":"用插销闩上；能被闩上","g":"[transitive, intransitive]","ex":{"en":"Don't forget to bolt the door.","cn":"别忘了闩门。"},"pos":"verb"},{"en":"to fasten things together with a bolt","cn":"用螺栓把（甲和乙）固定在一起","g":"[transitive]","ex":{"en":"The vice is bolted to the workbench.","cn":"这虎钳是用螺栓固定在工作台上的。"},"pos":"verb"},{"en":"if an animal, especially a horse, bolts, it suddenly runs away because it is frightened","cn":"（马等受惊）脱缰","g":"[intransitive]","ex":{"en":"Bonnie the mare broke free and bolted.","cn":"母马邦妮挣脱束缚，逃跑了。"},"pos":"verb"},{"en":"to run away, especially in order to escape","cn":"跑开；（尤指）逃跑","g":"[intransitive]","ex":{"en":"When he saw the police arrive, he bolted down an alley.","cn":"他看见警察来了，便从小巷逃走了。"},"pos":"verb"},{"en":"to eat something very quickly","cn":"狼吞虎咽","g":"[transitive]","ex":{"en":"Don't bolt your food!","cn":"吃饭不能狼吞虎咽！"},"pos":"verb"},{"en":"to stop supporting a particular group or political party","cn":"停止支持（某团体或政党）","g":"[transitive, intransitive]","lab":"North American English","ex":{"en":"Many Democrats bolted the party to vote Republican.","cn":"很多民主党人放弃本党，转而投共和党的票。"},"pos":"verb"},{"en":"to grow too quickly and start producing seeds and so become less good to eat","cn":"过早结实（因而食用价值降低）","g":"[intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"螺栓","en":"A bolt is a long metal object which screws into a nut and is used to fasten things together."},{"pos":"VERB 动词","cn":"用螺栓固定；闩上","en":"When you bolt one thing to another, you fasten them firmly together, using a bolt.","ex":{"en":"The safety belt is easy to fit as there's no need to bolt it to seat belt anchorage points","cn":"由于不必扣在座位的固定夹上，安全带很容易就可以系好。"}},{"pos":"N-COUNT 可数名词","cn":"（门、窗的）金属插销，闩","en":"A bolt on a door or window is a metal bar that you can slide across in order to fasten the door or window.","ex":{"en":"I heard the sound of a bolt being slowly and reluctantly slid open.","cn":"我听到门闩被缓慢而吃力地拉开的声音。"}},{"pos":"VERB 动词","cn":"闩上（门、窗）","en":"When you bolt a door or window, you slide the bolt across to fasten it.","ex":{"en":"He reminded her that he would have to lock and bolt the kitchen door after her.","cn":"他提醒她,在她走后他得把厨房的门上锁并闩上。"}},{"pos":"VERB 动词","cn":"（常指人或动物因受惊吓）迅速逃跑，逃窜","en":"If a person or animal bolts, they suddenly start to run very fast, often because something has frightened them.","ex":{"en":"The pig rose squealing and bolted","cn":"那头猪突然嗷嗷叫着狂奔起来。"}},{"pos":"VERB 动词","cn":"狼吞虎咽","en":"If you bolt your food, you eat it so quickly that you hardly chew it or taste it.","ex":{"en":"Being under stress can cause you to miss meals, eat on the move, or bolt your food.","cn":"人在压力之下有时会吃不上饭，或边走边吃，或是匆匆吃上几口。"}},{"pos":"N-COUNT 可数名词","cn":"一道（闪电）","en":"A bolt of lightning is a flash of lightning that is seen as a white line in the sky.","ex":{"en":"Suddenly a bolt of lightning crackled through the sky.","cn":"突然一道闪电划破长空。"}},{"pos":"N-COUNT 可数名词","cn":"（布的）一匹，一卷","en":"A bolt of cloth is a long wide piece of it that is wound into a roll round a piece of cardboard.","ex":{"en":"...bolts of black silk.","cn":"成匹的黑丝绸"}},{"pos":"VERB 动词","cn":"（蔬菜）生长过快，结实过早（而不宜食用）","en":"When vegetables such as lettuces or onions bolt, they grow too quickly and produce flowers and seeds, and therefore become less good to eat.","ex":{"en":"If the soil dries out the plants may bolt.","cn":"如果土壤过干，植株可能会过早结实。"}},{"pos":"PHRASE 短语","cn":"突然逃跑；慌忙逃窜","en":"If someone makes a bolt for somewhere, or makes a bolt for it, they make a sudden escape.","ex":{"en":"His father kept a tight grip on his collar in case he should make a bolt for the door.","cn":"他的父亲紧紧抓住他的衣领，防止他夺门而逃。"}},{"pos":"PHRASE 短语","cn":"晴天霹雳；出人意表；令人大吃一惊","en":"If a piece of news comes like a bolt from the blue, it is completely unexpected and very surprising.","ex":{"en":"The company decided to appoint a Japanese manager as president of the company. The decision came as a bolt from the blue.","cn":"公司决定任命一位日籍经理担任总裁。这个决定太出乎意料了。"}},{"pos":"PHRASE 短语","cn":"挺直地；笔直地","en":"If someone is sitting or standing bolt upright, they are sitting or standing very straight.","ex":{"en":"When I pushed his door open, Trevor was sitting bolt upright in bed.","cn":"当我推开特雷弗的房门时，他正腰杆笔直地坐在床上。"}},{"pos":"","cn":"","en":"nuts and bolts→see: ; to close the stable door after the horse has bolted→see: ;"},{"pos":"","cn":"","en":"相关词组：bolt down"}]},"examples":[{"en":"Many Democrats bolted the party to vote Republican.","cn":"很多民主党人放弃本党，转而投共和党的票。"},{"en":"The various parts of the car are then bolted together.","cn":"然后汽车的各种部件便用螺栓装配在一起。"}]},"boil":{"oxford":{"phon":"bɔɪl","pos":"verb","senses":[{"en":"when a liquid boils or when you boil it, it is heated to the point where it forms bubbles and turns to steam or vapour","cn":"（使）沸腾；煮沸；烧开","g":"[intransitive, transitive]","ex":{"en":"The water was bubbling and boiling away.","cn":"水在咕嘟咕嘟地沸腾着。"}},{"en":"when a kettle, pan, etc. boils or when you boil a kettle, etc., it is heated until the water inside it boils","cn":"（把壶、锅等里面的水）烧开","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"The kettle's boiling.","cn":"壶开了。"}},{"en":"to cook or wash something in boiling water; to be cooked or washed in boiling water","cn":"用沸水煮（或烫洗）；被煮（或烫洗）","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"She put some potatoes on to boil.","cn":"她煮了些土豆。"}},{"en":"if you boil with anger, etc. or anger, etc. boils inside you, you are very angry","cn":"怒火中烧；异常气愤","g":"[intransitive]","ex":{"en":"He was boiling with rage.","cn":"他怒不可遏。"}},{"en":"a period of boiling; the point at which liquid boils","cn":"沸腾；沸点","g":"[singular]","lab":"British English","ex":{"en":"Bring the soup to the boil, then allow it to simmer for five minutes.","cn":"把汤煮开，然后文火煮五分钟。"},"pos":"noun"},{"en":"a painful swelling (= an area that is larger and rounder than normal) under the skin which is full of a thick yellow liquid (called pus)","cn":"疖；皮下脓肿；黄水疮","g":"[countable]","ex":{"en":"The doctor lanced the boil.","cn":"医生切开疖子。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）达到沸点；（使）沸腾；（使）烧开","en":"When a hot liquid boils or when you boil it, bubbles appear in it and it starts to change into steam or vapour.","ex":{"en":"I stood in the kitchen, waiting for the water to boil","cn":"我站在厨房，等着水烧开。"}},{"pos":"V-ERG 及物/不及物动词","cn":"使（水壶或锅里的水）烧开","en":"When you boil a kettle or pan, or put it on to boil, you heat the water inside it until it boils.","ex":{"en":"He had nothing to do but boil the kettle and make the tea","cn":"他除了烧水沏茶以外无事可做。"}},{"pos":"VERB 动词","cn":"（水壶或平底锅里的水）烧开，沸腾","en":"When a kettle or pan is boiling, the water inside it has reached boiling point.","ex":{"en":"Is the kettle boiling?","cn":"壶里的水开了吗？"}},{"pos":"V-ERG 及物/不及物动词","cn":"用开水煮；在开水中煮","en":"When you boil food, or when it boils, it is cooked in boiling water. →see usage note at:","ex":{"en":"Boil the chick peas, add garlic and lemon juice","cn":"把鹰嘴豆放在开水中煮，并加入大蒜和柠檬汁。"}},{"pos":"VERB 动词","cn":"愤怒；怒火中烧","en":"If you are boiling with anger, you are very angry.","ex":{"en":"I used to be all sweetness and light on the outside, but inside I would be boiling with rage.","cn":"我过去常常是外表看上去轻松愉快，而内心却怒火中烧。"}},{"pos":"N-COUNT 可数名词","cn":"疖子；疔","en":"A boil is a red, painful swelling on your skin, which contains a thick yellow liquid called pus."},{"pos":"PHRASE 短语","cn":"(使)沸腾；（使）达到沸点","en":"When you bring a liquid to the boil, you heat it until it boils. When it comes to the boil, it begins to boil.","ex":{"en":"Put water, butter and lard into a saucepan and bring slowly to the boil.","cn":"把水、黄油和猪油倒入平底锅，然后慢火煮沸。"}},{"pos":"","cn":"","en":"to make someone's blood boil→see: ;"},{"pos":"","cn":"","en":"相关词组：boil away boil down boil down to boil over boil up"}]},"media":{"img":["media/pic/cooking_methods_comp.jpg","media/thumb/boil.jpg"],"uk":"media/uk/boil__gb_1.mp3","us":"media/us/boil__us_1.mp3"},"examples":[{"en":"Racial tension finally boiled over in the inner city riots.","cn":"种族间的紧张状态最终演化成了内城区的暴乱。"},{"en":"Boil plenty of salted water, then add the spaghetti.","cn":"把足量的盐水烧开，再放入意大利面条。"}]},"bountiful":{"media":{"uk":"media/uk/bountiful__gb_1.mp3","us":"media/us/bountiful__us_1.mp3"},"oxford":{"phon":"ˈbaʊntɪfl","pos":"adjective","senses":[{"en":"in large quantities; large","cn":"大量的；巨大的","ex":{"en":"a bountiful supply of food","cn":"充足的食物供应"}},{"en":"giving generously","cn":"慷慨的；大方的","ex":{"en":"belief in a bountiful god","cn":"对慷慨的神的信仰"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大量的；丰富的","en":"A bountiful supply or amount of something pleasant is a large one.","ex":{"en":"State aid is less bountiful than it was before.","cn":"国家提供的援助比以往减少了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地区或时期）物产富饶的，（尤指）食物充足的","en":"A bountiful area or period of time produces or provides large amounts of something, especially food.","ex":{"en":"The land is bountiful and no one starves.","cn":"这片土地物产丰富，没有人挨饿。"}}]},"examples":[{"en":"belief in a bountiful god","cn":"对宽宏的神的信仰"},{"en":"a bountiful supply of food","cn":"富足的食物供应"}]},"boundaries":{"lemma":"boundary"},"borough":{"oxford":{"phon":"ˈbʌrə","pos":"noun","senses":[{"en":"a town or part of a city that has its own local government","cn":"自治市镇；（城市）行政区","ex":{"en":"the London borough of Westminster","cn":"伦敦的威斯敏斯特自治市"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自治市镇；（大城市中的）行政区","en":"A borough is a town, or a district within a large town, which has its own council.","ex":{"en":"...the South London borough of Lambeth.","cn":"伦敦南部的兰贝斯区"}}]},"media":{"uk":"media/uk/borough__gb_1.mp3","us":"media/us/borough__us_1.mp3"},"examples":[{"en":"The Bronx is one of the five boroughs of New York.","cn":"布朗克斯是纽约市的五个行政区之一。"},{"en":"the London borough of Westminster","cn":"伦敦的威斯敏斯特自治市"}]},"bolster":{"media":{"uk":"media/uk/bolster__gb_1.mp3","us":"media/us/bolster__us_1.mp3"},"oxford":{"phon":"ˈbəʊlstə(r)","pos":"verb","senses":[{"en":"to improve something or make it stronger","cn":"改善；加强","ex":{"en":"to bolster somebody’s confidence/courage/morale","cn":"增强某人的信心／勇气／士气"}},{"en":"a long thick pillow that is placed across the top of a bed under the other pillows","cn":"垫枕（长而厚）","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"增强（信心）；鼓舞（士气）","en":"If you bolster something such as someone's confidence or courage, you increase it.","ex":{"en":"Hopes of an early cut in interest rates bolstered confidence.","cn":"利率有望早日下调，从而增强了人们的信心。"}},{"pos":"VERB 动词","cn":"巩固（地位）；加强","en":"If someone tries to bolster their position in a situation, they try to strengthen it.","ex":{"en":"Britain is free to adopt policies to bolster its economy.","cn":"英国可以自由制定政策以振兴经济。"}},{"pos":"N-COUNT 可数名词","cn":"（垫在普通枕头下的）长枕，垫枕","en":"A bolster is a firm pillow shaped like a long tube which is sometimes put across a bed under the ordinary pillows."},{"pos":"","cn":"","en":"相关词组：bolster up"}]},"examples":[{"en":"Falling interest rates may help to bolster up the economy.","cn":"利率下降可能有助于刺激经济。"},{"en":"to bolster sb's confidence/courage/morale","cn":"增加某人的信心/勇气/士气"}]},"bowl":{"media":{"img":["media/ldoce/img/bowl.jpg","media/pic/bowls_hobbies_comp.jpg"],"uk":"media/uk/bowl__gb_1.mp3","us":"media/us/bowl__us_1.mp3"},"oxford":{"phon":"bəʊl","pos":"noun","senses":[{"en":"a deep round dish with a wide open top, used especially for holding food or liquid","cn":"碗；钵；盆","g":"[countable]","sc":"container","ex":{"en":"a salad/fruit/sugar bowl","cn":"色拉碗；水果盆；糖钵"}},{"en":"the amount contained in a bowl","cn":"一碗，一钵，一盆（的量）","g":"[countable]","sc":"amount","ex":{"en":"He poured himself a bowl of soup.","cn":"他给自己倒了一碗汤。"}},{"en":"the part of some objects that is like a bowl in shape","cn":"物体的碗状部分","g":"[countable]","sc":"shape","ex":{"en":"the bowl of a spoon","cn":"勺子头"}},{"en":"a large round theatre without a roof, used for concerts, etc. outdoors","cn":"露天圆形剧场","g":"[countable]","lab":"especially North American English","sc":"theatre","ex":{"en":"the Hollywood Bowl","cn":"好莱坞露天剧场"}},{"en":"a heavy wooden ball that is used in the games of bowls and bowling","cn":"（草地滚球运动和保龄球运动中用的）木球","g":"[countable]","sc":"ball"},{"en":"a game played on an area of very smooth grass, in which players take turns to roll bowls as near as possible to a small ball","cn":"草地滚球运动","g":"[uncountable]","lab":"North American English also","sc":"game"},{"en":"a game of American football played after the main season between the best teams","cn":"（美式足球主要赛季后强队之间的）碗赛","g":"[countable]","lab":"North American English","sc":"football game","ex":{"en":"the Super Bowl","cn":"超级碗季后赛"}},{"en":"to roll a ball in the games of bowls and bowling","cn":"（草地滚球运动或保龄球运动中）滚球，投球","g":"[intransitive, transitive]","sc":"roll ball","ex":{"en":"It was Peter's turn to bowl.","cn":"轮到彼得投球了。"},"pos":"verb"},{"en":"to throw a ball to the batsman (= the person who hits the ball)","cn":"把（球）投给击球员","g":"[intransitive, transitive]","lab":"especially British English","sc":"in cricket","ex":{"en":"He bowled him a gentle first ball.","cn":"他轻轻地向他投出第一个球。"},"pos":"verb"},{"en":"to make the batsman have to leave the field by throwing a ball that hits the wicket","cn":"击掉三柱门的横木使（击球员）杀出局；破门使（击球员）出局","g":"[transitive]","sc":"in cricket","pos":"verb"},{"en":"to move quickly in a particular direction, especially in a vehicle","cn":"（向某处）迅速移动；（尤指）快速行驶","g":"[intransitive]","sc":"move quickly","ex":{"en":"Soon we were bowling along the country roads.","cn":"我们不久便在乡村的公路上疾驰了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"碗；钵；盆","en":"A bowl is a round container with a wide uncovered top. Some kinds of bowl are used, for example, for serving or eating food from, or in cooking, while other larger kinds are used for washing or cleaning.","ex":{"en":"Put all the ingredients into a large bowl","cn":"把所有配料都放进一个大碗里。"}},{"pos":"N-COUNT 可数名词","cn":"一碗之量","en":"The contents of a bowl can be referred to as a bowl of something.","ex":{"en":"...a bowl of soup.","cn":"一碗汤"}},{"pos":"N-COUNT 可数名词","cn":"碗状部分","en":"You can refer to the hollow rounded part of an object as its bowl .","ex":{"en":"He smacked the bowl of his pipe into his hand.","cn":"他在自己手上磕打烟斗。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"草地滚木球运动","en":"Bowls is a game in which players try to roll large wooden balls as near as possible to a small wooden ball. Bowls is usually played outdoors on grass."},{"pos":"N-COUNT 可数名词","cn":"（草地滚木球运动中用的）木球","en":"A set of bowls is a set of round wooden balls that you play bowls with."},{"pos":"VERB 动词","cn":"玩草地滚木球游戏；玩保龄球","en":"If you bowl, you play the game of bowls or the game of bowling.","ex":{"en":"Everyone wanted to bowl, hence everyone wanted to open a bowling alley.","cn":"大家都想玩保龄球，因此大家都想开保龄球馆。"}},{"pos":"VERB 动词","cn":"（在板球等运动中）投（球）给击球手","en":"In a sport such as cricket, when a bowler bowls a ball, he or she sends it down the pitch towards a batsman.","ex":{"en":"I can't see the point of bowling a ball like that","cn":"我看不出那样投球用意何在。"}},{"pos":"VERB 动词","cn":"（在板球等运动中因为投球手击中三柱门）迫使（击球手）出局","en":"In a sport such as cricket, when a batsman is bowled, he has to leave the pitch because the bowler has hit the wicket with the ball.","ex":{"en":"Watkins hit 16 before being bowled by Ambrose.","cn":"沃特金斯击球得了16分后被安布罗斯投杀出局。"}},{"pos":"VERB 动词","cn":"（尤指愉快地乘车或船）快速行驶","en":"If you bowl along in a car or on a boat, you move along very quickly, especially when you are enjoying yourself.","ex":{"en":"Veronica looked at him, smiling, as they bowled along","cn":"他们的车快速前行时，韦罗妮卡面带微笑地看着他。"}},{"pos":"N-IN-NAMES 名称名词","cn":"椭圆形运动场；环形剧场","en":"A large stadium where sports or concerts take place is sometimes called a Bowl .","ex":{"en":"...the Crystal Palace Bowl.","cn":"水晶宫露天剧场"}},{"pos":"N-COUNT 可数名词","cn":"（主赛季后最强的大学球队参加的）季后赛，杯赛","en":"A bowl or bowl game is a competition in which the best college teams play, after the main season has ended.","ex":{"en":"...the Fiesta college football bowl.","cn":"大学橄榄球节日碗赛"}},{"pos":"","cn":"","en":"相关词组：bowl out bowl over"}]},"examples":[{"en":"Soon we were bowling along the country roads.","cn":"我们不久便在乡村的公路上疾驰了。"},{"en":"a salad/fruit/sugar, etc. bowl","cn":"色拉碗、水果盆、糖钵等"}]},"bounds":{"media":{"uk":"media/uk/bounds__gb_1.mp3","us":"media/us/bounds__us_1.mp3"},"oxford":{"phon":"baʊndz","pos":"noun","senses":[{"en":"the accepted or furthest limits of something","cn":"限制范围；极限","ex":{"en":"beyond/outside/within the bounds of decency","cn":"没体统；有体统"}}]},"examples":[{"en":"It was not beyond the bounds of possibility that they would meet again one day.","cn":"他们有一天会再度相遇，这不是没有可能。"},{"en":"Public spending must be kept within reasonable bounds.","cn":"公共开支必须控制在合理的范围内。"}],"base":"bound"},"borrows":{"lemma":"borrow"},"bottom":{"media":{"uk":"media/uk/bottom__gb_1.mp3","us":"media/us/bottom__us_1.mp3"},"oxford":{"phon":"ˈbɒtəm","pos":"noun","senses":[{"en":"the lowest part of something","cn":"底部；最下部","g":"[countable, usually singular]","sc":"lowest part","ex":{"en":"the bottom of the screen/stairs/hill","cn":"屏幕底部；楼梯底部；山脚"}},{"en":"the part of something that faces downwards and is not usually seen","cn":"（朝下的）底，底面","g":"[countable, usually singular]","sc":"lowest part","ex":{"en":"The bottom of the pan was all sticky.","cn":"锅底都粘住了。"}},{"en":"the lowest surface on the inside of a container","cn":"（容器内的）底","g":"[countable, usually singular]","sc":"of container","ex":{"en":"Line the bottom of the cage with newspaper.","cn":"给笼子底部垫上报纸。"}},{"en":"the ground below the water in a lake, the sea, a swimming pool, etc.","cn":"（湖、海、游泳池等的）底，水底","g":"[singular]","sc":"of lake/sea/pool","ex":{"en":"I feel safe as long as I can touch the bottom.","cn":"只要能触到底部我就感到安全。"}},{"en":"the lowest position in a class, on a list, etc.; a person, team, etc. that is in this position","cn":"（班级、名单等的）最末位置；排名最后的人（或团队等）","g":"[singular]","sc":"lowest position","ex":{"en":"When the list came out, my name was near the bottom.","cn":"名单出来了，我的名字接近末尾。"}},{"en":"the part of the body that you sit on","cn":"屁股；臀部","g":"[countable]","lab":"especially British English","sc":"part of body","ex":{"en":"We sat on our bottoms on the damp grass.","cn":"我们屁股坐在潮湿的草地上。"}},{"en":"the lower part of a set of clothes that consists of two pieces","cn":"套装的裙（或裤）","g":"[countable, usually plural]","sc":"clothing","ex":{"en":"a pair of pyjama/tracksuit bottoms","cn":"一条睡裤／运动裤"}},{"en":"the part of something that is furthest from you, your house, etc.","cn":"…尽头","g":"[singular]","lab":"especially British English","sc":"end of something","ex":{"en":"There was a stream at the bottom of the garden.","cn":"花园尽头有一条小溪。"}},{"en":"the lower part of a ship that is below the surface of the water","cn":"（吃水线以下的）船底，船身","g":"[countable]","sc":"of ship"},{"en":"having the type of bottom mentioned","cn":"有…底的","sc":"-bottomed","ex":{"en":"a flat-bottomed boat","cn":"平底船"}},{"en":"in the lowest, last or furthest place or position","cn":"底部的；最后的；尽头的","g":"[only before noun]","ex":{"en":"your bottom lip","cn":"下嘴唇"},"pos":"adjective"},{"en":"the lowest or last position in a scale or competition","cn":"（级别或排名）最低的，最末的","ex":{"en":"the bottom end of the price range","cn":"最低价位"},"pos":"adjective"},{"en":"a comic character in Shakespeare's play A Midsummer Night's Dream. For most of the play, Bottom has the head of an ass because of a magic trick played by Oberon.","cn":"底部；最下部","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"底；底部","en":"The bottom of something is the lowest or deepest part of it.","ex":{"en":"He sat at the bottom of the stairs","cn":"他坐在最下面的一级楼梯上。"}},{"pos":"ADJ 形容词","cn":"最下方的；底部的；底层的","en":"The bottom thing or layer in a series of things or layers is the lowest one.","ex":{"en":"There's an extra duvet in the bottom drawer of the cupboard.","cn":"橱柜最底层的抽屉里还有一床羽绒被。"}},{"pos":"N-COUNT 可数名词","cn":"底面；内底面；外底面","en":"The bottom of an object is the flat surface at its lowest point. You can also refer to the inside or outside of this surface as the bottom .","ex":{"en":"Spread the onion slices on the bottom of the dish.","cn":"把洋葱片铺在盘底。"}},{"pos":"N-SING 单数名词","cn":"（某市场或产业的)最差状况，低谷","en":"If you say that the bottom has dropped or fallen out of a market or industry, you mean that people have stopped buying the products it sells.","ex":{"en":"The bottom had fallen out of the city's property market.","cn":"该市的房地产市场已陷入极度低迷。"}},{"pos":"N-SING 单数名词","cn":"（街道、花园的）尽头，远端","en":"The bottom of a street or garden is the end farthest away from you or from your house.","ex":{"en":"...the Cathedral at the bottom of the street.","cn":"街道尽头的大教堂"}},{"pos":"N-SING 单数名词","cn":"（桌子的）边角；（床）脚，尾","en":"The bottom of a table is the end farthest away from where you are sitting. The bottom of a bed is the end where you usually rest your feet.","ex":{"en":"Malone sat down on the bottom of the bed.","cn":"马隆在床脚坐下了。"}},{"pos":"N-SING 单数名词","cn":"（组织机构或职业架构的）最底层，基层","en":"The bottom of an organization or career structure is the lowest level in it, where new employees often start.","ex":{"en":"He had worked in the theatre for many years, starting at the bottom.","cn":"他从最基础的干起，已经从事戏剧工作很多年了。"}},{"pos":"N-SING 单数名词","cn":"（调查、测试或联赛中的）表现最差者，最后一名","en":"If someone is bottom or at the bottom in a survey, test, or league their performance is worse than that of all the other people involved.","ex":{"en":"He was always bottom of the class","cn":"他一直是全班的最后一名。"}},{"pos":"N-COUNT 可数名词","cn":"臀部；屁股","en":"Your bottom is the part of your body that you sit on.","ex":{"en":"If there was one thing she could change about her body it would be her bottom.","cn":"如果能对自己的身体做一点改变，那她会选择臀部。"}},{"pos":"N-COUNT 可数名词","cn":"（比基尼泳装的）泳裤；（田径服、睡衣的）裤子","en":"The lower part of a bikini, tracksuit, or pair of pyjamas can be referred to as the bottoms or the bottom.","ex":{"en":"She wore blue tracksuit bottoms.","cn":"她穿了一件蓝色田径裤。"}},{"pos":"PHRASE 短语","cn":"实质上；实际上","en":"You use at bottom to emphasize that you are stating what you think is the real nature of something or the real truth about a situation.","ex":{"en":"The two systems are, at bottom, conceptual models","cn":"这两个系统实质上是两种概念模式。"}},{"pos":"PHRASE 短语","cn":"是…的真正原因；是…的根源","en":"If something is at the bottom of a problem or unpleasant situation, it is the real cause of it.","ex":{"en":"Often I find that anger and resentment are at the bottom of the problem.","cn":"我常常发现愤怒和不满是问题的真正根源。"}},{"pos":"PHRASE 短语","cn":"打心眼里；衷心地","en":"You can say that you mean something from the bottom of your heart to emphasize that you mean it very sincerely.","ex":{"en":"I'm happy, and I mean that from the bottom of my heart","cn":"我很开心，而且是那种发自肺腑的开心。"}},{"pos":"PHRASE 短语","cn":"找到…的真正起因；查寻到…的根源","en":"If you want to get to the bottom of a problem, you want to solve it by finding out its real cause.","ex":{"en":"I have to get to the bottom of this mess.","cn":"我必须查清造成这一混乱局面的真正原因。"}},{"pos":"CONVENTION 惯用语","cn":"干杯","en":"Some people say bottoms up to each other just before drinking an alcoholic drink."},{"pos":"","cn":"","en":"to scrape the bottom of the barrel→see: ;"},{"pos":"","cn":"","en":"相关词组：bottom out"}]},"examples":[{"en":"Their offer to help was at bottom self-centred.","cn":"他们提出要帮忙，这其实还是他们为自己考虑。"},{"en":"The book I want is right at the bottom (= of the pile).","cn":"我想要的书就压在（那堆书的）最下面。"}]},"bored":{"media":{"uk":"media/uk/bored__gb_1.mp3","us":"media/us/bored__us_1.mp3"},"oxford":{"phon":"bɔːd","pos":"adjective","senses":[{"en":"feeling tired and impatient because you have lost interest in somebody/something or because you have nothing to do","cn":"（对某人／事物）厌倦的；烦闷的","ex":{"en":"There was a bored expression on her face.","cn":"她脸上有一种厌倦的表情。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感到厌倦的；感到厌烦的","en":"If you are bored, you feel tired and impatient because you have lost interest in something or because you have nothing to do.","ex":{"en":"I am getting very bored with this entire business.","cn":"我开始对这整件事情感到非常厌倦。"}}]},"examples":[{"en":"The children quickly got bored with staying indoors.","cn":"孩子们在屋子里很快就待不住了。"},{"en":"There was a bored expression on her face.","cn":"她脸上有一种厌倦的表情。"}],"base":"bore"},"bob":{"oxford":{"phon":"bɒb","pos":"verb","senses":[{"en":"to move or make something move quickly up and down, especially in water","cn":"（使在水中）上下快速移动，摆动","g":"[intransitive, transitive]","ex":{"en":"a plastic bottle bobbing along in the current","cn":"一个塑料瓶在水流中漂浮"}},{"en":"to cut somebody’s hair so that it is the same length all the way around","cn":"把（头发）剪成短头发","g":"[transitive]"},{"en":"a quick movement down and up of your head and body","cn":"快速的点头（或鞠躬）","ex":{"en":"a bob of the head","cn":"点头"},"pos":"noun"},{"en":"a hairstyle in which the hair is cut at the same fairly short or medium length all the way around","cn":"（女式）齐短发型","ex":{"en":"She wears her hair in a bob.","cn":"她留齐短发。"},"pos":"noun"},{"en":"an old British coin, the shilling, worth 12 old pence","cn":"先令（英国旧制硬币，等于 12 旧便士）","lab":"informal","ex":{"en":"That'll cost a few bob (= a lot of money).","cn":"那东西很值钱。"},"pos":"noun"},{"en":"a racing sledge (= a vehicle for two or more people that slides over snow)","cn":"有舵雪橇（供两人或以上比赛用）","lab":"British English also","pos":"noun"},{"en":"a first name for boys, short for Robert","cn":"鲍勃（男子名，Robert 缩写）","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（像物体在水中飘浮似的）上下移动，起伏","en":"If something bobs, it moves up and down, like something does when it is floating on water.","ex":{"en":"Huge balloons bobbed about in the sky above","cn":"一个个巨大的气球在头顶的蓝天中漂浮着。"}},{"pos":"VERB 动词","cn":"快速移动；突然消失（或出现）","en":"If you bob somewhere, you move there quickly so that you disappear from view or come into view.","ex":{"en":"She handed over a form, then bobbed down again behind a typewriter.","cn":"她递过来一张表格，随后又立刻埋头在打字机后面忙活起来。"}},{"pos":"VERB 动词","cn":"（快速）点（头）（如打招呼等）","en":"When you bob your head, you move it quickly up and down once, for example when you greet someone.","ex":{"en":"A hostess stood at the top of the steps and bobbed her head at each passenger.","cn":"一位空姐站在最高的阶梯上向每位旅客点头致意。"}},{"pos":"N-COUNT 可数名词","cn":"（英国旧时货币单位）先令","en":"In Britain, people used to refer to a shilling as a bob.","ex":{"en":"I've only got ten bob on me.","cn":"我身上只有10先令。"}},{"pos":"N-COUNT 可数名词","cn":"（女式）齐短发，蘑菇头，波波头","en":"A bob is a fairly short hair style for women in which the hair is the same length all the way round, except for the front."},{"pos":"PHRASE 短语","cn":"零碎物件；小玩意儿","en":"Bits and bobs are small objects or parts of something.","ex":{"en":"The microscope contains a few hundred dollars-worth of electronic bits and bobs.","cn":"这架显微镜内有价值数百美元的电子元件。"}}]},"media":{"uk":"media/uk/bob__gb_1.mp3","us":"media/us/bob__us_1.mp3","img":["media/thumb/bob.jpg"]},"examples":[{"en":"Press here and Bob's your uncle! It's disappeared.","cn":"按一下这里就成了！消失了。"},{"en":"Just copy the disk, and Bob’s your uncle!","cn":"把磁盘拷贝一下就行﹐容易得很！"}]},"bottled":{"media":{"uk":"media/uk/bottled__gb_1.mp3","us":"media/us/bottled__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（气体）瓶装的，罐装的","en":"Bottled gas is kept under pressure in special metal cylinders which can be moved from one place to another."}]},"examples":[{"en":"bottled gas (= sold in metal containers for use in heating and cooking)","cn":"瓶装液化气"},{"en":"bottled beer/water/pickles","cn":"瓶装啤酒/水/腌菜"}],"oxford":{"phon":"ˈbɒtld","pos":"adjective","senses":[{"en":"sold or stored in bottles","cn":"瓶装的","ex":{"en":"bottled beer/water/pickles","cn":"瓶装啤酒／水／腌菜"}}]},"base":"bottle"},"borne":{"media":{"uk":"media/uk/borne__gb_1.mp3","us":"media/us/borne__us_1.mp3"},"oxford":{"phon":"bɔːn","pos":"verb","senses":[{"en":"carried by","cn":"由…携带的","ex":{"en":"waterborne diseases","cn":"由水传染的疾病"}}]},"examples":[{"en":"waterborne diseases","cn":"由水传染的疾病"},{"en":"water-borne diseases","cn":"由水传播的疾病"}],"collins":{"senses":[{"pos":"","cn":"","en":"Borne is the past participle of bear."}]},"base":"bear"},"boarding":{"media":{"uk":"media/uk/boarding__gb_1.mp3","us":"media/us/boarding__us_1.mp3"},"oxford":{"phon":"ˈbɔːdɪŋ","pos":"noun","senses":[{"en":"long pieces of wood that are put together to make a wall, etc.","cn":"（做墙等的）木板；板材"},{"en":"the arrangement by which school students live at their school, going home during the holidays","cn":"（学生的）寄宿","ex":{"en":"boarding fees","cn":"寄宿费用"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"学校寄宿（制）","en":"Boarding is an arrangement by which children live at school during the school term.","ex":{"en":"...the master in charge of boarding","cn":"主管学生住宿的男老师"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（用来建造围墙、门、栅栏的）长条木板","en":"Boarding is long, flat pieces of wood which can be used to make walls, doors, and fences.","ex":{"en":"...the white-painted boarding in the sitting room.","cn":"起居室里粉刷成白色的门板"}}]},"examples":[{"en":"boarding fees","cn":"寄宿费用"},{"en":"Boarding is now taking place at Gate 38. 38","cn":"号登机口现在正在登机。"}],"base":"board"},"bond":{"media":{"uk":"media/uk/bond__gb_1.mp3","us":"media/us/bond__us_1.mp3"},"oxford":{"phon":"bɒnd","pos":"noun","senses":[{"en":"something that forms a connection between people or groups, such as a feeling of friendship or shared ideas and experiences","cn":"纽带；联系；关系；契合","g":"[countable]","sc":"strong connection","ex":{"en":"the bond that links us","cn":"连接我们的纽带"}},{"en":"an agreement by a government or a company to pay you interest on the money you have lent; a document containing this agreement","cn":"债券；公债","g":"[countable]","sc":"money","ex":{"en":"government bonds","cn":"公债。"}},{"en":"a sum of money that is paid as bail","cn":"保释金","g":"[uncountable]","lab":"especially North American English, law，，","sc":"money","ex":{"en":"He was released on $5 000 bond.","cn":"他以 5 000 美元取保释放。"}},{"en":"a legal agreement by which a bank lends you money to buy a house, etc. which you pay back over many years; the sum of money that is lent","cn":"按揭贷款协议；按揭贷款","g":"[countable]","lab":"South African English","sc":"money","ex":{"en":"to pay off a bond","cn":"偿清按揭贷款"}},{"en":"the ropes or chains keeping somebody prisoner; anything that stops you from being free to do what you want","cn":"捆绑犯人的绳索（或镣铐）；羁绊；桎梏","g":"[plural]","lab":"formal","sc":"ropes/chains","ex":{"en":"to release somebody from their bonds","cn":"给某人脱去枷锁"}},{"en":"a legal written agreement or promise","cn":"书面的法律协定（或承诺）","g":"[countable]","lab":"formal","sc":"legal agreement","ex":{"en":"We entered into a solemn bond.","cn":"我们缔结了一项庄严的协定。"}},{"en":"the way in which two things are joined together","cn":"连接；结合","g":"[countable]","sc":"join","ex":{"en":"a firm bond between the two surfaces","cn":"两个面之间的牢固接合"}},{"en":"the way in which atoms are held together in a chemical compound","cn":"键合；键","g":"[countable]","sc":"chemistry"},{"en":"to join two things strongly together; to join strongly to something else","cn":"使牢固结合；把…紧紧地连接到","g":"[transitive, intransitive]","sc":"join together","ex":{"en":"This new glue bonds a variety of surfaces in seconds.","cn":"这种新型胶水可迅速粘牢各种材质的面板。"},"pos":"verb"},{"en":"to develop or create a relationship of trust with somebody","cn":"增强（与某人的）信任关系；建立（与某人的）互信关系","g":"[intransitive, transitive]","sc":"develop relationship","ex":{"en":"Mothers who are depressed sometimes fail to bond with their children.","cn":"患抑郁症的母亲有时无法和孩子建立亲子关系。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（情感的）纽带，契合，关系","en":"A bond between people is a strong feeling of friendship, love, or shared beliefs and experiences that unites them.","ex":{"en":"The experience created a very special bond between us.","cn":"这种经历使我们之间产生了一种很特殊的关系。"}},{"pos":"V-RECIP-ERG","cn":"与…紧密联系；（使）相互联结；（使）建立亲密关系","en":"When people bond with each other, they form a relationship based on love or shared beliefs and experiences. You can also say that people bond or that something bonds them.","ex":{"en":"Belinda was having difficulty bonding with the baby","cn":"贝琳达难以与孩子建立起亲密的关系。"}},{"pos":"N-COUNT 可数名词","cn":"（个人或团体之间的）密切联系","en":"A bond between people or groups is a close connection that they have with each other, for example because they have a special agreement.","ex":{"en":"...the strong bond between church and nation","cn":"教会和国家之间紧密相连的关系"}},{"pos":"N-PLURAL 复数名词","cn":"桎梏；束缚；约束；羁绊","en":"Bonds are feelings, duties, or customs that force you to behave in a particular way.","ex":{"en":"Freed from the bonds of convention and the fear of what others may think, the mind responds with new solutions","cn":"从传统的束缚中解脱出来，不再担心别人会有什么看法，顿时感到柳暗花明。"}},{"pos":"N-COUNT 可数名词","cn":"黏合；连结","en":"A bond between two things is the way in which they stick to one another or are joined in some way.","ex":{"en":"The superglue may not create a bond with some plastics","cn":"强力胶水可能无法粘住某些塑料。"}},{"pos":"V-RECIP-ERG","cn":"与…黏合（或连接）；（使）黏合（或连接）在一起","en":"When one thing bonds with another, it sticks to it or becomes joined to it in some way. You can also say that two things bond together, or that something bonds them together .","ex":{"en":"Diamond may be strong in itself, but it does not bond well with other materials","cn":"钻石本身可能很坚固，但却不易与其他物质很好地黏合。"}},{"pos":"N-COUNT 可数名词","cn":"（政府或公司发行的）公债，债券","en":"When a government or company issues a bond, it borrows money from investors. The certificate which is issued to investors who lend money is also called a bond.","ex":{"en":"Most of it will be financed by government bonds.","cn":"大部分资金将通过发行政府债券来筹措。"}}]},"examples":[{"en":"Mothers who are depressed sometimes fail to bond with their children.","cn":"长期抑郁的母亲有时无法和孩子建立亲子关系。"},{"en":"This new glue bonds a variety of surfaces in seconds.","cn":"这种新型胶水可迅速粘牢各种材质的面板。"}]},"bottle":{"media":{"img":["media/pic/packaging_comp.jpg","media/thumb/bottle.jpg"],"uk":"media/uk/bottle__gb_1.mp3","us":"media/us/bottle__us_1.mp3"},"oxford":{"phon":"ˈbɒtl","pos":"noun","senses":[{"en":"a glass or plastic container, usually round with straight sides and a narrow neck, used especially for storing liquids","cn":"（细颈）瓶子","g":"[countable]","ex":{"en":"a wine/beer/milk/water bottle","cn":"酒瓶；啤酒瓶；奶瓶；水瓶"}},{"en":"the amount contained in a bottle","cn":"一瓶（的量）","g":"[countable]","ex":{"en":"He drank a whole bottle of wine.","cn":"他喝了整整一瓶酒。"}},{"en":"alcoholic drink","cn":"酒","g":"[singular]","lab":"informal","ex":{"en":"After his wife died, he really hit the bottle (= started drinking heavily).","cn":"他妻子死后，他就酗酒了。"}},{"en":"a bottle used to give milk to a baby; the milk from such a bottle (used instead of mother’s milk)","cn":"（婴儿）奶瓶；奶瓶里的奶（非母乳）","g":"[countable, usually singular]","ex":{"en":"It's time for her bottle.","cn":"该给她用奶瓶喂奶了。"}},{"en":"courage or confidence, for example to do something that is dangerous or unpleasant","cn":"勇气；信心","g":"[uncountable]","lab":"British English, informal，，","ex":{"en":"It took a lot of bottle to do that.","cn":"那样做需要很大的勇气。"}},{"en":"to put a liquid into a bottle","cn":"把（液体）装入瓶中","ex":{"en":"The wines are bottled after three years.","cn":"那些酒是在三年之后装瓶的。"},"pos":"verb"},{"en":"to put fruit or vegetables into glass containers in order to preserve them","cn":"把（水果或蔬菜等）装入玻璃瓶储存","ex":{"en":"Keep your empty jam jars for bottling next year’s fruit.","cn":"保留你的空果酱罐，用于装瓶明年的水果。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"瓶子","en":"A bottle is a glass or plastic container in which drinks and other liquids are kept. Bottles are usually round with straight sides and a narrow top.","ex":{"en":"There were two empty beer bottles on the table","cn":"桌子上有两个空啤酒瓶。"}},{"pos":"VERB 动词","cn":"用瓶装；把…装入瓶中","en":"To bottle a drink or other liquid means to put it into bottles after it has been made.","ex":{"en":"This is a large truck which has equipment to automatically bottle the wine.","cn":"这是一辆大型卡车，拥有自动将葡萄酒装瓶的设备。"}},{"pos":"N-COUNT 可数名词","cn":"奶瓶","en":"A bottle is a drinking container used by babies. It has a special rubber part at the top through which they can suck their drink.","ex":{"en":"Gary was holding a bottle to the baby's lips.","cn":"加里正拿着一个奶瓶给婴儿喂奶。"}},{"pos":"VERB 动词","cn":"将（水果）装罐瓶保存","en":"To bottle fruit means to put it into special jars, in order to preserve it.","ex":{"en":"Did she do things like bottling fruit or making jam?","cn":"她干过将水果装瓶或做果酱之类的活计吗？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"勇气；胆量","en":"Bottle is used to refer to courage or boldness.","ex":{"en":"But will anyone have the bottle to go through with it?","cn":"但是谁会有胆量经受这件事？"}},{"pos":"PHRASE 短语","cn":"酗酒","en":"If someone hits the bottle, they drink a lot of alcohol.","ex":{"en":"After my mother died my father started hitting the bottle.","cn":"我母亲死后父亲开始酗酒。"}},{"pos":"PHRASE 短语","cn":"（在最后时刻）因胆怯而放弃，打退堂鼓","en":"If you say that someone has bottled it, you mean that they have lost their courage at the last moment and have not done something they intended to do.","ex":{"en":"He was scheduled to appear on the Russell Harty Show, but bottled it at the last minute.","cn":"他原定参加拉塞尔·哈蒂主持的节目，但在最后时刻打了退堂鼓。"}},{"pos":"","cn":"","en":"相关词组：bottle out bottle up"}]},"examples":[{"en":"The wines are bottled after three years.","cn":"那些酒是在酿了三年之后装瓶的。"},{"en":"After his wife died, he really hit the bottle (= started drinking heavily).","cn":"他妻子死后，他就酗酒了。"}]},"bottles":{"lemma":"bottle","media":{"img":["media/pic/packaging_comp.jpg","media/thumb/bottle.jpg"],"uk":"media/uk/bottle__gb_1.mp3","us":"media/us/bottle__us_1.mp3"}},"bombs":{"lemma":"bomb","media":{"uk":"media/uk/bomb__gb_1.mp3","us":"media/us/bomb__us_1.mp3"}},"body":{"media":{"img":["media/ldoce/img/body.jpg","media/pic/body_labels_comp.jpg"],"uk":"media/uk/body__gb_1.mp3","us":"media/us/body__us_1.mp3"},"oxford":{"phon":"ˈbɒdi","pos":"noun","senses":[{"en":"the whole physical structure of a human or an animal","cn":"身体；躯体","g":"[countable]","sc":"of person/animal","ex":{"en":"The human body is a complex structure.","cn":"人体是一个复杂的结构。"}},{"en":"the main part of a body not including the head, or not including the head, arms and legs","cn":"躯干","g":"[countable]","sc":"of person/animal","ex":{"en":"She had injuries to her head and body.","cn":"她的头上和身上都有伤。"}},{"en":"the body of a dead person or animal","cn":"尸体；死尸","g":"[countable]","sc":"of person/animal","ex":{"en":"a dead body","cn":"一具尸体"}},{"en":"the main part of something, especially a building, a vehicle or a book, an article, etc.","cn":"（尤指建筑、车辆或书、文章等的）主体，主要部分","g":"[singular]","sc":"main part","ex":{"en":"the body of a plane (= the central part where the seats are)","cn":"飞机机身"}},{"en":"a group of people who work or act together, often for an official purpose, or who are connected in some other way","cn":"团体；社团；群体","g":"[countable + singular or plural verb]","sc":"group of people","ex":{"en":"a regulatory/an advisory body","cn":"监管／咨询机构"}},{"en":"a large amount or collection of something","cn":"大量；大批；大堆","g":"[countable]","sc":"large amount","ex":{"en":"a vast body of evidence/information/research","cn":"大量证据／信息／研究"}},{"en":"an object","cn":"物体","g":"[countable]","lab":"formal","sc":"object","ex":{"en":"heavenly bodies (= stars, planets, etc.)","cn":"天体（恒星、行星等）"}},{"en":"the full strong taste of alcoholic drinks or the thick healthy quality of somebody’s hair","cn":"（酒的）浓香，香醇；（头发的）浓密","g":"[uncountable]","sc":"of drink/hair","ex":{"en":"a wine with plenty of body","cn":"浓郁香醇的葡萄酒"}},{"en":"having the type of body mentioned","cn":"有…的身体（或浓郁味道等）的","sc":"-bodied","ex":{"en":"full-bodied red wines","cn":"醇厚的红葡萄酒"}},{"en":"a piece of clothing that fits tightly over the upper body and bottom, usually fastening between the legs","cn":"女紧身衣（通常止于大腿根）","g":"[countable]","lab":"British English","sc":"clothing"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"身体；人体","en":"Your body is all your physical parts, including your head, arms, and legs.","ex":{"en":"The largest organ in the body is the liver.","cn":"人体最大的器官是肝脏。"}},{"pos":"N-COUNT 可数名词","cn":"躯干（不包括头和四肢）；躯体","en":"You can also refer to the main part of your body, except for your arms, head, and legs, as your body .","ex":{"en":"Lying flat on the floor, twist your body on to one hip and cross your upper leg over your body.","cn":"平躺在地板上，屈体侧躺，把上面的一条腿搭在身上。"}},{"pos":"N-COUNT 可数名词","cn":"（人的）尸体","en":"You can refer to a person's dead body as a body .","ex":{"en":"Officials said they had found no traces of violence on the body of the politician.","cn":"官员称他们没有在这位政治家的尸体上发现暴力侵犯的痕迹。"}},{"pos":"N-COUNT 可数名词","cn":"团体；机构；组织","en":"A body is an organized group of people who deal with something officially.","ex":{"en":"...the Chairman of the policemen's representative body, the Police Federation.","cn":"警察的代表机构“警察协会”的主席"}},{"pos":"N-COUNT 可数名词","cn":"一群；一批","en":"A body of people is a group of people who are together or who are connected in some way.","ex":{"en":"...that large body of people which teaches other people how to teach.","cn":"向别人传授教学方法的那一大批人"}},{"pos":"N-SING 单数名词","cn":"（建筑物、文件等的）主体，主要部分","en":"The body of something such as a building or a document is the main part of it or the largest part of it.","ex":{"en":"The main body of the church had been turned into a massive television studio","cn":"该教堂的主体部分已被改造成了一个大型电视演播室。"}},{"pos":"N-COUNT 可数名词","cn":"（汽车或飞机的）车身，机身","en":"The body of a car or aeroplane is the main part of it, not including its engine, wheels, or wings.","ex":{"en":"The only shade was under the body of the plane.","cn":"唯一的阴凉处是飞机机身下面。"}},{"pos":"N-COUNT 可数名词","cn":"一片，一泓（水域）","en":"A body of water is a large area of water, such as a lake or a sea.","ex":{"en":"It is probably the most polluted body of water in the world.","cn":"这很可能是世界上受污染最严重的一片水域。"}},{"pos":"N-COUNT 可数名词","cn":"大量（信息）","en":"A body of information is a large amount of it.","ex":{"en":"An increasing body of evidence suggests that all of us have cancer cells in our bodies at times during our lives.","cn":"越来越多的证据表明，我们所有人一生中体内时有癌细胞存在。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（酒的）醇度，浓郁，劲儿","en":"If you say that an alcoholic drink has body, you mean that it has a full and strong flavour.","ex":{"en":"...a dry wine with good body.","cn":"香醇的干葡萄酒"}},{"pos":"N-COUNT 可数名词","cn":"同bodysuit","en":"A body is the same as a bodysuit ."},{"pos":"PHRASE 短语","cn":"（用于强调强烈反对）除非我死了，休想","en":"You can say over my dead body to emphasize that you feel very strongly that something should not happen, and that you will do everything you can to prevent it.","ex":{"en":"'We'll have her over for dinner.' — 'Over my dead body!'","cn":"“我们要请她过来吃饭。”——“休想！”"}},{"pos":"PHRASE 短语","cn":"全身心地；全心全意","en":"You use body and soul to mean every part of you, including your mind and your emotions.","ex":{"en":"He dedicated himself body and soul to the education of young men","cn":"他全身心地投入到年轻人的教育中。"}},{"pos":"PHRASE 短语","cn":"维持生计；挣钱糊口","en":"If you keep body and soul together, you have enough money to provide what you need to live.","ex":{"en":"He at first kept body and soul together by selling cartoons to the humorous papers.","cn":"他最初通过向幽默搞笑类报纸出售卡通漫画维持生计。"}}]},"examples":[{"en":"recognized professional bodies such as the Law Association","cn":"诸如律师公会之类的获得承认的专业团体"},{"en":"The family of the missing girl has been called in by the police to identify the body.","cn":"失踪女孩的家人已被警察叫来认尸。"}]},"bow":{"media":{"img":["media/ldoce/img/bow.jpg","media/pic/bow1_comp.jpg"],"uk":"media/uk/bow__gb_1.mp3","us":"media/us/bow__us_1.mp3"},"oxford":{"phon":"baʊ","pos":"verb","senses":[{"en":"to move your head or the top half of your body forwards and downwards as a sign of respect or to say hello or goodbye","cn":"鞠躬；点头","g":"[intransitive]","ex":{"en":"He bowed low to the assembled crowd.","cn":"他向集结的人群深深地鞠了一躬。"}},{"en":"to move your head forwards and downwards","cn":"低（头）；垂（首）","g":"[transitive]","ex":{"en":"She bowed her head in shame.","cn":"她羞愧地低下了头。"}},{"en":"to bend or make something bend","cn":"（使）弯曲","g":"[intransitive, transitive]","ex":{"en":"The pines bowed in the wind.","cn":"松树被风吹弯了。"}},{"en":"the act of bending your head or the upper part of your body forward in order to say hello or goodbye to somebody or to show respect","cn":"鞠躬；弯腰行礼","ex":{"en":"She gave a slight bow of her head in greeting.","cn":"她微微低头打招呼。"},"pos":"noun"},{"en":"the front part of a boat or ship","cn":"船头；艏","g":"[plural]","ex":{"en":"A huge whale crossed our bows.","cn":"一只巨鲸从我们的船头前穿过。"},"pos":"noun"},{"en":"a weapon used for shooting arrows, consisting of a long curved piece of wood or metal with a tight string joining its ends","cn":"弓","ex":{"en":"He was armed with a bow and arrow.","cn":"他佩带着弓箭。"},"pos":"noun"},{"en":"a knot with two loops and two loose ends which is used for decoration on clothes, in hair, etc. or for tying shoes","cn":"蝴蝶结","ex":{"en":"to tie your shoelaces in a bow","cn":"把鞋带打成蝴蝶结"},"pos":"noun"},{"en":"a long thin piece of wood with thin string stretched along it, used for playing musical instruments such as the violin","cn":"琴弓","ex":{"en":"She drew the bow across the strings.","cn":"她将琴弓拉过琴弦。"},"pos":"noun"},{"en":"to use a bow to play a musical instrument that has strings","cn":"用琴弓拉奏（弦乐器）"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"鞠躬，欠身（打招呼或表示恭敬）","en":"When you bow to someone, you briefly bend your body towards them as a formal way of greeting them or showing respect.","ex":{"en":"They bowed low to Louis and hastened out of his way","cn":"他们向路易斯深深鞠躬，并忙不迭地给他让道。"}},{"pos":"VERB 动词","cn":"低（头）；俯（首）","en":"If you bow your head, you bend it downwards so that you are looking towards the ground, for example because you want to show respect or because you are thinking deeply about something.","ex":{"en":"The Colonel bowed his head and whispered a prayer of thanksgiving","cn":"这位上校低头轻声做感恩祈祷。"}},{"pos":"VERB 动词","cn":"向（压力或他人的意愿）让步；屈从于；屈服于","en":"If you bow to pressure or to someone's wishes, you agree to do what they want you to do.","ex":{"en":"Some shops are bowing to consumer pressure and stocking organically grown vegetables","cn":"一些商店迫于顾客的压力，开始供应有机蔬菜。"}},{"pos":"V-PASSIVE 被动动词","cn":"使沮丧；使不安；使无望","en":"If you are bowed by something, you are made unhappy and anxious by it, and lose hope.","ex":{"en":"...their determination not to be bowed in the face of the allied attacks.","cn":"他们绝不在联合攻击面前丧失斗志的坚定决心"}},{"pos":"PHRASE 短语","cn":"(为形势所迫）低头，屈服","en":"If someone bows to the inevitable and does something that they do not want to do, they do it, because circumstances force them to do it.","ex":{"en":"He bowed to the inevitable and announced that he was willing to resume diplomatic relations.","cn":"迫于形势他只好宣称愿意恢复外交关系。"}},{"pos":"PHRASE 短语","cn":"（演员或表演者向观众）鞠躬致意","en":"If an actor or entertainer takes a bow, he or she shows appreciation of an audience's applause by bowing to them.","ex":{"en":"They ran to the center of the tent to take their bows.","cn":"他们跑到帐篷中央鞠躬致意。"}},{"pos":"","cn":"","en":"相关词组：bow down bow out"},{"pos":"N-COUNT 可数名词","cn":"船首；船头","en":"The front part of a ship is called the bow or the bows. The plural bows can be used to refer either to one or to more than one of these parts.","ex":{"en":"The waves were about five feet now, and the bow of the boat was leaping up and down.","cn":"那时浪高大约有5英尺，船头在上下颠簸。"}},{"pos":"N-COUNT 可数名词","cn":"（鞋带或丝带系成的）蝴蝶结","en":"A bow is a knot with two loops and two loose ends that is used in tying shoelaces and ribbons.","ex":{"en":"Add a length of ribbon tied in a bow.","cn":"再用一段丝带，系个蝴蝶结。"}},{"pos":"N-COUNT 可数名词","cn":"弓","en":"A bow is a weapon for shooting arrows which consists of a long piece of curved wood with a string attached to both its ends.","ex":{"en":"Some of the raiders were armed with bows and arrows.","cn":"其中一些袭击者身背弓箭。"}},{"pos":"N-COUNT 可数名词","cn":"（小提琴等弦乐器的）弓，琴弓","en":"The bow of a violin or other stringed instrument is a long thin piece of wood with fibres stretched along it, which you move across the strings of the instrument in order to play it."},{"pos":"","cn":"","en":"another string to your bow→see: ;"}]},"examples":[{"en":"Her hair was tied back in a neat bow.","cn":"她的头发扎在脑后打了个整齐的蝴蝶结。"},{"en":"She has finally decided it's time to bow out of international tennis.","cn":"她最终认定是退出世界网坛的时候了。"}]},"board":{"media":{"uk":"media/uk/board__gb_1.mp3","us":"media/us/board__us_1.mp3","img":["media/ldoce/img/chopping_board.jpg"]},"oxford":{"phon":"bɔːd","pos":"noun","senses":[{"en":"a long thin piece of strong hard material, especially wood, used, for example, for making floors, building walls and roofs and making boats","cn":"板；（尤指）木板","g":"[countable, uncountable]","sc":"piece of wood, etc.","ex":{"en":"He had ripped up the carpet, leaving only the bare boards.","cn":"他用力扯去了地毯，只剩下裸露的地板。"}},{"en":"a piece of wood, or other strong material, that is used for a special purpose","cn":"…用木板（或板材）","g":"[countable]","lab":"British English","sc":"piece of wood, etc.","ex":{"en":"a whiteboard","cn":"白板"}},{"en":"the piece of equipment on which somebody stands in various water sports and in snowboarding and skateboarding","cn":"（水上、冰雪运动等的）滑板","g":"[countable]","sc":"in sports","ex":{"en":"You kick-turn with both feet on the board.","cn":"你用双脚踩在板上进行踢腿转身。"}},{"en":"a group of people who have power to make decisions and control a company or other organization","cn":"（公司或其他机构的）董事会，委员会，理事会","g":"[countable + singular or plural verb]","lab":"North American English","sc":"group of people","ex":{"en":"The board is/are unhappy about falling sales.","cn":"董事会对销售额下降感到不满。"}},{"en":"used in the name of some organizations","cn":"（用于机构名称）","g":"[countable]","sc":"organization","ex":{"en":"the Welsh Tourist Board (= responsible for giving tourist information)","cn":"威尔士旅游局"}},{"en":"the meals that are provided when you stay in a hotel, guest house, etc.; what you pay for the meals","cn":"（旅馆、招待所等提供的）伙食，膳食；膳食费用","g":"[uncountable]","sc":"meals","ex":{"en":"He pays £90 a week board and lodging.","cn":"他每周的膳宿花费为 90 英镑。"}},{"en":"exams that you take when you apply to go to college in the US","cn":"（美国大学的）入学考试","g":"[plural]","lab":"old-fashioned, US English，，","sc":"exams"},{"en":"the stage in a theatre","cn":"舞台","g":"[plural]","lab":"old-fashioned, informal，，","sc":"in theatre","ex":{"en":"His play is on the boards on Broadway.","cn":"他的戏剧搬上了百老汇的舞台。"}},{"en":"the low wooden wall surrounding the area where a game of ice hockey is played","cn":"（冰球场周围的）界墙","g":"[plural]","lab":"North American English","sc":"ice hockey","ex":{"en":"The puck went wide, hitting the boards.","cn":"冰球击偏了，打在了界墙上。"}},{"en":"to get on a ship, train, plane, bus, etc.","cn":"上船（或火车、飞机、公共汽车等）","g":"[intransitive, transitive]","lab":"formal","sc":"get on plane/ship, etc.","ex":{"en":"Passengers are waiting to board.","cn":"乘客们正在候机。"},"pos":"verb"},{"en":"when a plane or ship is boarding, it is ready for passengers to get on","cn":"让乘客登机（或上船等）","g":"[intransitive]","sc":"get on plane/ship, etc.","ex":{"en":"Flight BA193 for Paris is now boarding at Gate 37.","cn":"乘 BA193 航班飞往巴黎的乘客请于 37 号登机口登机。"},"pos":"verb"},{"en":"to live and take meals in somebody’s home, in return for payment","cn":"付费（在某人家里）膳宿","g":"[intransitive]","sc":"live somewhere","ex":{"en":"She always had one or two students boarding with her.","cn":"她家总有一两名寄宿学生。"},"pos":"verb"},{"en":"to live at a school during the school year","cn":"（在学校）寄宿","g":"[intransitive]","sc":"live somewhere","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（有特殊用途的）木板，塑料板，板材","en":"A board is a flat, thin, rectangular piece of wood or plastic which is used for a particular purpose.","ex":{"en":"...a chopping board.","cn":"砧板"}},{"pos":"N-COUNT 可数名词","cn":"（下棋等用的）木板，硬纸板，棋盘","en":"A board is a square piece of wood or stiff cardboard that you use for playing games such as chess.","ex":{"en":"...a draughts board","cn":"跳棋棋盘"}},{"pos":"N-COUNT 可数名词","cn":"黑板；告示牌","en":"You can refer to a blackboard or a noticeboard as a board.","ex":{"en":"He wrote a few more notes on the board.","cn":"他在黑板上又写了几条注释。"}},{"pos":"N-COUNT 可数名词","cn":"（用来铺地板、筑围墙等的）长条木板","en":"Boards are long flat pieces of wood which are used, for example, to make floors or walls.","ex":{"en":"The floor was draughty bare boards.","cn":"地面铺的是透气性好的实木地板。"}},{"pos":"N-COUNT 可数名词","cn":"董事会；理事会","en":"The board of a company or organization is the group of people who control it and direct it.","ex":{"en":"Arthur wants to put his recommendation before the board at a meeting tomorrow.","cn":"阿瑟希望在明天的会议上把自己的建议书提交董事会。"}},{"pos":"N-COUNT 可数名词","cn":"（用于机构名称中）局，所，中心，委员会","en":"Board is used in the names of various organizations which are involved in dealing with a particular kind of activity.","ex":{"en":"The Scottish Tourist Board said 33,000 Japanese visited Scotland last year.","cn":"苏格兰旅游局宣称去年有33,000名日本人到苏格兰旅游。"}},{"pos":"VERB 动词","cn":"上，登上（火车、轮船或飞机）","en":"When you board a train, ship, or aircraft, you get on it in order to travel somewhere.","ex":{"en":"I boarded the plane bound for England.","cn":"我登上了飞往英格兰的飞机。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（旅馆等提供的）膳食，伙食","en":"Board is the food which is provided when you stay somewhere, for example in a hotel.","ex":{"en":"Free room and board are provided for all hotel staff.","cn":"宾馆的所有员工都可享受免费膳宿。"}},{"pos":"PHRASE 短语","cn":"（协议或交易）合法诚信的，公开的，光明正大的","en":"An arrangement or deal that is above board is legal and is being carried out honestly and openly.","ex":{"en":"All I knew about were Antony's own financial dealings, which were always above board.","cn":"据我所知，安东尼经手的金融交易一直是公开透明的。"}},{"pos":"PHRASE 短语","cn":"影响全体地；全面地","en":"If a policy or a situation applies across the board, it affects everything or everyone in a particular group.","ex":{"en":"There are hefty charges across the board for one-way rental","cn":"各处对单程租赁的收费都很高。"}},{"pos":"PHRASE 短语","cn":"被否决；被忽视；落空","en":"If something goes by the board, it is rejected or ignored, or is no longer possible.","ex":{"en":"It's a case of not what you know but who you know in this world today and qualifications quite go by the board.","cn":"在当今这个世界，重要的不是你知道什么而是你认识谁，能力才干根本派不上用场。"}},{"pos":"PHRASE 短语","cn":"在火车（或轮船、飞机）上","en":"When you are on board a train, ship, or aircraft, you are on it or in it.","ex":{"en":"They arrived at Gatwick airport on board a plane chartered by the Italian government","cn":"他们乘坐意大利政府的包机到达盖特威克机场。"}},{"pos":"PHRASE 短语","cn":"（在竞赛或选举中）取得压倒性胜利，大获全胜","en":"If someone sweeps the board in a competition or election, they win nearly everything that it is possible to win.","ex":{"en":"Spain swept the board in boys' team competitions.","cn":"西班牙队在男子团体比赛中大获全胜。"}},{"pos":"PHRASE 短语","cn":"接受（主意）；理解（问题）","en":"If you take on board an idea or a problem, you begin to accept it or understand it.","ex":{"en":"I hope that they will take on board some of what you have said.","cn":"我希望他们能采纳你们所提出的部分想法。"}},{"pos":"","cn":"","en":"相关词组：board out board up"}]},"examples":[{"en":"All her efforts to be polite went by the board and she started to shout.","cn":"她力图保持和颜悦色的一切努力都白费了，于是她开始大喊大叫。"},{"en":"Flight BA193 for Paris is now boarding at Gate 37. * BA193","cn":"次往巴黎航班的乘客现在可以在 37 号登机口登机。"}]},"bounce":{"oxford":{"phon":"baʊns","pos":"verb","senses":[{"en":"if something bounces or you bounce it, it moves quickly away from a surface it has just hit or you make it do this","cn":"（使）弹起，弹跳；反射","g":"[intransitive, transitive]","lab":"figurative","sc":"move off surface","ex":{"en":"The ball bounced twice before he could reach it.","cn":"球弹跳两次他才接到。"}},{"en":"to jump up and down on something","cn":"（在…上）跳动，蹦","g":"[intransitive]","sc":"move up and down","ex":{"en":"She bounced up and down excitedly on the bed.","cn":"她兴奋地在床上蹦蹦跳跳。"}},{"en":"to move a child up and down while they are sitting on your knee in order to entertain them","cn":"（放在膝上的孩子）摇逗；逗弄","g":"[transitive]","sc":"move up and down","ex":{"en":"I bounced the baby on my knee while Pete did the dishes.","cn":"皮特洗碗时，我在摇逗膝上的孩子。"}},{"en":"to move up and down; to move something up and down","cn":"（使）上下晃动","g":"[intransitive, transitive]","sc":"move up and down","ex":{"en":"Her hair bounced as she walked.","cn":"她走起路来头发上下晃动。"}},{"en":"to move up and down in a particular direction","cn":"（朝某个方向）颠簸行进","g":"[intransitive]","sc":"move up and down","ex":{"en":"The bus bounced down the hill.","cn":"公共汽车颠簸着开下山去。"}},{"en":"to move somewhere in a lively and cheerful way","cn":"活泼兴奋地走，蹦蹦跳跳地去（到某处）","g":"[intransitive]","sc":"move with energy","ex":{"en":"He bounced across the room to greet them.","cn":"他兴奋地冲过房间去迎接他们。"}},{"en":"if a cheque bounces, or a bank bounces it, the bank refuses to accept it because there is not enough money in the bank account to pay it","cn":"（支票等）被拒付退回；拒付，退回（支票等）","g":"[intransitive, transitive]","lab":"informal","sc":"cheque"},{"en":"to tell somebody your ideas in order to find out what they think about them","cn":"（向某人）试探地透露（主意）","g":"[transitive]","sc":"ideas","ex":{"en":"He bounced ideas off colleagues everywhere he went.","cn":"他在同事中逢人便试探地大讲他的想法。"}},{"en":"if an email bounces or the system bounces it, it returns to the person who sent it because the system cannot deliver it","cn":"（电子邮件）被退回；退回（电子邮件）","g":"[intransitive, transitive]","sc":"computing","ex":{"en":"I tried to send her an email but it bounced.","cn":"我试图给她发一封电子邮件，但被退回了。"}},{"en":"to force somebody to leave a job, team, place, etc.","cn":"解雇；开除；撵走；逐出","g":"[transitive]","lab":"especially North American English, informal，，","sc":"make somebody leave","ex":{"en":"He was soon bounced from the post.","cn":"他不久被解职。"}},{"en":"to leave a place or group of people","cn":"离开","g":"[intransitive]","lab":"informal","sc":"leave","ex":{"en":"All right, cool, we'll bounce.","cn":"行，没问题，我们走。"}},{"en":"the action of bouncing","cn":"弹跳；跳动","g":"[countable]","lab":"North American English","sc":"movement","ex":{"en":"one bounce of the ball","cn":"球的一次弹起"},"pos":"noun"},{"en":"the ability to bounce or to make something bounce","cn":"弹性；反弹力","g":"[uncountable]","sc":"movement","ex":{"en":"There's not much bounce left in these balls.","cn":"这些球已没有多少弹性了。"},"pos":"noun"},{"en":"the energy that a person has","cn":"活力；精力","g":"[uncountable, countable]","sc":"energy","ex":{"en":"All her old bounce was back.","cn":"她完全恢复了以往的活力。"},"pos":"noun"},{"en":"the quality in a person’s hair that shows that it is in good condition and means that it does not lie flat","cn":"富有弹性；蓬松","g":"[uncountable]","sc":"of hair","ex":{"en":"thin fine hair, lacking in bounce","cn":"没有弹性、稀疏纤细的头发"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使)弹起；（使)反弹","en":"When an object such as a ball bounces or when you bounce it, it moves upwards from a surface or away from it immediately after hitting it.","ex":{"en":"I bounced a ball against the house","cn":"我对着房子打球。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（体育场地的）弹性，弹力","en":"The bounce of a sports field is the condition of it, which determines how high a ball will bounce on it."},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（声或光）反射","en":"If sound or light bounces off a surface or is bounced off it, it reaches the surface and is reflected back.","ex":{"en":"Your arms and legs need protection from light bouncing off glass","cn":"需要保护你的手臂和双腿免受玻璃反射光线的照射。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）跳动；（使）上下晃动","en":"If something bounces or if something bounces it, it swings or moves up and down.","ex":{"en":"Her long black hair bounced as she walked","cn":"她走路时长长的黑发随之飘动。"}},{"pos":"VERB 动词","cn":"(在柔软物体表面）跳上跳下，蹦跳，弹跳","en":"If you bounce on a soft surface, you jump up and down on it repeatedly.","ex":{"en":"She lets us do anything, even bounce on our beds.","cn":"她放任我们随心所欲，甚至连我们在床上蹦跳她也不管。"}},{"pos":"VERB 动词","cn":"（用膝盖）颠动（孩子）","en":"If you bounce a child on your knee, you lift him or her up and down quickly and repeatedly for fun.","ex":{"en":"Patsy had picked up the baby and was bouncing him on her knee.","cn":"帕齐抱起婴儿放在膝上颠动着。"}},{"pos":"VERB 动词","cn":"蹦蹦跳跳地去","en":"If someone bounces somewhere, they move there in an energetic way, because they are feeling happy.","ex":{"en":"Moira bounced into the office.","cn":"莫伊拉蹦蹦跳跳地进了办公室。"}},{"pos":"VERB 动词","cn":"向…透露（想法）；与…探讨（想法）","en":"If you bounce your ideas off someone, you tell them to that person, in order to find out what they think about them.","ex":{"en":"It was good to bounce ideas off another mind","cn":"与别人谈谈自己的想法是有益的。"}},{"pos":"VERB 动词","cn":"迫使…做（不情愿做的事）","en":"If someone bounces you into doing something you do not really want to do, they make you do it, usually by starting a process which cannot easily be stopped.","ex":{"en":"Attempts have been made to bounce member states into decisions with major financial implications.","cn":"已经努力迫使成员国制定具有重大金融意义的决策。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（支票）被拒付；（银行）拒付（支票）","en":"If a cheque bounces or if a bank bounces it, the bank refuses to accept it and pay out the money, because the person who wrote it does not have enough money in their account.","ex":{"en":"Our only complaint would be if the cheque bounced","cn":"我们唯一的不满就是，如果支票被拒付…"}},{"pos":"VERB 动词","cn":"（电子邮件等）被退回","en":"If an e-mail or other electronic message bounces, it is returned to the person who sent it because the address was wrong or because of a problem with one of the computers involved in sending it."},{"pos":"","cn":"","en":"相关词组：bounce back"}]},"media":{"uk":"media/uk/bounce__gb_1.mp3","us":"media/us/bounce__us_1.mp3"},"examples":[{"en":"He's had a lot of problems, but he always seems to bounce back pretty quickly.","cn":"他遭遇过很多挫折，但他似乎总能很快地振作起来。"},{"en":"The airline's shares have bounced back from two days of heavy losses.","cn":"航空公司的股票狂跌两天后已经反弹回来。"}]},"bot":{"oxford":{"phon":"bɒt","pos":"noun","senses":[{"en":"a computer program that runs automated tasks over the internet","cn":"自动程序","ex":{"en":"Developers can program bots to provide anything from automated subscriptions to content such as weather and traffic updates.","cn":"开发人员可以编写机器人程序，提供从自动订阅天气和交通更新等内容。"}},{"en":"a robot","cn":"机器人"},{"en":"a computer program that creates fake social media accounts and communicates with other users","cn":"社交媒体机器人（计算机程序，能创建虚假社交媒体账号并与其他用户互动）","ex":{"en":"It's becoming harder and harder to detect which accounts are real and which are bots.","cn":"要识别出哪些是真人账号，哪些是机器人账号，变得越来越难。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指因特网上的）自动程序，机器人程序","en":"A bot is a computer program that carries out tasks for other programs or users, especially on the Internet."}]},"media":{"uk":"media/uk/bot__gb_1.mp3","us":"media/us/bot__us_1.mp3"}},"bookmarks":{"lemma":"bookmark"},"both":{"media":{"uk":"media/uk/both__gb_1.mp3","us":"media/us/both__us_1.mp3"},"oxford":{"phon":"bəʊθ","pos":"determiner, pronoun","senses":[{"en":"used with plural nouns to mean ‘the two’ or ‘the one as well as the other’","cn":"（与复数名词连用）两个，两个都","ex":{"en":"Both women were French.","cn":"两名妇女都是法国人。"}},{"en":"not only… but also…","cn":"不仅…而且…；…和…都","ex":{"en":"Both his mother and his father will be there.","cn":"他父母二人都要去那里。"}}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"两个；两个都","en":"You use both when you are referring to two people or things and saying that something is true about each of them.","ex":{"en":"She cried out in fear and flung both arms up to protect her face","cn":"她吓得大叫，并且抡起双臂护住了自己的脸。"}},{"pos":"CONJ-COORD 连词","cn":"不仅…而且…；…和…都；既…又…","en":"You use the structure both...and when you are giving two facts or alternatives and emphasizing that each of them is true or possible.","ex":{"en":"Now women work both before and after having their children","cn":"现在妇女在生孩子前后都要去工作。"}}]},"examples":[{"en":"For this job you will need a good knowledge of both Italian and Spanish.","cn":"担任这项工作需要精通意大利语和西班牙语。"},{"en":"I talked to the women. Both of them were French/They were both French.","cn":"我和两位妇女交谈了，她们都是法国人。"}]},"borders":{"lemma":"border","media":{"uk":"media/ldoce/hwd/bre/d/p028-000002523.mp3","us":"media/ldoce/hwd/ame/d/p028-000002523.mp3"}},"boot":{"oxford":{"phon":"buːt","pos":"noun","senses":[{"en":"a strong shoe that covers the foot and ankle and often the lower part of the leg","cn":"靴子","lab":"British English","ex":{"en":"walking boots","cn":"便靴"}},{"en":"the space at the back of a car that you put bags, cases, etc. in","cn":"（汽车后部的）行李厢","lab":"British English","ex":{"en":"I'll put the luggage in the boot.","cn":"我去把行李放进后车厢。"}},{"en":"a quick hard kick","cn":"猛踢","g":"[usually singular]","lab":"informal","ex":{"en":"He gave the ball a tremendous boot.","cn":"他抽起脚猛踢了一下球。"}},{"en":"a device that is attached to the wheel of a car that has been parked illegally, so that it cannot be driven away","cn":"车轮锁（用于锁住违章停放的车辆）","lab":"both North American English"},{"en":"to kick somebody/something hard with your foot","cn":"猛踢","g":"[transitive]","ex":{"en":"He booted the ball clear of the goal.","cn":"他一个大脚把球踢离了球门。"},"pos":"verb"},{"en":"to prepare a computer for use by loading its operating system; to be prepared in this way","cn":"装入操作系统；启动（计算机）","g":"[intransitive, transitive]","lab":"computing","pos":"verb"},{"en":"if you or your car is booted, a piece of equipment is fixed to the car’s wheel so that you cannot drive it away, usually because the car is illegally parked","cn":"在（通常为非法停放的汽车）车轮上装制动装置","g":"[transitive]","lab":"North American English, informal，，","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"靴子","en":"Boots are shoes that cover your whole foot and the lower part of your leg.","ex":{"en":"He sat in a kitchen chair, reached down and pulled off his boots","cn":"他坐到厨房的椅子上，俯身脱掉了靴子。"}},{"pos":"N-COUNT 可数名词","cn":"(步行、运动等时穿的）厚底短筒靴","en":"Boots are strong, heavy shoes which cover your ankle and which have thick soles. You wear them to protect your feet, for example when you are walking or taking part in sport.","ex":{"en":"The soldiers' boots resounded in the street","cn":"士兵的军靴声在街上回荡。"}},{"pos":"VERB 动词","cn":"猛踢（球等）","en":"If you boot something such as a ball, you kick it hard.","ex":{"en":"He booted the ball 40 yards back up field","cn":"他一脚踢出40码远，把球踢回前场。"}},{"pos":"N-COUNT 可数名词","cn":"（汽车的）行李箱，后备箱","en":"The boot of a car is a covered space at the back or front, in which you carry things such as luggage and shopping.","ex":{"en":"He opened the boot to put my bags in","cn":"他打开行李箱把我带的包放了进去。"}},{"pos":"VERB 动词","cn":"（用丹佛锁扣）锁住（汽车）","en":"To boot a car means to fit a Denver boot to one of its wheels so that it cannot be driven away.","ex":{"en":"'If we're gettin' booted, we sure as hell ain't leavin' it for the locals.'","cn":"“如果我们的车轮被锁住，我们绝不会把车留给当地人。”"}},{"pos":"PHRASE 短语","cn":"被解雇；被抛弃；","en":"If you get the boot or are given the boot, you are told that you are not wanted any more, either in your job or by someone you are having a relationship with.","ex":{"en":"She was a disruptive influence, and after a year or two she got the boot","cn":"她总是影响正常的工作，一两年后便被解雇了。"}},{"pos":"PHRASE 短语","cn":"（在某人已感到虚弱或苦恼时）说刻薄伤人的话，落井下石","en":"If someone puts the boot in, they attack another person by saying something cruel, often when the person is already feeling weak or upset."},{"pos":"PHRASE 短语","cn":"而且；另外；加之","en":"You can say to boot to emphasize that you have added something else to something or to a list of things that you have just said.","ex":{"en":"He is making money and receiving free advertising to boot!","cn":"他既挣了钱，又做了免费的广告！"}},{"pos":"","cn":"","en":"相关词组：boot out boot up"}]},"media":{"img":["media/pic/boots_shoes_comp.jpg","media/thumb/boot.jpg"],"uk":"media/uk/boot__gb_1.mp3","us":"media/us/boot__us_1.mp3"},"examples":[{"en":"He was a vegetarian, and a fussy one to boot.","cn":"他是个素食主义者，而且过于讲究。"},{"en":"He booted the ball clear of the goal.","cn":"他一个大脚把球踢离了球门。"}]},"booth":{"media":{"uk":"media/uk/booth__gb_1.mp3","us":"media/us/booth__us_1.mp3"},"oxford":{"phon":"buːð","pos":"noun","senses":[{"en":"a small place with walls or sides where you can do something privately, for example make a phone call or vote","cn":"小隔间（如电话亭、投票间等）","ex":{"en":"a phone booth","cn":"电话亭"}},{"en":"a small tent or temporary structure at a market, an exhibition or a fairground, where you can buy things, get information or watch something","cn":"临时货摊（或放映棚等）","ex":{"en":"The stalls and booths were doing a brisk trade.","cn":"那些售货亭和临时摊位的生意很红火。"}},{"en":"a place to sit in a restaurant which consists of two long seats with a table between them","cn":"（餐馆中的）火车座，卡座"},{"en":"a place in a sports ground, theatre, etc. where the people who introduce or describe an event for radio or television sit","cn":"（体育场、剧院等的）播音间，解说席","lab":"North American English","ex":{"en":"the announcer's/announce/announcing booth","cn":"播音员的/公告/公告亭"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小隔间；电话亭；投票间","en":"A booth is a small area separated from a larger public area by screens or thin walls where, for example, people can make a telephone call or vote in private.","ex":{"en":"I called her from a public phone booth near the entrance to the bar","cn":"我在酒吧入口处附近的公用电话亭给她打了电话。"}},{"pos":"N-COUNT 可数名词","cn":"（餐厅或咖啡馆中的）火车座，雅座","en":"A booth in a restaurant or café consists of a table with long fixed seats on two or sometimes three sides of it.","ex":{"en":"They sat in a corner booth, away from other diners.","cn":"他们坐在位于角落的一个雅座里，远离其他就餐的客人。"}},{"pos":"N-COUNT 可数名词","cn":"（通常设在集市的）娱乐棚，售货摊","en":"A booth is a small tent or stall, usually at a fair, in which you can buy goods or watch some form of entertainment."},{"pos":"N-COUNT 可数名词","cn":"（展会的）展亭，展位","en":"A booth is a stall at an exhibition, for example with a display of goods for sale or with information leaflets."}]},"examples":[{"en":"a phone booth","cn":"电话亭"},{"en":"a polling/voting booth","cn":"投票间"}]},"box":{"media":{"img":["media/pic/packaging_comp.jpg","media/thumb/box.jpg"],"uk":"media/uk/box__gb_1.mp3","us":"media/us/box__us_1.mp3"},"oxford":{"phon":"bɒks","pos":"noun","senses":[{"en":"a container made of wood, thick card, metal, etc. with a flat stiff base and sides and often a lid (= cover), used especially for holding solid things","cn":"盒；箱；匣","g":"[countable]","sc":"container","ex":{"en":"Everything we owned was neatly packed in cardboard boxes.","cn":"我们全部的家当都整齐地装进了纸箱。"}},{"en":"a box and its contents; the things a box contains","cn":"一盒东西；盒子里的东西","g":"[countable]","sc":"container","ex":{"en":"a box of chocolates/cereal/tissues","cn":"一盒巧克力／麦片／纸巾"}},{"en":"a square or rectangle on a page or computer screen for people to put information in or containing extra or different information","cn":"方框；长方格","g":"[countable]","lab":"British English","sc":"shape","ex":{"en":"Put a cross in the appropriate box.","cn":"在适当的方格里打叉号。"}},{"en":"a small area in a theatre, court or sports stadium, separated off from where other people sit","cn":"（剧院或体育场馆中的）包厢；（法庭中的）专席","g":"[countable]","sc":"in theatre/court","ex":{"en":"The painting depicts two elegantly dressed women in a box at the opera.","cn":"这幅油画描绘的是两个坐在歌剧院包厢里穿着优雅的女人。"}},{"en":"a small shelter used for a particular purpose","cn":"小亭；岗亭","g":"[countable]","lab":"British English, old-fashioned，，","sc":"shelter","ex":{"en":"a sentry/signal box","cn":"岗亭；铁路信号所"}},{"en":"the television","cn":"电视；电视机","g":"[singular]","lab":"especially British English, old-fashioned, informal，，，，","sc":"television","ex":{"en":"What's on the box tonight?","cn":"今晚有什么电视节目？"}},{"en":"a place where two roads cross or join, marked with a pattern of yellow lines to show that vehicles must not stop in that area","cn":"交叉路口黄格区（车辆不得停留）","g":"[countable]","lab":"British English","sc":"on road","ex":{"en":"Only traffic turning right may enter the box.","cn":"只允许右拐的车辆进入交叉路口黄格区。"}},{"en":"an area on a sports field that is marked by lines and used for a particular purpose","cn":"运动场上以线标出的特定区域","g":"[countable]","lab":"British English","sc":"in sport","ex":{"en":"He was fouled in the box (= the penalty box).","cn":"有人在禁区对他犯规。"}},{"en":"a number used as an address, especially one given in newspaper advertisements to which replies can be sent","cn":"信箱号码（报章广告常用）","g":"[countable]","sc":"for mail"},{"en":"a piece of plastic that a man wears over his sex organs to protect them while he is playing a sport, especially cricket","cn":"（运动员的）下体护身","g":"[countable]","lab":"British English","sc":"protection"},{"en":"a small evergreen tree or bush with thick dark leaves, used especially for garden hedges","cn":"黄杨（常绿，尤用作花园树篱）","g":"[countable, uncountable]","sc":"tree/wood"},{"en":"the hard wood of the box tree","cn":"黄杨木","g":"[uncountable]","sc":"tree/wood"},{"en":"to fight somebody in the sport of boxing","cn":"（拳击运动中）击打（某人）","g":"[intransitive, transitive]","sc":"fight","ex":{"en":"He boxed for Ireland in the Olympics.","cn":"他在奥运会上代表爱尔兰出战拳击比赛。"},"pos":"verb"},{"en":"to put something in a box","cn":"把（某物）装箱（或盒、匣）","g":"[transitive]","sc":"put in container","ex":{"en":"She boxed the decorations up and put them in the attic.","cn":"她把装饰品装箱放在阁楼里。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盒子；箱子；匣子","en":"A box is a square or rectangular container with hard or stiff sides. Boxes often have lids.","ex":{"en":"He reached into the cardboard box beside him","cn":"他把手伸进身边的纸板盒里。"}},{"pos":"N-COUNT 可数名词","cn":"（在纸张、道路等上印制或画出的）方格，方框","en":"A box is a square or rectangle that is printed or drawn on a piece of paper, a road, or on some other surface."},{"pos":"N-SING 单数名词","cn":"（足球场的）罚球区","en":"In football, the box is the penalty area of the field.","ex":{"en":"He scored from the penalty spot after being brought down in the box.","cn":"在罚球区内被违规撞倒后，他罚点球破门得分。"}},{"pos":"N-COUNT 可数名词","cn":"（剧院或运动场的）包厢","en":"A box is a small separate area in a theatre or at a sports ground or stadium, where a small number of people can sit to watch the performance or game."},{"pos":"N-SING 单数名词","cn":"电视机","en":"Television is sometimes referred to as the box .","ex":{"en":"Do you watch it live at all or do you watch it on the box?","cn":"你是在现场看还是在电视上看？"}},{"pos":"N-COUNT 可数名词","cn":"（用在数字前表示邮政地址）邮政信箱，邮箱","en":"Box is used before a number as a postal address by organizations that receive a lot of mail.","ex":{"en":"...Country Crafts, Box 111, Landisville.","cn":"兰蒂斯维尔111号信箱，乡村工艺社"}},{"pos":"N-UNCOUNT 不可数名词","cn":"黄杨（小型长绿树，常用作篱笆）","en":"Box is a small evergreen tree with dark leaves which is often used to form hedges.","ex":{"en":"...box hedges.","cn":"黄杨篱笆"}},{"pos":"VERB 动词","cn":"（按照拳击运动的规则）击打","en":"To box means to fight someone according to the rules of boxing.","ex":{"en":"At school I boxed and played rugby","cn":"在学校时我既打拳击又玩橄榄球。"}},{"pos":"","cn":"","en":"to box someone's ears→see: ;"},{"pos":"","cn":"","en":"相关词组：box in"}]},"examples":[{"en":"Only traffic turning right may enter the box.","cn":"只允许右拐的车辆进入交叉路口黄格区。"},{"en":"She felt boxed in by all their petty rules.","cn":"她觉得被他们的琐碎规章束缚住了手脚。"}]},"borderline":{"media":{"uk":"media/uk/borderline__gb_1.mp3","us":"media/us/borderline__us_1.mp3"},"oxford":{"phon":"ˈbɔːdəlaɪn","pos":"adjective","senses":[{"en":"not clearly belonging to a particular condition or group; not clearly acceptable","cn":"所属不清的；两可之间的；临界的","ex":{"en":"In borderline cases teachers will take the final decision, based on the student's previous work.","cn":"在难以定夺的情况下，教师将根据学生先前的作业作出最终评分。"}},{"en":"the division between two qualities or conditions","cn":"两种品质（或状况）之间的分界线","ex":{"en":"This biography sometimes crosses the borderline between fact and fiction.","cn":"这部传记有时混淆了事实和虚构。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（两种不同或相反事物之间的）分界线","en":"The borderline between two different or opposite things is the division between them.","ex":{"en":"...a task which involves exploring the borderline between painting and photography.","cn":"一项探究绘画与摄影之间界线的工作"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"勉强可以的；刚刚够格的","en":"Something that is borderline is only just acceptable as a member of a class or group.","ex":{"en":"Some were obviously unsuitable and could be ruled out at once. Others were borderline cases.","cn":"一些明显不合适，可以马上排除。另一些则勉强合格。"}}]},"examples":[{"en":"In borderline cases teachers will take the final decision, based on the student's previous work.","cn":"在难以定夺的情况下，教师将根据学生先前的作业作出最终评分。"},{"en":"This biography sometimes crosses the borderline between fact and fiction.","cn":"这部传记有时混淆了事实和虚构。"}]},"bookmark":{"oxford":{"phon":"ˈbʊkmɑːk","pos":"noun","senses":[{"en":"a long narrow piece of paper, etc. that you put between the pages of a book when you finish reading so that you can easily find the place again","cn":"书签"},{"en":"a record of the address of a file, a page on the internet, etc. that enables you to find it quickly","cn":"（电子文件、网页等的）书签","lab":"computing"},{"en":"to record of the address of a file, a page on the internet, etc. so that you can find it quickly","cn":"（电子文件、网页等的）书签","ex":{"en":"Do you want to bookmark this site?","cn":"你想把这个网站加入书签吗？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"书签","en":"A bookmark is a narrow piece of card or leather that you put between the pages of a book so that you can find a particular page easily."},{"pos":"N-COUNT 可数名词","cn":"（记录因特网网址的）书签","en":"In computing, a bookmark is the address of an Internet site that you put into a list on your computer so that you can return to it easily.","ex":{"en":"This makes it extremely simple to save what you find with an electronic bookmark so you can return to it later.","cn":"如此一来，用电子书签保存所找到的网页内容就变得非常简单，日后也可以再次访问。"}}]},"media":{"uk":"media/uk/bookmark__gb_1.mp3","us":"media/us/bookmark__us_1.mp3"},"examples":[{"en":"Do you want to bookmark this site?","cn":"你想给这个站点做书签吗？"}]},"booking":{"media":{"uk":"media/uk/booking__gb_1.mp3","us":"media/us/booking__us_1.mp3"},"oxford":{"phon":"ˈbʊkɪŋ","pos":"noun","senses":[{"en":"an arrangement that you make in advance to buy a ticket to travel somewhere, go to the theatre, etc.","cn":"预订","g":"[countable, uncountable]","lab":"especially British English","ex":{"en":"a booking form/hall/clerk","cn":"订票表；售票厅；售票员"}},{"en":"an arrangement for somebody to perform at a theatre, in a concert, etc.","cn":"（登台等的）预约，约定","g":"[countable]"},{"en":"an act of the referee writing a player’s name in a book, as a punishment because an offence has been committed","cn":"（对犯规者的）记名警告","g":"[countable]","lab":"British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"预约；预订","en":"A booking is the arrangement that you make when you book something such as a hotel room, a table at a restaurant, a theatre seat, or a place on public transport.","ex":{"en":"I suggest you tell him there was a mistake over his late booking.","cn":"我建议你告诉他，他应该及早预订。"}}]},"examples":[{"en":"Can I make a booking for Friday?","cn":"我可以订星期五的票吗？"},{"en":"We can't take any more bookings.","cn":"我们不能再接受订票了。"}],"base":"book"},"bomb":{"media":{"uk":"media/uk/bomb__gb_1.mp3","us":"media/us/bomb__us_1.mp3"},"oxford":{"phon":"bɒm","pos":"noun","senses":[{"en":"a weapon designed to explode at a particular time or when it is dropped or thrown","cn":"炸弹","g":"[countable]","ex":{"en":"a bomb goes off/explodes","cn":"炸弹爆炸"}},{"en":"nuclear weapons (atomic or hydrogen bombs)","cn":"核武器；核弹","g":"[singular]","ex":{"en":"countries that have the bomb","cn":"拥有核武器的国家"}},{"en":"a lot of money","cn":"一大笔钱","g":"[singular]","lab":"British English, informal，，","ex":{"en":"That dress must have cost a bomb!","cn":"那条连衣裙花费不菲吧！"}},{"en":"a complete failure","cn":"彻底的失败","g":"[singular]","lab":"North American English, informal，，","ex":{"en":"The musical was a complete bomb on Broadway.","cn":"那出音乐剧在百老汇的演出完全失败。"}},{"en":"a long forward throw of the ball","cn":"长传","g":"[countable]","lab":"North American English"},{"en":"a container in which a liquid such as paint or insect poison is kept under pressure and released as a spray or as foam","cn":"气溶胶弹式容器（油漆、杀虫剂等液体加压贮存可喷出）","g":"[countable]","lab":"North American English","ex":{"en":"a bug bomb (= used for killing insects)","cn":"喷雾杀虫剂"}},{"en":"to attack something/somebody by leaving a bomb in a place or by dropping bombs from a plane","cn":"轰炸；对…投炸弹","g":"[transitive]","ex":{"en":"Warplanes bombed targets in and around the capital.","cn":"战机轰炸了首都内部及周边的目标。"},"pos":"verb"},{"en":"to move very fast, especially in a vehicle, in a particular direction","cn":"快速移动，疾行（尤指乘车）","g":"[intransitive]","lab":"British English, informal，，","ex":{"en":"They were bombing down the road at about 80 miles an hour.","cn":"他们正以大约一小时 80 英里的速度沿路飞驰。"},"pos":"verb"},{"en":"to fail a test or an exam very badly","cn":"（考试）惨败","g":"[transitive, intransitive]","lab":"North American English, informal，，","ex":{"en":"The exam was impossible! I definitely bombed it.","cn":"考试太难了！我肯定考砸了。"},"pos":"verb"},{"en":"to fail very badly","cn":"大败；票房极差；不卖座","g":"[intransitive]","lab":"informal","ex":{"en":"His latest musical bombed and lost thousands of dollars.","cn":"他最近的一部音乐剧演砸了，赔了几千美元。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"炸弹；爆炸装置","en":"A bomb is a device which explodes and damages or destroys a large area.","ex":{"en":"Bombs went off at two London train stations","cn":"伦敦的两个地铁站发生了炸弹爆炸事件。"}},{"pos":"N-SING 单数名词","cn":"核武器；核弹","en":"Nuclear weapons are sometimes referred to as the bomb .","ex":{"en":"They are generally thought to have the bomb.","cn":"人们普遍认为他们拥有核武器。"}},{"pos":"VERB 动词","cn":"轰炸；向…投炸弹","en":"When people bomb a place, they attack it with bombs.","ex":{"en":"Airforce jets bombed the airport.","cn":"空军的喷气式飞机轰炸了该机场。"}},{"pos":"","cn":"","en":"相关词组：bomb out"}]},"examples":[{"en":"They were bombing down the road at about 80 miles an hour.","cn":"他们正以大约一小时 80 英里的速度沿路飞驰。"},{"en":"His latest musical bombed and lost thousands of dollars.","cn":"他最近的一部音乐剧演砸了，赔了几千元。"}]},"boiling":{"oxford":{"phon":"ˈbɔɪlɪŋ","pos":"adjective","senses":[{"en":"very hot","cn":"炽热的；很热的","ex":{"en":"You must be boiling in that sweater!","cn":"你穿着那件毛衣一定很热！"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"炎热的；酷热的","en":"Something that is boiling or boiling hot is very hot.","ex":{"en":"'It's boiling in here,' complained Miriam","cn":"“这里热死了，”米里亚姆抱怨道。"}},{"pos":"ADJ 形容词","cn":"感觉极热的；热得难受的","en":"If you say that you are boiling or boiling hot, you mean that you feel very hot, usually unpleasantly hot. →see usage note at:","ex":{"en":"When everybody else is boiling hot, I'm freezing!","cn":"当其他所有人都酷热难耐时，我却冻得够呛！"}}]},"media":{"uk":"media/uk/boiling__gb_1.mp3","us":"media/us/boiling__us_1.mp3"},"examples":[{"en":"You must be boiling in that sweater!","cn":"你穿着那件毛衣一定很热！"},{"en":"a boiling hot day","cn":"酷热的一天"}],"base":"boil"},"boomer":{"media":{"uk":"media/uk/boomer__gb_1.mp3","us":"media/us/boomer__us_1.mp3"},"oxford":{"phon":"ˈbuːmə(r)","pos":"noun","senses":[{"en":"a person born during a baby boom, especially after the Second World War","cn":"（尤指第二次世界大战后）生育高峰期出生的人；婴儿潮一代","lab":"North American English"},{"en":"a large male kangaroo","cn":"大雄袋鼠"}]}},"boundary":{"oxford":{"phon":"ˈbaʊndri","pos":"noun","senses":[{"en":"a real or imagined line that marks the limits or edges of something and separates it from other things or places; a dividing line","cn":"边界；界限；分界线","lab":"British English","ex":{"en":"After the war the national boundaries were redrawn.","cn":"战后重新划定了国界。"}},{"en":"a hit of the ball that crosses the boundary of the playing area and scores extra points","cn":"使球越过边界线的击球（得加分）","ex":{"en":"He hit 13 boundaries from 183 balls.","cn":"他在 183 球中打出了 13 个边界球。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（土地的）分界线，边界","en":"The boundary of an area of land is an imaginary line that separates it from other areas.","ex":{"en":"...the Bow Brook which forms the western boundary of the wood","cn":"构成了这片树林西部边界的鲍溪"}},{"pos":"N-COUNT 可数名词","cn":"（学科或活动的）界限，边界","en":"The boundaries of something such as a subject or activity are the limits that people think that it has.","ex":{"en":"The boundaries between history and storytelling are always being blurred and muddled.","cn":"历史和轶闻的分界向来是模糊而混乱的。"}}]},"media":{"uk":"media/uk/boundary__gb_1.mp3","us":"media/us/boundary__us_1.mp3"},"examples":[{"en":"The fence marks the boundary between my property and hers.","cn":"那道篱笆是我和她的住宅之间的分界。"},{"en":"the boundary between acceptable and unacceptable behaviour","cn":"可接受和不可接受的行为之间的分界线"}]},"bouncing":{"media":{"uk":"media/uk/bouncing__gb_1.mp3","us":"media/us/bouncing__us_1.mp3"},"oxford":{"phon":"ˈbaʊnsɪŋ","pos":"adjective","senses":[{"en":"healthy and full of energy","cn":"健壮的；茁壮的","ex":{"en":"a bouncing baby boy","cn":"健壮的男婴"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"健壮的；茁壮的","en":"If you say that someone is bouncing with health, you mean that they are very healthy. You can also refer to a bouncing baby.","ex":{"en":"They are bouncing with health in the good weather","cn":"在这种宜人的天气里，他们健康活泼地茁壮成长。"}}]},"examples":[{"en":"a bouncing baby boy","cn":"茁壮的男婴"},{"en":"a bouncing baby girl","cn":"一个健康活泼的女婴"}],"base":"bounce"},"bodily":{"oxford":{"phon":"ˈbɒdɪli","pos":"adjective","senses":[{"en":"connected with the human body","cn":"人体的；身体的","ex":{"en":"bodily functions/changes/needs","cn":"身体的机能／变化／需要"}},{"en":"by moving the whole of somebody’s body; by force","cn":"移动全身地；用力地","ex":{"en":"The force of the blast hurled us bodily to the ground.","cn":"爆炸的力量把我们震落在地上。"},"pos":"adverb"},{"en":"in one piece; completely","cn":"整个地；完全地","ex":{"en":"The monument was moved bodily to a new site.","cn":"整个纪念碑被迁到了新的地点。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"身体的；肉体的","en":"Your bodily needs and functions are the needs and functions of your body.","ex":{"en":"...descriptions of natural bodily functions","cn":"对人体自然生理功能的描述"}},{"pos":"ADV 副词","cn":"整个身体地；全身地","en":"You use bodily to indicate that an action involves the whole of someone's body.","ex":{"en":"I was hurled bodily to the deck.","cn":"我整个人都被摔到了甲板上。"}}]},"media":{"uk":"media/uk/bodily__gb_1.mp3","us":"media/us/bodily__us_1.mp3"},"examples":[{"en":"The force of the blast hurled us bodily to the ground.","cn":"爆炸的力量把我们震落在地上。"},{"en":"The monument was moved bodily to a new site.","cn":"整个纪念碑被迁到了新的地点。"}]},"bone":{"media":{"uk":"media/uk/bone__gb_1.mp3","us":"media/us/bone__us_1.mp3"},"oxford":{"phon":"bəʊn","pos":"noun","senses":[{"en":"any of the hard parts that form the skeleton of the body of a human or an animal","cn":"骨头；骨","g":"[countable]","ex":{"en":"He survived the accident with no broken bones.","cn":"他在事故中幸免于难，没有骨折。"}},{"en":"the hard substance that bones are made of","cn":"骨质","g":"[uncountable]","ex":{"en":"knives with bone handles","cn":"有骨质把手的刀子"}},{"en":"having bones of the type mentioned","cn":"有…样的骨头的","ex":{"en":"fine-boned","cn":"骨架小的"}},{"en":"to take the bones out of fish or meat","cn":"挑鱼刺；剔骨头","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"骨；骨头","en":"Your bones are the hard parts inside your body which together form your skeleton.","ex":{"en":"Many passengers suffered broken bones","cn":"许多乘客骨折。"}},{"pos":"VERB 动词","cn":"剔除（肉类或鱼）的骨头","en":"If you bone a piece of meat or fish, you remove the bones from it before cooking it.","ex":{"en":"Make sure that you do not pierce the skin when boning the chicken thighs","cn":"剔鸡腿骨时切勿戳破外面的皮。"}},{"pos":"ADJ 形容词","cn":"（工具或装饰品）骨制的","en":"A bone tool or ornament is made of bone.","ex":{"en":"...a small, expensive pocketknife with a bone handle.","cn":"昂贵的骨柄小折刀"}},{"pos":"PHRASE 短语","cn":"基本部分；梗概","en":"The bare bones of something are its most basic parts or details.","ex":{"en":"There are not even the bare bones of a garden here — I've got nothing.","cn":"这儿连个花园的影子都没有——我什么也没看到。"}},{"pos":"PHRASE 短语","cn":"太过直白；过于直率；露骨","en":"If something is too close to the bone, it makes you feel uncomfortable because it is very close to the truth or to the real nature of something."},{"pos":"PHRASE 短语","cn":"从内心；凭直觉","en":"If you say that you feel or know something in your bones, you are indicating that you are certain about it, although you cannot explain why.","ex":{"en":"I've got a feeling in my bones that things are not quite right.","cn":"直觉告诉我情况不太对头。"}},{"pos":"PHRASE 短语","cn":"开诚布公；直言不讳","en":"If you make no bones about something, you talk openly about it, rather than trying to keep it a secret.","ex":{"en":"Some of them make no bones about their political views.","cn":"他们中的一些人坦率地表达了自己的政治观点。"}},{"pos":"PHRASE 短语","cn":"毫不犹豫；毫不迟疑；二话不说","en":"If you make no bones about doing something that is unpleasant or difficult or that might upset someone else, you do it without hesitating.","ex":{"en":"Stafford-Clark made no bones about reapplying for the job when Daldry was standing for it.","cn":"当戴德利对他表示支持时，斯塔福德-克拉克毫不迟疑地再次申请了这份工作。"}},{"pos":"PHRASE 短语","cn":"瘦得皮包骨头；瘦骨嶙峋","en":"You can say someone is just skin and bone when you do not approve of the fact that they are very thin.","ex":{"en":"He was nothing but skin and bones.","cn":"他瘦得只剩皮包骨头了。"}},{"pos":"PHRASE 短语","cn":"（削减）达到最低限度，到最小化","en":"If something such as costs are cut to the bone, they are reduced to the minimum possible.","ex":{"en":"It has survived by cutting its costs to the bone","cn":"它通过最大限度地降低运营成本生存了下来。"}},{"pos":"PHRASE 短语","cn":"（影响）深刻地，彻骨地","en":"You use to the bone to indicate that you are very deeply affected by something. For example, if you feel chilled to the bone, your whole body feels extremely cold, often because you have had a shock.","ex":{"en":"What I saw chilled me to the bone.","cn":"我看到的景象令我不寒而栗。"}},{"pos":"","cn":"","en":"相关词组：bone up on"}]},"examples":[{"en":"She had boned up on the city's history before the visit.","cn":"她在前往这个城市之前先对它的历史研究了一番。"},{"en":"She made no bones about telling him exactly what she thought of him.","cn":"她毫无保留地把对他的看法照直告诉了他。"}]},"boyhood":{"media":{"uk":"media/uk/boyhood__gb_1.mp3","us":"media/us/boyhood__us_1.mp3"},"oxford":{"phon":"ˈbɔɪhʊd","pos":"noun","senses":[{"en":"the time in a man’s life when he is a boy","cn":"（男子的）孩童期，青少年时代","ex":{"en":"boyhood days/memories/friends","cn":"童年时代／回忆；儿时的朋友"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（男子的）童年，少年时代","en":"Boyhood is the period of a male person's life during which he is a boy.","ex":{"en":"He has been a Derby County supporter since boyhood.","cn":"他从孩提时代起就是德比郡队的支持者。"}}]},"examples":[{"en":"boyhood days/memories/friends","cn":"童年时代/回忆；儿时的朋友"},{"en":"boyhood memories","cn":"童年的记忆"}]},"bowler":{"oxford":{"phon":"ˈbəʊlə(r)","pos":"noun","senses":[{"en":"a player who throws the ball towards the batsman","cn":"投球手"},{"en":"a hard black hat with a curved brim and round top, worn, for example, in the past by men in business in Britain","cn":"常礼帽（英国旧时商人等戴）","lab":"both especially British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（板球等运动中的）投球手，投球员","en":"The bowler in a sport such as cricket is the player who is bowling the ball.","ex":{"en":"He's a rather good fast bowler.","cn":"他是一个非常棒的快投手。"}},{"pos":"N-COUNT 可数名词","cn":"玩草地滚木球游戏的人；保龄球选手","en":"A bowler is someone who plays bowls or goes bowling."},{"pos":"N-COUNT 可数名词","cn":"同bowler hat","en":"A bowler is the same as a bowler hat ."}]},"media":{"img":["media/pic/hats_comp.jpg","media/thumb/bowler.jpg"],"uk":"media/uk/bowler__gb_1.mp3","us":"media/us/bowler__us_1.mp3"}},"boring":{"oxford":{"phon":"ˈbɔːrɪŋ","pos":"adjective","senses":[{"en":"not interesting; making you feel tired and impatient","cn":"没趣的；令人厌倦（或厌烦）的","ex":{"en":"He's such a boring man!","cn":"他那人无趣得很！"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人厌烦的；无聊的","en":"Someone or something boring is so dull and uninteresting that they make people tired and impatient.","ex":{"en":"Not only are mothers not paid but also most of their boring or difficult work is unnoticed.","cn":"母亲们不但得不到报酬，而且她们做的那些乏味艰苦的工作常常都不为人所注意。"}}]},"media":{"uk":"media/uk/boring__gb_1.mp3","us":"media/us/boring__us_1.mp3"},"examples":[{"en":"Life in a small town could be deadly dull.","cn":"小城镇的生活可能会非常没意思。"},{"en":"The journey soon became tedious.","cn":"那次旅行不久就变得乏味起来。"}],"base":"bore"},"boy":{"media":{"uk":"media/uk/boy__gb_1.mp3","us":"media/us/boy__us_1.mp3"},"oxford":{"phon":"bɔɪ","pos":"noun","senses":[{"en":"a male child or a young male person","cn":"男孩；男青年","g":"[countable]","ex":{"en":"a little/small/young boy","cn":"小男孩；小伙子"}},{"en":"a young son","cn":"年少的儿子","g":"[countable]","ex":{"en":"They have two boys and a girl.","cn":"他们有两个儿子和一个女儿。"}},{"en":"a boy or young man who does a particular job","cn":"做某工作的男孩（或小伙子）；伙计","g":"[countable]","ex":{"en":"a delivery boy","cn":"报童"}},{"en":"a way of talking about somebody who comes from a particular place, etc.","cn":"（指称某地等的人）","g":"[countable]","ex":{"en":"He's a local boy.","cn":"他是本地人。"}},{"en":"a group of male friends who often go out together","cn":"一帮男伙伴","g":"[plural]","lab":"informal","ex":{"en":"a night out with the boys","cn":"和弟兄们一同消遣的一夜"}},{"en":"a way of talking about your country’s soldiers to show that you like and care about them","cn":"（对本国士兵的昵称）兵哥哥们，小伙子们","g":"[plural]","ex":{"en":"a message of support for our boys serving overseas","cn":"支持我们在海外服役士兵的信息"}},{"en":"used as an offensive way of addressing a black man","cn":"（尤为旧时不礼貌地称呼黑人男子用）黑仔，小子","g":"[countable]","lab":"North American English, old-fashioned, offensive, taboo, slang，，，，，，，，"},{"en":"used to express feelings of surprise, pleasure, pain, etc.","cn":"（表示惊奇、高兴、痛苦等）","ex":{"en":"Boy, it sure is hot!","cn":"嗬，真够辣的！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男孩；男童","en":"A boy is a child who will grow up to be a man.","ex":{"en":"I knew him when he was a little boy","cn":"他还是个小男孩的时候我就认识他了。"}},{"pos":"N-COUNT 可数名词","cn":"男青年，小伙子（尤用于指青年男女恋爱关系时）","en":"You can refer to a young man as a boy, especially when talking about relationships between boys and girls.","ex":{"en":"...the age when girls get interested in boys.","cn":"姑娘开始对小伙子感兴趣的年龄"}},{"pos":"N-COUNT 可数名词","cn":"儿子","en":"Someone's boy is their son.","ex":{"en":"Eric was my cousin Edward's boy","cn":"埃里克是我表兄爱德华的儿子。"}},{"pos":"N-COUNT 可数名词","cn":"家伙，伙计（尤用于亲切谈论某人时）","en":"You can refer to a man as a boy, especially when you are talking about him in an affectionate way.","ex":{"en":"...the local boy who made President","cn":"当上总统的本地小伙子"}},{"pos":"N-VOC 称呼名词","cn":"家伙，伙计（用于吆喝马或狗时）","en":"You can use boy when giving instructions to a horse or dog.","ex":{"en":"Down, boy, down!","cn":"趴下，小家伙，趴下！"}},{"pos":"PHRASE 短语","cn":"警察","en":"The police are sometimes referred to as the boys in blue ."},{"pos":"EXCLAM 感叹语","cn":"好家伙(表示激动、羡慕等情感）","en":"Some people say 'boy' or 'oh boy' in order to express feelings of excitement or admiration.","ex":{"en":"Oh Boy! Just think what I could tell him.","cn":"哇，好家伙！想想看我会告诉他什么。"}},{"pos":"PHRASE 短语","cn":"男人总归是男人（用以表示男人的典型行为不会改变）","en":"If you say boys will be boys, for example when a group of men are behaving noisily or aggressively, you are suggesting in a light-hearted way that this is typical male behaviour and will never change."},{"pos":"PHRASE 短语","cn":"男子汉中的一员","en":"If a man is described as one of the boys, he is accepted by a group of male friends who do things that are thought of as typically masculine.","ex":{"en":"He wants to be accepted as one of the boys.","cn":"他想被人看作一个男子汉。"}}]},"examples":[{"en":"Now she's a teenager, she's starting to be interested in boys.","cn":"她现在已经是个十几岁的姑娘了，开始对男孩子感兴趣。"},{"en":"The older boys at school used to tease him.","cn":"学校里大一些的男生过去常常取笑他。"}]},"borrowed":{"lemma":"borrow"},"bookcase":{"oxford":{"phon":"ˈbʊkkeɪs","pos":"noun","senses":[{"en":"a piece of furniture with shelves for keeping books on","cn":"书架；书柜","ex":{"en":"I chose a book from the bookcase.","cn":"我从书橱里选了本书。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"书架；书橱","en":"A bookcase is a piece of furniture with shelves that you keep books on."}]},"media":{"uk":"media/uk/bookcase__gb_1.mp3","us":"media/us/bookcase__us_1.mp3"}},"boost":{"media":{"uk":"media/uk/boost__gb_1.mp3","us":"media/us/boost__us_1.mp3"},"oxford":{"phon":"buːst","pos":"verb","senses":[{"en":"to make something increase, or become better or more successful","cn":"使增长；使兴旺","ex":{"en":"to boost exports/profits","cn":"增加出口；提高利润"}},{"en":"to steal something","cn":"偷窃","lab":"North American English, informal, becoming old-fashioned，，，，"},{"en":"something that helps or encourages somebody/something","cn":"帮助；激励","ex":{"en":"a great/tremendous/welcome boost","cn":"很大的／极大的／令人欣喜的激励"},"pos":"noun"},{"en":"an increase in something","cn":"增长；提高","ex":{"en":"a boost in car sales","cn":"汽车销售额的增长"},"pos":"noun"},{"en":"an increase in power in an engine or a piece of electrical equipment","cn":"（发动机或电气设备的）功率增大","pos":"noun"},{"en":"an act of pushing somebody up from behind","cn":"（从后面的）向上一推，一举","lab":"especially North American English","ex":{"en":"He gave her a boost over the fence.","cn":"他推了她一把，帮她翻过围墙。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使增长；推动；改进；使兴旺","en":"If one thing boosts another, it causes it to increase, improve, or be more successful.","ex":{"en":"It wants the government to take action to boost the economy","cn":"它希望政府采取行动促进经济发展。"}},{"pos":"VERB 动词","cn":"增强，提高（信心或士气）","en":"If something boosts your confidence or morale, it improves it.","ex":{"en":"We need a big win to boost our confidence","cn":"我们需要大胜一场来增强信心。"}}]},"examples":[{"en":"The movie helped boost her screen career.","cn":"那部电影有助于她的银幕生涯的发展。"},{"en":"The tax cuts will give a much needed boost to the economy.","cn":"减税将给经济带来迫切需要的推动力。"}]},"bold":{"media":{"uk":"media/uk/bold__gb_1.mp3","us":"media/us/bold__us_1.mp3"},"oxford":{"phon":"bəʊld","pos":"adjective","senses":[{"en":"brave and confident; not afraid to say what you feel or to take risks","cn":"大胆自信的；敢于表白情感的；敢于冒险的","ex":{"en":"It was a bold move on their part to open a business in France.","cn":"在法国开业是他们的一个大胆举动。"}},{"en":"in a thick, dark type","cn":"粗体的；黑体的","ex":{"en":"Highlight the important words in bold type.","cn":"用黑体突出重要词语。"}},{"en":"that can be easily seen; having a strong clear appearance","cn":"明显的；轮廓突出的","ex":{"en":"the bold outline of a mountain against the sky","cn":"天空映衬下的山的清晰轮廓"}},{"en":"thick, dark type used for printing words or letters","cn":"黑体；粗体","ex":{"en":"Headwords are printed in bold.","cn":"首词用黑体印刷。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大胆的；勇敢的；无畏的","en":"Someone who is bold is not afraid to do things which involve risk or danger.","ex":{"en":"Amrita becomes a bold, daring rebel","cn":"阿姆里塔成了一个勇敢无畏的叛逆者。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（在众人面前）大胆的，放肆的，莽撞的","en":"Someone who is bold is not shy or embarrassed in the company of other people.","ex":{"en":"I don't feel I'm being bold, because it's always been natural for me to just speak out about whatever disturbs me.","cn":"我不觉得我有什么唐突，因为我素来心直口快，有什么烦心的都会说出来。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（色彩或图案）明亮的，醒目的","en":"A bold colour or pattern is very bright and noticeable.","ex":{"en":"...bold flowers in various shades of red, blue or white.","cn":"色彩鲜艳、浓淡不一的红、蓝、白色花朵"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(线条）粗重的；（图案）清晰的","en":"Bold lines or designs are drawn in a clear, strong way.","ex":{"en":"Each picture is shown in colour on one page and as a bold outline on the opposite page.","cn":"每幅图片的彩样都单独印在一页上，而在该页的背面会映出清晰的轮廓。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（印刷字体）粗体字，黑体字","en":"Bold is print which is thicker and looks blacker than ordinary printed letters."}]},"examples":[{"en":"The wine made him bold enough to approach her.","cn":"他趁着酒劲，鼓足勇气上前和她说话。"},{"en":"It was a bold move on their part to open a business in France.","cn":"在法国开业是他们的一个大胆举动。"}]},"border":{"oxford":{"phon":"ˈbɔːdə(r)","pos":"noun","senses":[{"en":"the line that divides two countries or areas; the land near this line","cn":"国界；边界；边疆；边界地区","lab":"figurative","ex":{"en":"I live in a small town in the US, near the Canadian border.","cn":"我住在靠近加拿大边界的一个美国小镇。"}},{"en":"a long narrow piece around the edge of something such as a picture or a piece of cloth","cn":"镶边；包边","ex":{"en":"a pillowcase with a lace border","cn":"有花边的枕套"}},{"en":"a long narrow area of soil which is planted with flowers, along the edge of the grass","cn":"（草坪边的）狭长花坛","ex":{"en":"The back garden is mostly lawn with herbaceous borders.","cn":"后院主要是草坪，草坪四边种有草本植物。"}},{"en":"to share a border with another country or area","cn":"和…毗邻；与…接壤","ex":{"en":"the countries bordering the Baltic","cn":"波罗的海沿岸国家"},"pos":"verb"},{"en":"to form a line along or around the edge of something","cn":"沿…的边；环绕…；给…镶边","ex":{"en":"Meadows bordered the path to the woods.","cn":"通往树林的小径两边都是草坪。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"边界；边疆；边界地区","en":"The border between two countries or regions is the dividing line between them. Sometimes the border also refers to the land close to this line.","ex":{"en":"They fled across the border.","cn":"他们穿越边界逃走了。"}},{"pos":"VERB 动词","cn":"和…毗邻；与…接壤","en":"A country that borders another country, a sea, or a river is next to it.","ex":{"en":"...the European and Arab countries bordering the Mediterranean.","cn":"地中海沿岸的欧洲和阿拉伯国家"}},{"pos":"N-COUNT 可数名词","cn":"镶边；包边","en":"A border is a strip or band around the edge of something.","ex":{"en":"...pillowcases trimmed with a hand-crocheted border.","cn":"饰有手工编织花边的枕套"}},{"pos":"N-COUNT 可数名词","cn":"（花园边上的）狭长花坛，花带","en":"In a garden, a border is a long strip of ground along the edge planted with flowers.","ex":{"en":"...a lawn flanked by wide herbaceous borders.","cn":"两侧栽种大片草本花的草坪"}},{"pos":"VERB 动词","cn":"形成…的边界；环绕；毗连","en":"If something is bordered by another thing, the other thing forms a line along the edge of it.","ex":{"en":"... the mile of white sand beach bordered by palm trees and tropical flowers","cn":"四周种有棕榈树和热带花卉的长达1英里的白色沙滩"}},{"pos":"","cn":"","en":"相关词组：border on"}]},"media":{"img":["media/pic/edge.jpg","media/thumb/border.jpg"],"uk":"media/uk/border__gb_1.mp3","us":"media/us/border__us_1.mp3"},"examples":[{"en":"The river formed the frontier between the land of the Saxons and that of the Danes.","cn":"这条河曾是撒克逊人与古斯堪的纳维亚人土地的分界线。"},{"en":"The fence marked the boundary between my property and hers.","cn":"那道篱笆曾是我和她的房产之间的地界。"}]},"boat":{"media":{"img":["media/pic/boats_comp.jpg","media/thumb/rowingboat.jpg"],"uk":"media/uk/boat__gb_1.mp3","us":"media/us/boat__us_1.mp3"},"oxford":{"phon":"bəʊt","pos":"noun","senses":[{"en":"a vehicle (smaller than a ship) that travels on water, moved by oars, sails or a motor","cn":"小船；汽艇；舟","ex":{"en":"a rowing/sailing boat","cn":"划艇；帆船"}},{"en":"any ship","cn":"（泛指）船","ex":{"en":"‘How are you going to France?’ ‘We're going by boat (= by ferry).’","cn":"“你们怎么去法国？”“我们乘船去。”"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"船；小船","en":"A boat is something in which people can travel across water.","ex":{"en":"One of the best ways to see the area is in a small boat","cn":"游览该地区的一个最好方式是乘坐小船。"}},{"pos":"N-COUNT 可数名词","cn":"客轮；客船","en":"You can refer to a passenger ship as a boat .","ex":{"en":"When the boat reached Cape Town, we said a temporary goodbye.","cn":"客轮到达开普敦时，我们暂时分别。"}},{"pos":"PHRASE 短语","cn":"坐失良机；错失机会","en":"If you say that someone has missed the boat, you mean that they have missed an opportunity and may not get another."},{"pos":"PHRASE 短语","cn":"（尤指为了庆祝）挥金如土，大事铺张","en":"If you push the boat out, you spend a lot of money on something, especially in order to celebrate.","ex":{"en":"I earn enough to push the boat out now and again.","cn":"我挣的钱足以时不时摆摆阔了。"}},{"pos":"PHRASE 短语","cn":"捣乱；兴风作浪","en":"If you say that someone is rocking the boat, you mean that they are upsetting a calm situation and causing trouble.","ex":{"en":"I said I didn't want to rock the boat in any way.","cn":"我说过我根本不想挑事。"}},{"pos":"PHRASE 短语","cn":"处于相同的倒霉境地；同病相怜","en":"If two or more people are in the same boat, they are in the same unpleasant situation."}]},"examples":[{"en":"‘How are you going to France?’ ‘We're going by boat (= by ferry ). ’ “","cn":"你们怎么去法国？” “我们乘船去。”"},{"en":"You can take a boat trip along the coast.","cn":"你可以乘船沿海岸旅游一趟。"}]},"bother":{"oxford":{"phon":"ˈbɒðə(r)","pos":"verb","senses":[{"en":"to spend time and/or energy doing something","cn":"花费时间精力（做某事）","g":"[intransitive, transitive]","ex":{"en":"‘Shall I wait?’ ‘No, don't bother’.","cn":"“要我等一下吗？”“不，别费事了。”"}},{"en":"to annoy, worry or upset somebody; to cause somebody trouble or pain","cn":"使（某人）烦恼（或担忧、不安）；给（某人）造成麻烦（或痛苦）","g":"[transitive]","ex":{"en":"The thing that bothers me is…","cn":"让我感到不安的是…"}},{"en":"to interrupt somebody; to talk to somebody when they do not want to talk to you","cn":"打扰；搭话烦扰","g":"[transitive]","ex":{"en":"Stop bothering me when I'm working.","cn":"我工作时别来烦我。"}},{"en":"trouble or difficulty","cn":"麻烦；困难","g":"[uncountable]","ex":{"en":"You seem to have got yourself into a spot of bother.","cn":"你似乎惹上了点麻烦。"},"pos":"noun"},{"en":"an annoying situation, thing or person","cn":"令人烦恼的情况（或事物、人）","g":"[singular]","ex":{"en":"I hope I haven't been a bother.","cn":"希望我没烦扰你。"},"pos":"noun"},{"en":"used to express the fact that you are annoyed about something/somebody","cn":"（表示对某事或某人烦恼）","ex":{"en":"Bother! I've left my wallet at home.","cn":"真烦人！我把钱包落在家里了。"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"操心；费力；麻烦","en":"If you do not bother to do something or if you do not bother with it, you do not do it, consider it, or use it because you think it is unnecessary or because you are too lazy.","ex":{"en":"Lots of people don't bother to go through a marriage ceremony these days","cn":"如今很多人不再费心思举行婚礼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"麻烦；不便；麻烦事","en":"Bother means trouble or difficulty. You can also use bother to refer to an activity which causes this, especially when you would prefer not to do it or get involved with it.","ex":{"en":"I usually buy sliced bread — it's less bother","cn":"我通常都买切片面包——比较省事。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"麻烦（用于淡化问题的严重性）","en":"You use bother to refer to serious trouble, usually when you want to make it sound less serious than it really is.","ex":{"en":"Vince is having a spot of bother with the law.","cn":"文斯惹上了点儿官司。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）烦恼；（使）担忧；（使）不安","en":"If something bothers you, or if you bother about it, it worries, annoys, or upsets you.","ex":{"en":"Is something bothering you?","cn":"你有什么烦心事吗？"}},{"pos":"VERB 动词","cn":"打扰；烦扰","en":"If someone bothers you, they talk to you when you want to be left alone or interrupt you when you are busy.","ex":{"en":"We are playing a trick on a man who keeps bothering me","cn":"我们在捉弄一个总是来烦我的人。"}},{"pos":"EXCLAM 感叹语","cn":"见鬼；真讨厌","en":"Some people say 'bother' or 'bother it' when they are annoyed about something."},{"pos":"PHRASE 短语","cn":"不愿找麻烦；不想出力","en":"If you say that you can't be bothered to do something, you mean that you are not going to do it because you think it is unnecessary or because you are too lazy.","ex":{"en":"I just can't be bothered to look after the house","cn":"我就是不想费事照看这所房子。"}},{"pos":"CONVENTION 惯用语","cn":"这不麻烦；不费事；没什么","en":"If you say 'it's no bother' after offering to do something for someone, you are emphasizing that you really want to do it and that it will take very little effort.","ex":{"en":"I'll drive you back to your hotel later. It's no bother.","cn":"我一会儿会开车把你送回宾馆，举手之劳。"}},{"pos":"","cn":"","en":"hot and bothered→see: ;"}]},"media":{"uk":"media/uk/bother__gb_1.mp3","us":"media/us/bother__us_1.mp3"},"examples":[{"en":"It bothers me to think of her alone in that big house.","cn":"想到她孤零零地待在那所大房子里，我便坐立不安。"},{"en":"Oh, bother him! He's never around when you need him.","cn":"哎呀，他可真讨厌！需要他的时候从来都找不到他。"}]},"book":{"media":{"uk":"media/uk/book__gb_1.mp3","us":"media/us/book__us_1.mp3"},"oxford":{"phon":"bʊk","pos":"noun","senses":[{"en":"a set of printed pages that are fastened inside a cover so that you can turn them and read them","cn":"书；书籍","g":"[countable]","sc":"printed work","ex":{"en":"His desk was covered with piles of books.","cn":"他的书桌上堆满了一摞摞的书。"}},{"en":"a written work published in printed or electronic form","cn":"印刷（或电子）出版物；著作","g":"[countable]","lab":"US English","sc":"printed work","ex":{"en":"to read/write/publish a book","cn":"读书；写书；出版书"}},{"en":"a set of sheets of paper that are fastened together inside a cover and used for writing in","cn":"本子；簿子","g":"[countable]","sc":"for writing in","ex":{"en":"an exercise book","cn":"练习本"}},{"en":"a set of things that are fastened together like a book","cn":"装订成册的一套东西","g":"[countable]","sc":"of stamps/tickets/matches, etc.","ex":{"en":"a book of stamps/tickets/matches","cn":"一封邮票；一本票券；一纸板火柴"}},{"en":"the written records of the financial affairs of a business","cn":"（企业的）账簿","g":"[plural]","sc":"accounts","ex":{"en":"to do the books (= to check the accounts)","cn":"查账"}},{"en":"a section of a large written work","cn":"（长篇作品的）篇，卷，部","g":"[countable]","sc":"section of Bible, etc.","ex":{"en":"the books of the Bible","cn":"《圣经》中各卷"}},{"en":"a record of bets made on whether something will happen, somebody will win a race, etc.","cn":"赌注记录","g":"[countable]","lab":"British English","sc":"for betting","ex":{"en":"They’ve opened a book on who’ll win the Championship.","cn":"他们出版了一本关于谁将赢得冠军的书。"}},{"en":"to arrange to have or use something on a particular date in the future; to buy a ticket in advance","cn":"预约；预订","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"Book early to avoid disappointment.","cn":"及早预约，以免向隅。"},"pos":"verb"},{"en":"to arrange for somebody to have a seat on a plane, etc.","cn":"给（某人）预订飞机等座位","g":"[transitive]","ex":{"en":"I've booked you on the 10 o'clock flight.","cn":"我给你订了 10 点钟的飞机票。"},"pos":"verb"},{"en":"to arrange for a singer, etc. to perform on a particular date","cn":"和（歌手等）预约演出日期","g":"[transitive]","ex":{"en":"We've booked a band for the wedding reception.","cn":"我们已经为婚宴预约了乐队。"},"pos":"verb"},{"en":"to write down somebody’s name and address because they have committed a crime or an offence","cn":"立案（控告某人）","g":"[transitive]","lab":"informal","ex":{"en":"He was booked for possession of cocaine.","cn":"他因藏有可卡因而被立案审查。"},"pos":"verb"},{"en":"to write down in an official book the name of a player who has broken the rules of the game","cn":"记名警告（犯规运动员）","g":"[transitive]","lab":"British English","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"书；书籍；本子；簿册","en":"A book is a number of pieces of paper, usually with words printed on them, which are fastened together and fixed inside a cover of stronger paper or cardboard. Books contain information, stories, or poetry, for example.","ex":{"en":"His eighth book came out earlier this year and was an instant best-seller","cn":"他的第8本书在今年早些时候面世，迅速成为了畅销书。"}},{"pos":"N-COUNT 可数名词","cn":"一册（邮票）；一纸板（火柴）；一本（票券）","en":"A book of something such as stamps, matches, or tickets is a small number of them fastened together between thin cardboard covers.","ex":{"en":"Can I have a book of first class stamps please?","cn":"请给我一板第一类邮件的邮票好吗？"}},{"pos":"VERB 动词","cn":"订，预订（旅馆房间、票等）","en":"When you book something such as a hotel room or a ticket, you arrange to have it or use it at a particular time.","ex":{"en":"British officials have booked hotel rooms for the women and children","cn":"英国官员已为妇女和儿童预订了宾馆房间。"}},{"pos":"N-PLURAL 复数名词","cn":"（公司或组织机构的）账册，账簿，名册","en":"A company's or organization's books are its records of money that has been spent and earned or of the names of people who belong to it.","ex":{"en":"For the most part he left the books to his managers and accountants","cn":"他通常都把账册交给经理和会计们处理。"}},{"pos":"VERB 动词","cn":"（足球裁判）记名警告（严重犯规的球员）","en":"When a referee books a football player who has seriously broken the rules of the game, he or she officially writes down the player's name.","ex":{"en":"League referee Keith Cooper booked him in the first half for a tussle with the goalie.","cn":"联赛裁判基思·库珀在上半场因他与守门员抢球犯规而对他记名警告。"}},{"pos":"VERB 动词","cn":"（警察)把…记录在案，给…做笔录","en":"When a police officer books someone, he or she officially records their name and the offence that they may be charged with.","ex":{"en":"They took him to the station and booked him for assault with a deadly weapon.","cn":"他们把他带到警察局，把他用致命武器袭击他人的罪行记录在案。"}},{"pos":"N-COUNT 可数名词","cn":"（《圣经》等长篇作品的）篇，卷，书","en":"In a very long written work such as the Bible, a book is one of the sections into which it is divided."},{"pos":"PHRASE 短语","cn":"令人厌烦/令人满意","en":"If you are in someone's bad books, they are annoyed with you. If you are in their good books, they are pleased with you.","ex":{"en":"Sir John was definitely in the Treasury's bad books for incorrect thinking on economic prospects","cn":"约翰爵士肯定不受财政部的待见，因为他对经济前景的预测并不准确。"}},{"pos":"PHRASE 短语","cn":"将…依法治罪；审讯；审问","en":"If you bring someone to book, you punish them for an offence or make them explain their behaviour officially.","ex":{"en":"Police should be asked to investigate so that the guilty can be brought to book soon.","cn":"应该要求警方介入调查，以将罪犯早日绳之以法。"}},{"pos":"PHRASE 短语","cn":"完全不了解的人；一无所知的事物；谜","en":"If you say that someone or something is a closed book, you mean that you do not know anything about them.","ex":{"en":"Frank Spriggs was a very able man but something of a closed book","cn":"弗兰克·斯普里格斯是一个很有才干的人，但是有些让人捉摸不透。"}},{"pos":"PHRASE 短语","cn":"（旅馆、餐馆、剧院或交通工具）被预订一空，满座，客满","en":"If a hotel, restaurant, theatre, or transport service is fully booked, or booked solid, it is booked up.","ex":{"en":"The car ferries from the mainland are often fully booked by February.","cn":"从大陆出发的汽车轮渡常常在2月前就被预订一空。"}},{"pos":"PHRASE 短语","cn":"依我看；根据我的观点","en":"In my book means 'in my opinion' or 'according to my beliefs'.","ex":{"en":"The greatest manager there has ever been, or ever will be in my book, is retiring.","cn":"这位迄今为止最杰出的，在我看来，也是后人无法超越的经理，就要退休了。"}},{"pos":"PHRASE 短语","cn":"（当权者）对（违法者）从严惩罚","en":"If someone in authority throws the book at someone who has committed an offence, they give the offender the greatest punishment that they are allowed to."},{"pos":"","cn":"","en":"to cook the books→see: ; to take a leaf from someone's book→see: ;"},{"pos":"","cn":"","en":"相关词组：book in"}]},"examples":[{"en":"I got in at ten and booked straight into a hotel.","cn":"我十点钟到达后直接到一家旅馆办理了住宿手续。"},{"en":"I'm in her good books at the moment because I cleared up the kitchen.","cn":"她现在对我有好感，因为我把厨房清理干净了。"}]},"bordering":{"lemma":"border"},"boredom":{"oxford":{"phon":"ˈbɔːdəm","pos":"noun","senses":[{"en":"the state of feeling bored; the fact of being very boring","cn":"厌烦；厌倦；无聊","ex":{"en":"I started to eat too much out of sheer boredom.","cn":"由于实在闲极无聊，我开始无节制地大吃起来。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"厌烦；厌倦","en":"Boredom is the state of being bored.","ex":{"en":"He had given up attending lectures out of sheer boredom","cn":"他不再去听那些讲座完全是出于厌倦。"}}]},"media":{"uk":"media/uk/boredom__gb_1.mp3","us":"media/us/boredom__us_1.mp3"},"examples":[{"en":"I started to eat too much out of sheer boredom.","cn":"由于实在闲极无聊，我开始无节制地大吃起来。"},{"en":"Television helps to relieve the boredom of the long winter evenings.","cn":"电视有助于打发漫长无聊的冬天晚上。"}]},"boils":{"lemma":"boil"},"bobbing":{"lemma":"bob"},"bore":{"media":{"uk":"media/uk/bore__gb_1.mp3","us":"media/us/bore__us_1.mp3"},"oxford":{"phon":"bɔː(r)","pos":"verb","senses":[{"en":"to make somebody feel bored, especially by talking too much","cn":"（尤指因啰嗦）使厌烦","g":"[transitive]","ex":{"en":"I'm not boring you, am I?","cn":"我没有让你厌烦吧？"}},{"en":"to make a long deep hole with a tool or by digging","cn":"钻，凿，挖（长而深的洞）","g":"[intransitive, transitive]","ex":{"en":"The drill is strong enough to bore through solid rock.","cn":"这把钻足以钻透坚固的岩石。"}},{"en":"to stare in a way that makes somebody feel uncomfortable","cn":"盯着看","g":"[intransitive]","ex":{"en":"His blue eyes seemed to bore into her.","cn":"他的一双蓝眼睛似乎要穿透她。"}},{"en":"a person who is very boring, usually because they talk too much","cn":"（常因话多）令人厌烦的人","g":"[countable]","pos":"noun"},{"en":"a situation or thing that is boring or that annoys you","cn":"烦人的状况（或事情）","g":"[singular]","ex":{"en":"It's such a bore having to stay late this evening.","cn":"今天晚上得熬夜了，真是烦人。"},"pos":"noun"},{"en":"the hollow inside of a tube, such as a pipe or a gun; the measurement from one side of the hole to the other","cn":"（管道、枪炮等的）孔，内径，口径；膛径","g":"[countable]","lab":"especially in North American English","ex":{"en":"a tube with a wide/narrow bore","cn":"内径宽／窄的管子"},"pos":"noun"},{"en":"a strong, high wave that rushes along a river from the sea at particular times of the year","cn":"（海水涌入江河的）涌潮，激潮","g":"[countable]","pos":"noun"},{"en":"a deep hole made in the ground, especially to find water or oil","cn":"（尤指找水或石油的）探孔，钻孔","g":"[countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使厌烦；使厌倦","en":"If someone or something bores you, you find them dull and uninteresting.","ex":{"en":"Dickie bored him all through the meal with stories of the Navy","cn":"迪基吃饭时一直在讲海军的故事，让他不胜其烦。"}},{"pos":"PHRASE 短语","cn":"使厌烦透顶；使烦得要命","en":"If someone or something bores you to tears ,bores you to death, or bores you stiff, they bore you very much indeed.","ex":{"en":"...a handsome engineer who bored me to tears with his tale of motorway maintenance","cn":"英俊的工程师不停地讲高速公路养护的故事，烦得我要命"}},{"pos":"N-COUNT 可数名词","cn":"令人厌烦的人；无趣的人","en":"You describe someone as a bore when you think that they talk in a very uninteresting way.","ex":{"en":"There is every reason why I shouldn't enjoy his company — he's a bore and a fool.","cn":"我有充分的理由不愿和他在一起 —— 他又乏味又愚笨。"}},{"pos":"N-SING 单数名词","cn":"令人生厌的事；无聊的事","en":"You can describe a situation as a bore when you find it annoying.","ex":{"en":"It's a bore to be sick, and the novelty of lying in bed all day wears off quickly.","cn":"生病是件烦人的事，整天躺在床上的新鲜劲很快就没了。"}},{"pos":"VERB 动词","cn":"钻，凿，挖（孔）","en":"If you bore a hole in something, you make a deep round hole in it using a special tool.","ex":{"en":"Get the special drill bit to bore the correct-size hole for the job.","cn":"做这个活儿要拿个特殊的钻头来钻个大小合适的孔。"}},{"pos":"VERB 动词","cn":"凝视；盯着看","en":"If someone's eyes bore into you, they stare intensely at you.","ex":{"en":"His eyes bored into her, paralysing her, robbing her of movement","cn":"他双眼凝视着她，令她全身瘫软，不能动弹。"}},{"pos":"N-COUNT 可数名词","cn":"（每年某一时期海水涌入江河的）涌潮,激潮","en":"A bore is a very large wave that moves quickly up certain rivers from the sea at particular times of the year as a result of unusual tides."},{"pos":"","cn":"","en":"Bore is the past tense of bear ."}]},"examples":[{"en":"Has he been boring you with his stories about his trip?","cn":"他是不是用他旅游的见闻在烦你？"},{"en":"His blue eyes seemed to bore into her.","cn":"他的一双蓝眼睛似乎要穿透她。"}],"base":"bear"},"boiled":{"lemma":"boil"},"bottoms":{"lemma":"bottom","media":{"uk":"media/uk/bottom__gb_1.mp3","us":"media/us/bottom__us_1.mp3"}},"born":{"media":{"uk":"media/uk/born__gb_1.mp3","us":"media/us/born__us_1.mp3"},"oxford":{"phon":"bɔːn","pos":"verb","senses":[{"en":"to come out of your mother’s body at the beginning of your life","cn":"出生；出世","lab":"often ironic) 102／23 （） 102／23 （）","ex":{"en":"I was born in 1976.","cn":"我生于 1976 年。"}},{"en":"to start to exist","cn":"出现；形成；成立","ex":{"en":"the city where the protest movement was born","cn":"抗议运动发源的城市"}},{"en":"born in the order, way, place, etc. mentioned","cn":"以…的顺序（或方式、地点等）出生的","ex":{"en":"firstborn","cn":"第一个孩子"}},{"en":"having a natural ability or skill for a particular activity or job","cn":"天生（有某方面才能）的","ex":{"en":"a born athlete/writer/leader","cn":"天生的运动员／作家／领袖"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"V-PASSIVE 被动动词","cn":"出生；诞生；为…所生","en":"When a baby is born, it comes out of its mother's body at the beginning of its life. In formal English, if you say that someone is born of someone or to someone, you mean that person is their parent.","ex":{"en":"My mother was 40 when I was born","cn":"母亲生我时40岁。"}},{"pos":"V-PASSIVE 被动动词","cn":"生下来（有某种疾病或问题）；天生（具有某种性格）","en":"If someone is born with a particular disease, problem, or characteristic, they have it from the time they are born.","ex":{"en":"He was born with only one lung.","cn":"他生下来就只有一叶肺。"}},{"pos":"V-PASSIVE 被动动词","cn":"（用于姓名前）出生（取名…的）","en":"You can use be born in front of a particular name to show that a person was given this name at birth, although they may be better known by another name.","ex":{"en":"She was born Jenny Harvey on June 11, 1946.","cn":"她在1946年6月11号出生，取名叫珍妮·哈维。"}},{"pos":"ADJ 形容词","cn":"天生的","en":"You use born to describe someone who has a natural ability to do a particular activity or job. For example, if you are a born cook, you have a natural ability to cook well.","ex":{"en":"Jack was a born teacher.","cn":"杰克天生是个当老师的料。"}},{"pos":"V-PASSIVE 被动动词","cn":"（思想、组织等）产生，诞生","en":"When an idea or organization is born, it comes into existence. If something is born of a particular emotion or activity, it exists as a result of that emotion or activity.","ex":{"en":"The idea for the show was born in his hospital room","cn":"这个节目的构思是他在医院病房里想出来的。"}},{"pos":"","cn":"","en":"to be born and bred→see: ; to be born with a silver spoon in your mouth→see: ;"}]},"examples":[{"en":"John Wayne was born Marion Michael Morrison (= that was his name at birth).","cn":"约翰 · 韦恩出生时取名马里恩 · 迈克尔 · 莫里森。"},{"en":"Oh yeah? I wasn't born yesterday, you know.","cn":"是吗？我可不是三岁的小孩子，你知道的。"}],"base":"bear"},"borrow":{"oxford":{"phon":"ˈbɒrəʊ","pos":"verb","senses":[{"en":"to take and use something that belongs to somebody else, and return it to them at a later time","cn":"借；借用","g":"[transitive]","lab":"British English, informal，，","ex":{"en":"Can I borrow your umbrella?","cn":"借你的伞用一下行吗？"}},{"en":"to take money from a person or bank and agree to pay it back to them at a later time","cn":"借入（款项）；（向…）借贷","g":"[transitive, intransitive]","lab":"informal","ex":{"en":"How much did you have to borrow to pay for this?","cn":"你得借多少钱来付这个？"}},{"en":"to take words, ideas, etc. from another language, person, etc. and use them as your own","cn":"引用，借用（言语、思想等）","g":"[intransitive, transitive]","ex":{"en":"The author borrows heavily from Henry James.","cn":"那位作家大量引用亨利·詹姆斯的作品。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"借；借用","en":"If you borrow something that belongs to someone else, you take it or use it for a period of time, usually with their permission.","ex":{"en":"Can I borrow a pen please? ","cn":"我可以借支笔吗？"}},{"pos":"VERB 动词","cn":"借（钱）；贷（款）","en":"If you borrow money from someone or from a bank, they give it to you and you agree to pay it back at some time in the future.","ex":{"en":"Morgan borrowed £5,000 from his father to form the company 20 years ago","cn":"20年前摩根从他父亲那里借了5,000英镑，成立了这家公司。"}},{"pos":"VERB 动词","cn":"借（书）","en":"If you borrow a book from a library, you take it away for a fixed period of time.","ex":{"en":"I couldn't afford to buy any, so I borrowed them from the library.","cn":"我一本书也买不起，只好从图书馆借。"}},{"pos":"VERB 动词","cn":"采用，借用（词语、想法等）","en":"If you borrow something such as a word or an idea from another language or from another person's work, you use it in your own language or work.","ex":{"en":"I borrowed his words for my book's title","cn":"我借用他的话作为我这本书的标题。"}},{"pos":"PHRASE 短语","cn":"捡回一条命；余下的光阴不多；好景不长","en":"Someone who is living on borrowed time or who is on borrowed time has continued to live or to do something for longer than was expected, and is likely to die or be stopped from doing it soon.","ex":{"en":"Perhaps that illness, diagnosed as fatal, gave him a sense of living on borrowed time.","cn":"也许是那种被诊断为绝症的疾病让他有了时日无多之感。"}}]},"media":{"uk":"media/uk/borrow__gb_1.mp3","us":"media/us/borrow__us_1.mp3"},"examples":[{"en":"The author borrows heavily from Henry James.","cn":"那位作家大量引用亨利 · 詹姆斯的作品。"},{"en":"She borrowed £2 000 from her parents.","cn":"她向她的父母借了 2 000 英镑。"}]},"bowls":{"lemma":"bowl","media":{"img":["media/pic/bowls_hobbies_comp.jpg","media/thumb/bowls.jpg"],"uk":"media/uk/bowl__gb_1.mp3","us":"media/us/bowl__us_1.mp3"}},"boyish":{"media":{"uk":"media/uk/boyish__gb_1.mp3","us":"media/us/boyish__us_1.mp3"},"oxford":{"phon":"ˈbɔɪɪʃ","pos":"adjective","senses":[{"en":"looking or behaving like a boy, in a way that is attractive","cn":"（长相或举止）像男孩的，顽皮可爱的","ex":{"en":"boyish charm/enthusiasm","cn":"男孩般的魅力／热心"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（外貌或举止）男孩子气的，稚气的","en":"If you describe a man as boyish, you mean that he is like a boy in his appearance or behaviour, and you find this characteristic quite attractive.","ex":{"en":"She was relieved to see his face light up with a boyish grin","cn":"看到他脸上现出孩子气的笑容，她总算松了口气。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（女子）长得像男孩子的，假小子的","en":"If you describe a girl or woman as boyish, you mean that she looks like a boy, for example because she has short hair or small breasts.","ex":{"en":"...her tall, boyish figure.","cn":"她高挑的男孩子般的身材"}}]},"examples":[{"en":"her slim boyish figure","cn":"她那男孩子般修长的体形"},{"en":"boyish charm/enthusiasm","cn":"男孩般的魅力/热心"}]},"boots":{"oxford":{"phon":"buːts","pos":"","senses":[{"en":"a company with shops in almost every town in Britain. The shops provide pharmaceutical services (= they prepare medicines) and sell a wide range of health and beauty products, as well as some food. The company also provides eye-care services. The company was founded in Nottingham in 1849.","cn":"靴子：一家在英国几乎每个城镇都有商店的公司。这些商店提供药品服务，并出售各种保健和美容产品以及一些食品。该公司还提供眼保健服务。该公司于1849年在诺丁汉成立。"}]},"media":{"uk":"media/ldoce/hwd/bre/c/lpd_boots.mp3","us":"media/ldoce/hwd/ame/c/lpd_boots.mp3"},"base":"boot"},"bottlenecks":{"oxford":{"phon":"ˈbɒtlnek","pos":"noun","senses":[{"en":"a narrow or busy section of road where the traffic often gets slower and stops","cn":"瓶颈路段，狭窄街道（常引起交通阻塞）"},{"en":"anything that delays development or progress, particularly in business or industry （","cn":"尤指工商业发展的）瓶颈，阻碍，障碍"}]}},"boxes":{"lemma":"box"},"boarders":{"oxford":{"phon":"ˈbɔːdə(r)","pos":"noun","senses":[{"en":"a child who lives at school and goes home for the holidays","cn":"在学校寄宿的学生；寄宿生"},{"en":"a person who pays money to live in a room in sb else's house","cn":"付费寄住者；寄膳宿者"}]}},"books":{"lemma":"book"},"boughs":{"oxford":{"phon":"baʊ","pos":"noun","senses":[{"en":"a large branch of a tree","cn":"大树枝"}]}},"boomers":{"lemma":"boomer"},"boosted":{"lemma":"boost"},"bodies":{"lemma":"body"},"boasts":{"lemma":"boast"},"boats":{"lemma":"boat","media":{"img":["media/pic/boats_comp.jpg"]}},"booming":{"lemma":"boom","media":{"uk":"media/ldoce/hwd/bre/6/brelasdeboom.mp3","us":"media/ldoce/hwd/ame/8/boom1.mp3"}},"boutiques":{"lemma":"boutique"},"bowing":{"lemma":"bow"},"bones":{"lemma":"bone"},"bolts":{"lemma":"bolt"},"bosses":{"lemma":"boss"},"boards":{"lemma":"board"},"booked":{"lemma":"book"},"boosting":{"lemma":"boost"},"bodied":{"lemma":"body"},"bonded":{"lemma":"bond"},"boys":{"lemma":"boy"},"bookstore":{"oxford":{"phon":"ˈbʊkʃɒp","pos":"noun","senses":[{"en":"a shop/store that sells books","cn":"书店"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"书店","en":"A bookstore is a shop where books are sold."}]},"media":{"uk":"media/ldoce/hwd/bre/5/bookstore0205.mp3","us":"media/ldoce/hwd/ame/3/bookstore.mp3"}},"bonds":{"lemma":"bond"},"boarded":{"lemma":"board"},"boulevards":{"lemma":"boulevard"},"boggling":{"oxford":{"phon":"ˈbɒɡl","pos":"verb","senses":[{"en":"( informal ) to be slow to do or accept sth because you are surprised or shocked by it （","cn":"因吃惊而）不知所措，犹豫不决"},{"en":"( informal ) if sth boggles the mind or the mind boggles at it, it is so unusual that people find it hard to imagine or accept","cn":"使人无法想像；使人难以接受"}]}},"bookshelves":{"oxford":{"phon":"ˈbʊkʃelf","pos":"noun","senses":[{"en":"a shelf that you keep books on","cn":"书架"}]}},"bonkers":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"愚蠢的；疯狂的","en":"If you say that someone is bonkers, you mean that they are silly or act in a crazy way.","ex":{"en":"The man must be bonkers to take such a risk","cn":"这人一定是疯了，居然去冒这种风险。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"slightly crazy","cn":"疯疯癫癫的﹔傻呵呵的"},{"en":"to make someone feel crazy or very annoyed","cn":"使某人发疯[苦恼不已]"}]},"collocations":{"phrases":["VERBS be | go I went a bit bonkers when he told me the news. | drive sb The noise nearly drove me bonkers.","ADV. absolutely, completely, plain, stark raving, totally I think he's absolutely stark raving bonkers! The whole idea is just plain bonkers"]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41bonkers.mp3","us":"media/ldoce/hwd/ame/d/bonkers.mp3"},"examples":[{"en":"I'll go bonkers if I have to wait any longer.","cn":"如果再等下去，我非发疯不可。"},{"en":"Thinking about the whole problem has driven me nearly bonkers.","cn":"想着这整个问题﹐我都快发疯了。"}],"oxford":{"phon":"ˈbɒŋkəz","pos":"adjective","senses":[{"en":"completely crazy and silly","cn":"疯狂；愚蠢透顶","ex":{"en":"I'll go bonkers if I have to wait any longer.","cn":"如果再等下去，我非发疯不可。"}}]}},"bonus":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"奖金；津贴","en":"A bonus is an extra amount of money that is added to someone's pay, usually because they have worked very hard.","ex":{"en":"Workers in big firms receive a substantial part of their pay in the form of bonuses and overtime.","cn":"大公司的员工有相当一部分薪酬来自奖金和加班费。"}},{"pos":"N-COUNT 可数名词","cn":"额外的好处；意外收获","en":"A bonus is something good that you get in addition to something else, and which you would not usually expect.","ex":{"en":"We felt we might finish third. Any better would be a bonus","cn":"我们感觉我们可能会获得第三名，要是能比这个名次更好那就是意外的惊喜了。"}},{"pos":"N-COUNT 可数名词","cn":"（保险公司付给投保人的）红利，余利","en":"A bonus is a sum of money that an insurance company pays to its policyholders, for example a percentage of the company's profits.","ex":{"en":"These returns will not be enough to meet the payment of annual bonuses to policyholders.","cn":"这些收益不够支付投保人每年分得的红利。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money that you receive from working, investments etc","cn":""},{"en":"the pay that professional people such as teachers or lawyers earn every year","cn":""},{"en":"the pay that someone earns every hour or every week","cn":""}]},"collocations":{"phrases":["ADJ. big, huge, large | extra, special | cash | annual, Christmas All employees get an annual bonus before the summer holidays. | loyalty, p","VERB + BONUS award (sb), give sb, pay sb | earn, get, receive You will receive a bonus for high levels of productivity. | lose If you don't ","BONUS + NOUN payment, scheme All workers participate in the bonus scheme.","PREP. ~ of He was awarded a cash bonus of &pound; 200. 2 sth extra that is good","ADJ. great, huge, major, real | added, extra The house is very comfortable, and as an added bonus, it's near to buses and trains. | unexpect","PREP. ~ for The sunshine on the final day was a welcome bonus for the spectators."]},"media":{"uk":"media/ldoce/hwd/bre/e/bonus0205.mp3","us":"media/ldoce/hwd/ame/2/bonus.mp3"},"examples":[{"en":"Being able to walk to work is an added bonus of the new job.","cn":"能够步行去上班是这份新工作额外的好处。"},{"en":"a £100 Christmas bonus * 100","cn":"英镑圣诞节奖金"}],"oxford":{"phon":"ˈbəʊnəs","pos":"noun","senses":[{"en":"an extra amount of money that is added to a payment, especially to somebody’s wages or salary as a reward","cn":"奖金；红利","ex":{"en":"a £100 Christmas bonus","cn":"100 英镑圣诞节奖金"}},{"en":"anything pleasant that is extra and more or better than you were expecting","cn":"意外收获","g":"[usually singular]","ex":{"en":"Being able to walk to work is an added bonus of the new job.","cn":"能够步行去上班是这份新工作额外的好处。"}}]}},"bodyguard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"保镖；警卫（队）","en":"A bodyguard is a person or a group of people employed to protect someone.","ex":{"en":"Three of his bodyguards were injured in the attack","cn":"在这次袭击事件中，他有3名保镖受了伤。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to watch a place, person, or valuable object, in order to protect them or stop them escaping","cn":""},{"en":"a person or group of people whose job is to protect someone important","cn":""},{"en":"a person or organization that protects, or appears to protect, someone or something that people think is important or morally right","cn":""}]},"collocations":{"phrases":["ADJ. armed | personal He never goes anywhere without his personal bodyguards.","VERB + BODYGUARD have, keep She has to have an armed bodyguard wherever she goes.","BODYGUARD + VERB protect sb","PREP. ~ of He keeps a bodyguard of ten men. | ~ to a former bodyguard to the prince • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/d/bodyguard0205.mp3","us":"media/ldoce/hwd/ame/c/bodyguard.mp3"},"examples":[{"en":"The President's bodyguard is/are armed.","cn":"总统的护卫人员携带着武器。"},{"en":"The senator arrived, surrounded by personal bodyguards.","cn":"这位参议员在私人保镖的簇拥下抵达。"}],"oxford":{"phon":"ˈbɒdiɡɑːd","pos":"noun","senses":[{"en":"a person or a group of people who are employed to protect somebody","cn":"保镖，警卫（队）","ex":{"en":"The President’s bodyguard is/are armed.","cn":"总统的护卫人员携带着武器。"}}]}},"bosom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（女子的）乳房","en":"A woman's breasts are sometimes referred to as her bosom or her bosoms.","ex":{"en":"...a large young mother with a baby resting against her ample bosom.","cn":"让怀中婴儿靠在她丰满胸部上的身材高大的年轻母亲"}},{"pos":"N-SING 单数名词","cn":"怀抱；关怀","en":"If you are in the bosom of your family or of a community, you are among people who love, accept, and protect you.","ex":{"en":"Joan was delighted to welcome her boyfriend into the bosom of her large, close-knit family.","cn":"琼十分高兴地欢迎她的男朋友加入她亲密无间的大家庭。"}},{"pos":"ADJ 形容词","cn":"（朋友）知心的，亲密的","en":"A bosom friend is a friend who you know very well and like very much indeed.","ex":{"en":"They were bosom friends","cn":"他们是知心好友。"}},{"pos":"PHRASE 短语","cn":"接纳；关怀；关爱","en":"If you take someone or something to your bosom, you accept them and treat or regard them with great affection.","ex":{"en":"We, at least, have taken her to our bosom.","cn":"至少我们对她是关爱有加的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the front part of a woman’s chest 〔","cn":"女人的〕胸部"},{"en":"a woman’s breast 〔","cn":"妇女的〕乳房"},{"en":"the situation where you feel safe because you are with people who love and protect you","cn":"家庭/教会等的温暖怀抱"}]},"vocab":{"pos":"n v","senses":[{"en":"The bosom is the breast or chest area of the body. It is also poetically considered to be the place where our feelings reside."}]},"collocations":{"phrases":["ADJ. ample, enormous, large, full","BOSOM + VERB heave, rise and fall Her bosom rose and fell; she was out of breath from keeping up with him.","PHRASES clutch sb/sth to your bosom (literary) She clutched her son tightly to her bosom."]},"media":{"uk":"media/ldoce/hwd/bre/0/bosom0205.mp3","us":"media/ldoce/hwd/ame/b/bosom.mp3"},"examples":[{"en":"She pressed him to her bosom.","cn":"她紧紧地把他抱在胸前。"},{"en":"a rose pinned to her bosom","cn":"别在她胸襟上的一朵玫瑰"}],"oxford":{"phon":"ˈbʊzəm","pos":"noun","senses":[{"en":"a woman’s chest or breasts","cn":"女人的胸部（或乳房）","g":"[countable]","ex":{"en":"her ample bosom","cn":"她丰满的乳房"}},{"en":"the part of a piece of clothing that covers a woman’s bosom","cn":"女衣胸部（或胸襟）","g":"[countable]","ex":{"en":"a rose pinned to her bosom","cn":"别在她胸襟上的一朵玫瑰"}},{"en":"a situation in which you are with people who love and protect you","cn":"和爱护自己的人在一起的情形；在…的怀抱中","g":"[singular]","ex":{"en":"to live in the bosom of your family","cn":"生活在家庭的温暖怀抱中"}}]}},"booty":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"赃物；（尤指）战利品","en":"Booty is a collection of valuable things stolen from a place, especially by soldiers after a battle.","ex":{"en":"Troops destroyed the capital and confiscated many works of art as war booty.","cn":"军队摧毁了这座都城，并把大量艺术品收缴为战利品。"}},{"pos":"","cn":"屁股","en":"Someone's booty is their bottom."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"valuable things that a group of people, especially an army that has just won a victory, take away from somewhere","cn":"赃物﹔缴获物；战利品"},{"en":"the part of your body that you sit on","cn":"屁股"}]},"vocab":{"pos":"n","senses":[{"en":"Booty is treasure — money, jewels, and the like — obtained by criminal means, especially plundering or pillaging. If you're in the Caribbean on vacation, you could spend some time looking for buried pirate booty ."}]},"collocations":{"phrases":["ADJ. war","VERB + BOOTY capture, carry off, seize, take | divide, share, split They divided the booty among the troops."]},"media":{"uk":"media/ldoce/hwd/bre/a/booty0205.mp3","us":"media/ldoce/hwd/ame/8/booty.mp3"},"examples":[{"en":"When we got home from our day's shopping, we laid all our booty out on the floor.","cn":"我们购物一天回到家里，把搜罗到的好东西都摊开摆在地板上。"},{"en":"to shake your booty (= to dance with great energy)","cn":"扭屁股（指用力跳舞）"}],"oxford":{"phon":"ˈbuːti","pos":"noun","senses":[{"en":"valuable things that are stolen, especially by soldiers in a time of war","cn":"赃物；掠夺物；战利品","g":"[uncountable]"},{"en":"valuable things that somebody wins, buys or obtains","cn":"（赢得、购买、得到的）贵重物品","g":"[uncountable]","lab":"informal","ex":{"en":"When we got home from our day's shopping, we laid all our booty out on the floor.","cn":"我们购物一天回到家里，把搜罗到的好东西都摊开摆在地板上。"}},{"en":"the part of the body that you sit on","cn":"屁股","g":"[countable]","lab":"especially North American English, informal，，","ex":{"en":"to shake your booty (= to dance with great energy)","cn":"扭屁股（指用力跳舞）"}}]}},"bowling":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"保龄球运动","en":"Bowling is a game in which you roll a heavy ball down a narrow track towards a group of wooden objects and try to knock down as many of them as possible.","ex":{"en":"I go bowling for relaxation.","cn":"我打保龄球是为了消遣。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（板球等运动中的）投球","en":"In a sport such as cricket, bowling is the action or activity of bowling the ball towards the batsman."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an indoor game in which you roll a large heavy ball along a wooden track in order to knock down a group of pin s (= wooden objects shaped like bottles )","cn":"保龄球"},{"en":"the act of throwing a ball at the batsman in cricket 〔","cn":"玩板球时向击球员的〕投球"}]},"collocations":{"phrases":["ADJ. tenpin","VERB + BOWLING go Let's go bowling on Saturday.","BOWLING + NOUN ball | alley | green •","ADJ. fast, pace, quick | slow | seam, spin, swing | short-pitched | intimidatory","VERB + BOWLING open McArthur opened the bowling on the first day of the match.","BOWLING + NOUN attack England were no match for the Indian bowling attack. | average | crease"]},"media":{"img":["media/ldoce/img/bowling.jpg"],"uk":"media/ldoce/hwd/bre/3/bowling0205.mp3","us":"media/ldoce/hwd/ame/8/bowling.mp3"},"examples":[{"en":"Do you want to go bowling with us Friday?","cn":"星期五想和我们一起去打保龄球吗？"}],"oxford":{"phon":"ˈbəʊlɪŋ","pos":"noun","senses":[{"en":"a game in which players roll heavy balls (called bowls) along a special track towards a group of pins (= objects that are like bottles in shape) and try to knock over as many of them as possible","cn":"保龄球运动","ex":{"en":"Let's go bowling on Saturday.","cn":"我们周六去打保龄球吧。"}},{"en":"the action of the bowler in throwing the ball towards the batsman","cn":"投球","ex":{"en":"a brilliant display of fast bowling","cn":"快速投球的精彩示范"}}]},"base":"bowl"},"bowel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肠","en":"Your bowels are the tubes in your body through which digested food passes from your stomach to your anus."},{"pos":"N-PLURAL 复数名词","cn":"大便","en":"You can refer in a polite way to someone getting rid of the waste from their body by saying that they move, open, or empty their bowels ."},{"pos":"N-PLURAL 复数名词","cn":"内部；深处","en":"You can refer to the parts deep inside something such as the earth, a building, or a machine as the bowels of that thing.","ex":{"en":"...deep in the bowels of the earth","cn":"在地心深处"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the system of tubes inside your body where food is made into solid waste material and through which it passes out of your body","cn":"肠"},{"en":"one part of this system of tubes","cn":"肠道"},{"en":"the act of getting rid of solid waste from your body","cn":"大解﹐排便"}]},"collocations":{"phrases":["ADJ. large, small","VERB + BOWEL empty, evacuate, move, open","BOWEL + NOUN action, function, habit, movement Patients are asked to report any change in bowel habit. He's been having painful bowel moveme","PREP. in the ~","PHRASES irritable bowel syndrome"]},"media":{"uk":"media/ldoce/hwd/bre/5/bowel0205.mp3","us":"media/ldoce/hwd/ame/7/laadbowel.mp3"},"examples":[{"en":"A rumble came from the bowels of the earth (= deep underground).","cn":"从地下深处传来隆隆的响声。"},{"en":"to empty/move/open your bowels (= to pass solid waste out of the body)","cn":""}],"oxford":{"phon":"ˈbaʊəl","pos":"noun","senses":[{"en":"the tube along which food passes after it has been through the stomach, especially the end where waste is collected before it is passed out of the body","cn":"肠","g":"[countable, usually plural]","lab":"medical","ex":{"en":"to empty/move/open your bowels (= to pass solid waste out of the body)","cn":"解大便"}},{"en":"the part that is deepest inside something","cn":"内部最深处","g":"[plural]","lab":"literary","ex":{"en":"A rumble came from the bowels of the earth (= deep underground).","cn":"从地下深处传来隆隆的响声。"}}]}},"boulevard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"林阴大道","en":"A boulevard is a wide street in a city, usually with trees along each side.","ex":{"en":"...Lenton Boulevard.","cn":"伦顿林阴大道"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a hard surface for cars, buses etc to drive on","cn":""},{"en":"a road in a town, with houses or shops on each side","cn":""},{"en":"a road in a town, often with trees on each side","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A boulevard is a type of street. You can get to school by taking the four-lane boulevard , but to avoid all the traffic, you might use the less-traveled side streets."}]},"collocations":{"phrases":["ADJ. broad, wide | tree-lined","BOULEVARD + VERB be lined with sth a boulevard lined with pavement cafes","PREP. along, down, up, etc. a/the ~ They sauntered along the tree-lined boulevard."]},"media":{"uk":"media/ldoce/hwd/bre/f/boulevard0205.mp3","us":"media/ldoce/hwd/ame/8/boulevard.mp3"},"examples":[{"en":"Sunset Boulevard","cn":"日落大道"}],"oxford":{"phon":"ˈbuːləvɑːd","pos":"noun","senses":[{"en":"a wide city street, often with trees on either side","cn":"（市区的）林荫大道","ex":{"en":"It is a city of broad boulevards and spacious parks.","cn":"这是一座拥有宽阔林荫大道和宽敞公园的城市。"}},{"en":"a wide main road (often used in the name of streets)","cn":"（常用作街道名称）要道，大街","lab":"North American English","ex":{"en":"Sunset Boulevard","cn":"日落大道"}}]}},"bog":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"沼泽；湿地；泥塘","en":"A bog is an area of land which is very wet and muddy."},{"pos":"N-COUNT 可数名词","cn":"厕所；茅厕","en":"The bog is another name for the toilet."},{"pos":"","cn":"","en":"相关词组：bog down"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area of low flat ground that is always wet and soft, that often has grasses or reed s growing in it but no trees","cn":""},{"en":"land that is always very wet or covered with a layer of water, that often has trees growing in it – used especially about areas in hot countries","cn":""},{"en":"an area of low wet muddy ground, sometimes with bushes or grasses growing in it","cn":""}]},"vocab":{"pos":"1 n 2 v","senses":[{"en":"You'd be pretty soggy by morning if you accidentally set your tent up in a bog . A bog is a swampy kind of ground made up mostly of decomposing plants and mosses."}]},"collocations":{"phrases":["ADJ. vast | stagnant, swampy | peat","VERB + BOG sink into The more she struggled the deeper she sank into the bog.","PREP. in a/the ~ He found himself in a vast stagnant bog. | through a/the ~ walking through a bog"]},"media":{"uk":"media/ldoce/hwd/bre/f/bog_v0205.mp3","us":"media/ldoce/hwd/ame/1/bog1.mp3"},"examples":[{"en":"We mustn't get bogged down in details.","cn":"我们一定不能因细节问题误事。"},{"en":"The tank became bogged down in mud.","cn":"坦克陷入了烂泥中。"}],"oxford":{"phon":"bɒɡ","pos":"noun","senses":[{"en":"(an area of) wet soft ground, formed of decayed (= destroyed by natural processes) plants","cn":"沼泽（地区）","g":"[countable, uncountable]","ex":{"en":"Like oil, gas and coal fields, peat bogs act as vast carbon stores.","cn":"与石油、天然气和煤田一样，泥炭沼泽也是巨大的碳库。"}},{"en":"a toilet","cn":"盥洗室；厕所","g":"[countable]","lab":"British English, slang，，","ex":{"en":"Have you got any bog roll (= toilet paper)?","cn":"你带卫生纸了吗？"}}]}},"bombardment":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（猛烈而持久的）炮击，轰炸","en":"A bombardment is a strong and continuous attack of gunfire or bombing.","ex":{"en":"The city has been flattened by heavy artillery bombardments","cn":"城市已被猛烈的炮火夷为平地。"}},{"pos":"N-VAR 可变名词","cn":"一连串（想法、要求、质问或批评）","en":"A bombardment of ideas, demands, questions, or criticisms is an aggressive and exhausting stream of them.","ex":{"en":"...the constant bombardment of images urging that work was important.","cn":"铺天盖地的图片，强调工作是至关重要的"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt to shoot someone or something","cn":""},{"en":"when someone is shot at, and killed or injured","cn":""},{"en":"the repeated shooting of a gun or guns","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When a lot of bombs fall on a city or area, it is a bombardment . But a bombardment can also mean a pummeling with lots of other things: questions, spit balls, or e-mails."}]},"collocations":{"phrases":["ADJ. constant, continuous | heavy, intense | aerial, artillery, naval","VERB + BOMBARDMENT conduct, launch, mount | stop | be subjected to, be under, come under, suffer | survive, withstand They have withstood he","BOMBARDMENT + VERB begin, start | continue, resume | (come to an) end, cease, stop","PREP. during/in a/the ~ Many people were killed in the bombardment. | under ~ The city has been under constant bombardment for three days. |"]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41bombardment.mp3","us":"media/ldoce/hwd/ame/7/bombardment.mp3"},"examples":[{"en":"The city came under heavy bombardment.","cn":"那座城市受到猛烈轰炸。"},{"en":"The bombardment continued for a terrible nine hours.","cn":"轰炸可怕地持续了九个小时。"}],"oxford":{"phon":"bɒmˈbɑːdmənt","pos":"noun","senses":[{"en":"an attack in which large guns are fired at a place or bombs are dropped on it continuously","cn":"轰炸；炮击","ex":{"en":"The city came under heavy bombardment.","cn":"这座城市遭到狂轰滥炸。"}},{"en":"an occasion when too many questions or criticisms are aimed at somebody or they are given too much information","cn":"连续提问，连续（口头等）攻击","ex":{"en":"these days of media bombardment","cn":"在媒体狂轰滥炸的今天"}}]}},"boardroom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"董事会会议室","en":"The boardroom is a room where the board of a company meets.","ex":{"en":"Everyone had already assembled in the boardroom for the 9:00 a.m. session.","cn":"所有人都已集中到了董事会会议室，准备参加上午9点钟的会议。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room where the director s of a company have meetings","cn":"董事会会议室"}]},"collocations":{"phrases":["ADJ. company, corporate","BOARDROOM + NOUN battle, coup, row, shake-up | table | pay, salary The massive boardroom pay awards were criticized by the workers.","PHRASES in a/the ~ The directors were working overtime in the boardroom."]},"media":{"uk":"media/ldoce/hwd/bre/a/boardroom0205.mp3","us":"media/ldoce/hwd/ame/e/boardroom.mp3"},"examples":[{"en":"a boardroom row","cn":"董事会会议上的争吵"}],"oxford":{"phon":"ˈbɔːdruːm","pos":"noun","senses":[{"en":"a room in which the meetings of the board of a company (= the group of people who control it) are held","cn":"董事会会议室","ex":{"en":"a boardroom row","cn":"董事会会议上的争吵"}}]}},"boycott":{"collins":{"senses":[{"pos":"VERB 动词","cn":"抵制；拒绝参加","en":"If a country, group, or person boycotts a country, organization, or activity, they refuse to be involved with it in any way because they disapprove of it.","ex":{"en":"The main opposition parties are boycotting the elections.","cn":"主要反对党都抵制此次选举。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something to show publicly that you disagree with something – used especially when a large group of people do this together","cn":""},{"en":"to walk in a large group from one place to another in order to protest about something","cn":""},{"en":"to walk or stand somewhere in a large group, in order to protest about something","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To boycott means to stop buying or using the goods or services of a certain company or country as a protest; the noun boycott is the protest itself."}]},"collocations":{"phrases":["ADV. officially","VERB + BOYCOTT threaten to | call on sb to, urge sb to They have urged people to boycott foreign products."]},"media":{"uk":"media/ldoce/hwd/bre/4/boycott_v0205.mp3","us":"media/ldoce/hwd/ame/0/boycott.mp3"},"examples":[{"en":"We are asking people to boycott goods from companies that use child labour.","cn":"我们正呼吁大家抵制雇用童工的公司的产品。"},{"en":"a trade boycott of British goods","cn":"对英国货品的贸易抵制"}],"oxford":{"phon":"ˈbɔɪkɒt","pos":"verb","senses":[{"en":"to refuse to buy, use or take part in something as a way of protesting","cn":"拒绝购买（或使用、参加）；抵制","ex":{"en":"We are asking people to boycott goods from companies that use child labour.","cn":"我们正呼吁大家抵制雇用童工的公司的产品。"}},{"en":"an act of boycotting somebody/something","cn":"（对某事物的）抵制","ex":{"en":"a trade boycott of British goods","cn":"对英国货品的贸易抵制"},"pos":"noun"}]}},"boss":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"老板；上司","en":"Your boss is the person in charge of the organization or department where you work.","ex":{"en":"He cannot stand his boss","cn":"他无法忍受他的老板。"}},{"pos":"N-COUNT 可数名词","cn":"领导；头儿；发号施令者","en":"If you are the boss in a group or relationship, you are the person who makes all the decisions.","ex":{"en":"He thinks he's the boss.","cn":"他认为自己是头儿。"}},{"pos":"VERB 动词","cn":"对…颐指气使；对…指手画脚","en":"If you say that someone bosses you, you mean that they keep telling you what to do in a way that is irritating.","ex":{"en":"We cannot boss them into doing more","cn":"我们不能再差遣他们做更多的事了。"}},{"pos":"PHRASE 短语","cn":"为自己打工；自己拿主意","en":"If you are your own boss, you work for yourself or make your own decisions and do not have anyone telling you what to do.","ex":{"en":"I'm very much my own boss and no one interferes with what I do.","cn":"我自己很有主见，没有人干预我做的事。"}},{"pos":"","cn":"","en":"相关词组：boss around"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the person who is in charge of you at work. Boss sounds rather informal. The usual word to use in more formal English is manager","cn":""},{"en":"the person in charge of a business such as a shop, a bank, or a hotel, or of a part of a business","cn":""},{"en":"the person who is in charge of an organization or a department within that organization","cn":""}]},"collocations":{"phrases":["ADJ. big | company, party, union"]},"media":{"uk":"media/ldoce/hwd/bre/5/boss_v0205.mp3","us":"media/ldoce/hwd/ame/7/boss1.mp3"},"examples":[{"en":"I'll ask my boss if I can have the day off.","cn":"我要问一下老板我能不能请一天假。"},{"en":"I like being my own boss (= working for myself and making my own decisions).","cn":"我喜欢自己做老板，自己拿主意。"}],"oxford":{"phon":"bɒs","pos":"noun","senses":[{"en":"a person who is in charge of other people at work and tells them what to do","cn":"老板；工头；领班","ex":{"en":"I'll ask my boss if I can have the day off.","cn":"我要问一下老板我能不能请一天假。"}},{"en":"a person who is in charge of a large organization","cn":"总经理；领导","lab":"informal","ex":{"en":"the new boss at IBM","cn":"IBM 公司的新领导"}},{"en":"to tell somebody what to do in an aggressive and/or annoying way","cn":"对（某人）发号施令","ex":{"en":"I'm sick of you bossing me around!","cn":"我讨厌你对我指手画脚。"},"pos":"verb"},{"en":"very good","cn":"很好的","ex":{"en":"She's a real boss chick.","cn":"她是数一数二的人物。"},"pos":"adjective"}]}},"boastfulness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is boastful boasts a lot","cn":""},{"en":"someone who is big-headed thinks that they are very important and shows this by often boasting about their abilities or achievements","cn":""},{"en":"if you say that someone is all talk , you mean that they make all their plans and their achievements seem more impressive than they really are, and people should not believe them","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/boastful0205.mp3","us":"media/ldoce/hwd/ame/c/boastful.mp3"}},"boast":{"collins":{"senses":[{"pos":"VERB 动词","cn":"吹嘘；炫耀；夸耀","en":"If someone boasts about something that they have done or that they own, they talk about it very proudly, in a way that other people may find irritating or offensive.","ex":{"en":"Witnesses said Furci boasted that he took part in killing them","cn":"几位证人声称富尔奇曾吹嘘自己参与了对他们的屠杀。"}},{"pos":"VERB 动词","cn":"有，拥有（值得骄傲的成就或财产）","en":"If someone or something can boast a particular achievement or possession, they have achieved or possess that thing.","ex":{"en":"The houses will boast the latest energy-saving technology","cn":"这些房屋将应用最新的节能技术。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to talk too proudly about your abilities, achievements, or possessions because you want other people to admire you","cn":""},{"en":"to boast in a way that annoys other people. Brag is more informal than boast","cn":""},{"en":"to talk a lot about your achievements – used especially when you want to mention your achievements but do not want to sound as if you are boasting","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you boast you are bragging about yourself and your accomplishments (or maybe those of your family), often to the boredom and annoyance of your audience."}]},"collocations":{"phrases":["ADV. openly","PREP. about/of He openly boasted of his talents. 2 have sth good/impressive","ADV. proudly This is a region which proudly boasts its own distinct culture."]},"media":{"uk":"media/ldoce/hwd/bre/b/boast_n0205.mp3","us":"media/ldoce/hwd/ame/6/boast1.mp3"},"examples":[{"en":"Despite his boasts that his children were brilliant, neither of them went to college.","cn":"尽管他夸赞他的两个孩子聪明，他们却都没念上大学。"},{"en":"It was her proud boast that she had never missed a day's work because of illness.","cn":"她所引以自豪的是她从未因病而耽误过一天工作。"}],"oxford":{"phon":"bəʊst","pos":"verb","senses":[{"en":"to talk in a way that shows you are too proud of something that you have or can do","cn":"自夸；自吹自擂","g":"[intransitive, transitive]","ex":{"en":"I don't want to boast, but I can actually speak six languages.","cn":"不是我吹嘘，我确实能讲六种语言。"}},{"en":"to have something that is impressive","cn":"拥有（令人印象深刻的事物）","g":"[transitive]","ex":{"en":"The hotel also boasts two swimming pools and a golf course.","cn":"那家酒店还有两个游泳池和一个高尔夫球场。"}},{"en":"something that a person talks about in a very proud way, often to seem more important or clever","cn":"夸耀；夸口","ex":{"en":"Despite his boasts that his children were brilliant, neither of them went to college.","cn":"尽管他夸赞他的两个孩子聪明，他们却都没念上大学。"},"pos":"noun"}]}},"boutique":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"时尚商店；时装店；精品店","en":"A boutique is a small shop that sells fashionable clothes, shoes, or jewellery."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building or place where things are sold","cn":""},{"en":"a small shop that sells fashionable clothes or other objects","cn":"时装店﹔精品店"},{"en":"a very large shop, especially one that is built outside the centre of a city","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A boutique is a small shop, especially one that sells women's clothes and jewelry. If you like to shop, you probably love going to all the little boutiques downtown."}]},"collocations":{"phrases":["ADJ. chic, elegant, exclusive, smart | fashion","VERB + BOUTIQUE open | run"]},"media":{"uk":"media/ldoce/hwd/bre/8/boutique0205.mp3","us":"media/ldoce/hwd/ame/2/boutique.mp3"},"examples":[{"en":"a boutique hotel that offers an escape from the outside world","cn":"让人远离尘世喧嚣的精品酒店"},{"en":"a boutique investment bank","cn":"精品投资银行"}],"oxford":{"phon":"buːˈtiːk","pos":"noun","senses":[{"en":"a small shop that sells fashionable clothes or expensive gifts","cn":"时装店；精品店"},{"en":"(of a business) small and offering products or services of a high quality to a small number of customers","cn":"（商店）精品的，提供专门服务的（针对少量顾客）","ex":{"en":"a boutique hotel that offers an escape from the outside world","cn":"让人远离尘世喧嚣的精品酒店"},"pos":"adjective"}]}},"bookkeeping":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"簿记；记账","en":"Bookkeeping is the job or activity of keeping an accurate record of the money that is spent and received by a business or other organization."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the job or activity of recording the financial accounts of an organization","cn":"记账﹐管账"}]},"collocations":{"phrases":["ADJ. double-entry | routine, simple","VERB + BOOKKEEPING do I run the shop and my wife does the bookkeeping.","BOOKKEEPING + NOUN entry | system"]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdebookkeeping.mp3","us":"media/ldoce/hwd/ame/2/bookkeeping.mp3"},"oxford":{"phon":"ˈbʊkkiːpɪŋ","pos":"noun","senses":[{"en":"the job or activity of keeping an accurate record of the accounts of a business","cn":"簿记员"}]}},"bonfire":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（焚烧垃圾的）火堆；（作为庆祝点燃的）篝火，营火","en":"A bonfire is a fire that is made outdoors, usually to burn rubbish. Bonfires are also sometimes lit as part of a celebration.","ex":{"en":"With bonfires outlawed in urban areas, gardeners must cart their refuse to a dump","cn":"由于市区明令禁止焚烧垃圾，园丁必须把垃圾运至垃圾场。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small, controlled fire that you make in order to provide heat or to cook food","cn":""},{"en":"a large outdoor fire used for burning dead leaves, wood, or things you do not need, or used for celebrations","cn":""},{"en":"a fire made outdoors for people who are camping, used for keeping them warm and cooking","cn":""}]},"collocations":{"phrases":["ADJ. blazing, roaring","VERB + BONFIRE build, have, make | light | put out | put sth on, throw sth on | gather/sit around/round","BONFIRE + VERB blaze, burn","BONFIRE + NOUN Night It was 5 November?Bonfire Night?and the children were excited."]},"media":{"uk":"media/ldoce/hwd/bre/d/bonfire0205.mp3","us":"media/ldoce/hwd/ame/0/bonfire.mp3"},"oxford":{"phon":"ˈbɒnfaɪə(r)","pos":"noun","senses":[{"en":"a large outdoor fire for burning waste or as part of a celebration","cn":"（在室外为焚烧垃圾或为庆祝而燃起的）大火堆，篝火","ex":{"en":"There will be a bonfire and a firework display.","cn":"将会点燃篝火，还会有烟火表演。"}}]}},"boyfriend":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男朋友；情人","en":"Someone's boyfriend is a man or boy with whom they are having a romantic or sexual relationship.","ex":{"en":"...Brenda and her boyfriend Anthony","cn":"布兰达和她的男友安东尼"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a boy or man that you have a romantic relationship with, especially for a fairly long time","cn":""},{"en":"the person you are married to, or the person you are living with and having a sexual relationship with","cn":""},{"en":"the man whom a woman is going to marry","cn":""}]},"collocations":{"phrases":["ADJ. current, latest, new | ex-, former, old | long-standing, long-term, serious, steady | live-in | jealous | jilted She was stalked by a j","QUANT. string, succession She had a string of wealthy boyfriends before she finally married.","VERB + BOYFRIEND have Have you got a boyfriend? | meet | live with | sleep with | marry","BOYFRIEND + NOUN trouble She's unhappy because she's been having boyfriend trouble."]},"media":{"uk":"media/ldoce/hwd/bre/c/boyfriend0205.mp3","us":"media/ldoce/hwd/ame/6/boyfriend.mp3"},"oxford":{"phon":"ˈbɔɪfrend","pos":"noun","senses":[{"en":"a man or boy that somebody has a romantic or sexual relationship with","cn":"男朋友","ex":{"en":"She's got a new boyfriend.","cn":"她有了新男友。"}}]}},"bouquet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"花束","en":"A bouquet is a bunch of flowers which is attractively arranged.","ex":{"en":"The woman carried a bouquet of dried violets.","cn":"这个女人拿着一束干枯的紫罗兰。"}},{"pos":"N-VAR 可变名词","cn":"（尤指葡萄酒散发的）香味，芬芳","en":"The bouquet of something, especially wine, is the pleasant smell that it has.","ex":{"en":"...a Sicilian wine with a light red colour and a bouquet of cloves.","cn":"颜色淡红、散发着丁香香味的西西里葡萄酒"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an arrangement of flowers, especially one that you give to someone","cn":"花束"},{"en":"the smell of a wine 〔","cn":"葡萄酒的〕芳香﹐香味"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A bouquet is an arrangement of flowers. A simple bouquet of flowers from your garden makes a lovely centerpiece for your table or a nice hostess gift when you are a guest."}]},"collocations":{"phrases":["ADJ. huge, large | small | bridal, wedding","VERB + BOUQUET carry | send (sb)","PREP. in a/the ~ Are there any roses in your bouquet? | ~ of He sent her a large bouquet of wild flowers."]},"media":{"img":["media/ldoce/img/bouquet.jpg"],"uk":"media/ldoce/hwd/bre/7/bouquet0205.mp3","us":"media/ldoce/hwd/ame/a/bouquet.mp3"},"examples":[{"en":"The little girl presented the princess with a large bouquet of flowers.","cn":"那小女孩向公主献上了一大束鲜花。"}],"oxford":{"phon":"buˈkeɪ","pos":"noun","senses":[{"en":"a bunch of flowers arranged in an attractive way so that it can be carried in a ceremony or presented as a gift","cn":"花束","g":"[countable]","ex":{"en":"The little girl presented the princess with a large bouquet of flowers.","cn":"那小女孩向公主献上了一大束鲜花。"}},{"en":"the pleasant smell of a type of food or drink, especially of wine","cn":"（尤指酒的）香味，芬芳","g":"[countable, uncountable]","ex":{"en":"a red wine with a full flavour and a fragrant bouquet","cn":"一款口感饱满、酒香芬芳的红酒"}}]}},"bout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（疾病或不愉快情绪的）发作","en":"If you have a bout of an illness or of an unpleasant feeling, you have it for a short period.","ex":{"en":"He was recovering from a severe bout of flu","cn":"他患了严重的流感，尚未痊愈。"}},{"pos":"N-COUNT 可数名词","cn":"（不愉快之事大量发生的）一阵，一小段时间","en":"A bout of something that is unpleasant is a short time during which it occurs a great deal.","ex":{"en":"The latest bout of violence has claimed twenty four lives","cn":"最近发生的一起暴力事件造成24人死亡。"}},{"pos":"N-COUNT 可数名词","cn":"拳击比赛；摔跤比赛","en":"A bout is a boxing or wrestling match.","ex":{"en":"This will be his eighth title bout in 19 months.","cn":"这将是他19个月里的第8次卫冕赛。"}},{"pos":"","cn":"（当about的第一个音节不发音时，有些作家以’bout或bout替代about）","en":"Some writers use 'bout or bout to represent about when the first syllable is not pronounced.","ex":{"en":"How 'bout some coffee?","cn":"来点儿咖啡吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you suddenly begin to have an illness that you often have, especially when this only continues for a short time","cn":""},{"en":"a short period of suffering from an illness, especially one that is not serious","cn":""},{"en":"a short period of suffering from an illness that is not serious","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A bout is a fight. If you want to be boxer, start with some easy bouts before challenging the champ."}]},"collocations":{"phrases":["ADJ. bad, nasty, prolonged, serious, severe I got a bad bout of flu last winter. | mild | drinking","VERB + BOUT get, have, suffer from","PREP. during a/the ~ | ~ of a bout of depression"]},"media":{"uk":"media/ldoce/hwd/bre/3/bout0205.mp3","us":"media/ldoce/hwd/ame/4/bout.mp3"},"examples":[{"en":"He suffered occasional bouts of depression.","cn":"他有时会犯抑郁症。"},{"en":"( NAmE ) a bout with the flu","cn":"流感发作期"}],"oxford":{"phon":"baʊt","pos":"noun","senses":[{"en":"a short period of great activity; a short period during which there is a lot of a particular thing, usually something unpleasant","cn":"一阵；一场；（尤指坏事的）一通，一次","ex":{"en":"They had been fighting after a drinking bout.","cn":"他们一顿狂饮之后一直在打架。"}},{"en":"an attack or period of illness","cn":"（疾病的）发作；发病期","lab":"North American English","ex":{"en":"a severe bout of flu/coughing","cn":"流感／咳嗽的猛烈发作"}},{"en":"a boxing or wrestling match","cn":"拳击（或摔跤）比赛","ex":{"en":"A karate bout lasts for two or three minutes.","cn":"空手道比赛持续两到三分钟。"}}]}},"boo":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发嘘声；喝倒彩","en":"If you boo a speaker or performer, you shout 'boo' or make other loud sounds to indicate that you do not like them, their opinions, or their performance.","ex":{"en":"People were booing and throwing things at them","cn":"人们向他们喝倒彩、掷东西。"}},{"pos":"EXCLAM 感叹语","cn":"嘿，砰（用于吓唬人时发出的声音）","en":"You say 'Boo!' loudly and suddenly when you want to surprise someone who does not know that you are there."},{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to shout 'boo' to show that you do not like a speaker, performance etc","cn":""},{"en":"to make a noise which sounds like 'ssss' to show that you do not like a speaker, performance etc","cn":""},{"en":"to shout rude remarks at someone or laugh unkindly at them to show that you strongly disapprove of them or their performance","cn":""}]},"collocations":{"phrases":["ADJ. loud","VERB + BOO be greeted/met with His speech was met with boos.","PREP. ~ from There were loud boos from the audience."]},"media":{"uk":"media/ldoce/hwd/bre/1/boo_interjecti0205.mp3","us":"media/ldoce/hwd/ame/7/boo1.mp3"},"examples":[{"en":"The audience booed as she started her speech.","cn":"她一开始讲话，听众便发出一阵嘘声。"},{"en":"‘Boo!’ they shouted, ‘Get off!’ “","cn":"去！”他们大声喊道，“滚下去！”"}],"oxford":{"phon":"buː","pos":"exclamation, noun","senses":[{"en":"a sound that people make to show that they do not like an actor, speaker, etc.","cn":"（对演员、讲话者等表示不满）嘘","ex":{"en":"‘Boo!’ they shouted, ‘Get off!’","cn":"“去！”他们大声喊道，“滚下去！”"}},{"en":"people shout Boo!when they want to surprise or frighten somebody","cn":"（惊吓他人的声音）乒"},{"en":"to show that you do not like a person, performance, idea, etc. by shouting ‘boo’","cn":"发嘘声；喝倒彩","ex":{"en":"The audience booed as she started her speech.","cn":"她一开始讲话，听众便发出一阵嘘声。"},"pos":"verb"}]}},"booze":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"酒","en":"Booze is alcoholic drink.","ex":{"en":"...booze and cigarettes.","cn":"酒和烟"}},{"pos":"VERB 动词","cn":"喝酒","en":"If people booze, they drink alcohol.","ex":{"en":"...a load of drunken businessmen who had been boozing all afternoon.","cn":"一群整个下午都在饮酒的醉醺醺的生意人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone drinks alcohol, especially a lot of it","cn":""},{"en":"drinks that contain alcohol – used especially in rules and warnings about alcoholic drinks","cn":""},{"en":"alcoholic drinks. Drink is more informal than alcohol","cn":""}]},"collocations":{"phrases":["ADJ. cheap | free There was free booze at the party.","VERB + BOOZE smell I could smell booze on his breath. | bring, take We need to take some booze to the party. | turn to He turned to booze (=","BOOZE + NOUN problem","PREP. off the ~ (= not drinking alcohol) She's been off the booze for a month now. | on the ~ (= drinking alcohol) He was dry for years but "]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41boozing.mp3","us":"media/ldoce/hwd/ame/8/ld41boozing.mp3"},"examples":[{"en":"He's out boozing with his mates.","cn":"他和他的朋友们喝酒去了。"},{"en":"He’s been on the booze (= drinking too much alcohol ) for five days.","cn":"他开怀痛饮了五天。"}],"oxford":{"phon":"buːz","pos":"noun","senses":[{"en":"alcoholic drink","cn":"含酒精饮料","ex":{"en":"Now he’s off the booze (= he has given up drinking alcohol), he’s a different person.","cn":"现在他戒了酒（=他已经戒酒了），他是一个不同的人。"}},{"en":"to drink alcohol, especially in large quantities","cn":"喝酒；（尤指）狂饮","ex":{"en":"He's out boozing with his mates.","cn":"他和他的朋友们喝酒去了。"},"pos":"verb"}]}},"boon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"给生活带来方便的事物","en":"You can describe something as a boon when it makes life better or easier for someone.","ex":{"en":"It is for this reason that television proves such a boon to so many people","cn":"就是因为这个原因，电视才会给这么多人带来如此大的便利。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make it easier for someone to do something or to make a difficult situation easier","cn":""},{"en":"to help someone do something","cn":""},{"en":"to help someone or something achieve something, by making the situation that they are in easier","cn":""}]},"vocab":{"pos":"1 n 2 adj","senses":[{"en":"Boon means something beneficial to a specific person, entity, or cause. \"Getting called out of school on the day of the test was a boon for Sam, as he hadn't remembered to study.\""}]},"collocations":{"phrases":["ADJ. enormous, great, real, tremendous","VERB + BOON be, come as, prove","PREP. ~ for The building scheme comes as an enormous boon for the building industry. | ~ to These machines have proved a real boon to disabl"]},"media":{"uk":"media/ldoce/hwd/bre/5/boon0205.mp3","us":"media/ldoce/hwd/ame/5/boon.mp3"},"examples":[{"en":"The new software will prove a boon to Internet users.","cn":"这种新软件将会对互联网用户大有益处。"},{"en":"The bus service is a real boon to people in the village.","cn":"公共汽车服务对村里的人来说是一大便利。"}],"oxford":{"phon":"buːn","pos":"noun","senses":[{"en":"something that is very helpful and makes life easier for you","cn":"非常有用的东西；益处","ex":{"en":"The device will prove a boon to home cooks.","cn":"该设备将为家庭厨师带来福音。"}}]}},"boston":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a city in Massachusetts on the Atlantic coast, the most important city in New England, and one of the oldest cities in the US. It is often thought of as being less noisy and more relaxed than other American cities, and is known for its old brick buildings. In ","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/p028-000002535.mp3","us":"media/ldoce/hwd/ame/6/p028-000002535.mp3"},"oxford":{"phon":"ˈbɒstən","pos":"","senses":[{"en":"the capital and largest city in the US state of Massachusetts. It is a major port and cultural centre, having nearly 50 colleges and universities. It also has the oldest underground railway in the US. Boston was settled in 1630 and played an important part in the American Revolution. It became a centre for Irish immigrants in the second half of the 19th century. International runners compete each year in the Boston marathon race, first run in 1897.","cn":"波士顿（美国马萨诸塞州首府和最大城市，重要的港口和文化中心，有近 50 所学院和大学）"}]}},"bound":{"collins":{"senses":[{"pos":"PHR-MODAL 情态动词短语","cn":"一定会；必然会；注定会","en":"If you say that something is bound to happen, you mean that you are sure it will happen, because it is a natural consequence of something that is already known or exists.","ex":{"en":"There are bound to be price increases next year","cn":"明年物价一定会上涨。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（对某事并不确定或无确凿证据时，认为其）肯定会，确定是","en":"If you say that something is bound to happen or be true, you feel confident and certain of it, although you have no definite knowledge or evidence.","ex":{"en":"I'll show it to Benjamin. He's bound to know","cn":"我会把它给本杰明看，他肯定会知道。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（与…）紧密相连的；（与…）密切相关的；（同…）难以分开的","en":"If one person, thing, or situation is bound to another, they are closely associated with each other, and it is difficult for them to be separated or to escape from each other.","ex":{"en":"We are as tightly bound to the people we dislike as to the people we love","cn":"不管是我们讨厌的人还是喜爱的人都一样和我们密切相关。"}},{"pos":"ADJ 形容词","cn":"要到…去的；驶往…的","en":"If a vehicle or person is bound for a particular place, they are travelling towards it.","ex":{"en":"The ship was bound for Italy.","cn":"这艘船驶向意大利。"}},{"pos":"PHRASE 短语","cn":"我不得不说（令人不快或出乎意料的事）","en":"You can say 'I am bound to say' to introduce a statement expressing something that you find undesirable or unexpected.","ex":{"en":"I'm bound to say that it seems to me this is certain to lead to violence.","cn":"我不得不说，在我看来这肯定会引发暴力事件。"}},{"pos":"PHRASE 短语","cn":"以…的形式；被容纳在…里","en":"If something is bound up in a particular form or place, it is fixed in that form or contained in that place.","ex":{"en":"The manager of a company does not like having a large chunk of his wealth bound up in its shares","cn":"一家公司经理不愿意让大笔财富套在股票里。"}},{"pos":"PHRASE 短语","cn":"与…密切相关的；同…难以分开的","en":"If one thing is bound up with or in another, they are closely connected with each other, and it is difficult to consider the two things separately.","ex":{"en":"My fate was bound up with hers","cn":"我和她的命运紧密相连。"}},{"pos":"N-PLURAL 复数名词","cn":"界限；限制","en":"Bounds are limits which normally restrict what can happen or what people can do.","ex":{"en":"Changes in temperature occur slowly and are constrained within relatively tight bounds.","cn":"温度变化缓慢，而且局限在相对较小的范围内。"}},{"pos":"VERB 动词","cn":"与…毗邻；成为…的边界","en":"If an area of land is bounded by something, that thing is situated around its edge.","ex":{"en":"Kirgizia is bounded by Uzbekistan, Kazakhstan and Tajikistan.","cn":"吉尔吉斯与乌兹别克斯坦、哈萨克斯坦和塔吉克斯坦接壤。"}},{"pos":"V-PASSIVE 被动动词","cn":"限制；约束","en":"If someone's life or situation is bounded by certain things, those are its most important aspects and it is limited or restricted by them.","ex":{"en":"Our lives are bounded by work, family and television.","cn":"我们的生活囿于工作、家庭和电视中。"}},{"pos":"VERB 动词","cn":"跳跃着前进","en":"If a person or animal bounds in a particular direction, they move quickly with large steps or jumps.","ex":{"en":"He bounded up the steps and pushed the bell of the door","cn":"他跳着上了台阶，按下了门铃。"}},{"pos":"N-COUNT 可数名词","cn":"蹦跳；跳跃","en":"A bound is a long or high jump.","ex":{"en":"She leaps in one bound onto her pony's back for a speedy canter around the ring","cn":"她纵身一跃骑上了马背，绕着场地策马慢跑。"}},{"pos":"VERB 动词","cn":"（数量）飞快增长；（表现）迅速改进","en":"If the quantity or performance of something bounds ahead, it increases or improves quickly and suddenly.","ex":{"en":"The shares bounded ahead a further 11p to 311p","cn":"股票价格又急涨了11便士，攀至311便士。"}},{"pos":"PHRASE 短语","cn":"无限；无止境；很强烈","en":"If you say that a feeling or quality knows no bounds, you are emphasizing that it is very strong or intense.","ex":{"en":"The passion of Argentinian football fans knows no bounds.","cn":"阿根廷足球迷极为热情。"}},{"pos":"PHRASE 短语","cn":"（某地）禁止进入","en":"If a place is out of bounds, people are not allowed to go there.","ex":{"en":"For the last few days the area has been out of bounds to foreign journalists.","cn":"最近几天该地区禁止外国记者进入。"}},{"pos":"PHRASE 短语","cn":"(某事物）被禁止","en":"If something is out of bounds, people are not allowed to do it, use it, see it, or know about it.","ex":{"en":"American parents may soon be able to rule violent TV programmes out of bounds.","cn":"美国的家长可能很快就会迫使含有暴力内容的电视节目遭禁播。"}},{"pos":"See also:","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the past tense and past participle of bind bind","cn":"的过去式和过去分词"},{"en":"moving, looking, or pointing in a particular direction","cn":""},{"en":"towards a place or object, but not moving, looking, or pointing directly at it","cn":""}]},"vocab":{"pos":"1 adj 2 adj 3 adj 4 ","senses":[{"en":"To bound is to jump or hop — usually as you run. Bound can also mean to go or to plan to go, especially to a certain destination, as in being bound for New York or homeward- bound ."}]},"collocations":{"phrases":["VERBS be, seem","ADV. almost These problems were almost bound to arise. 2 bound (to do sth): obliged to do sth","VERBS be, feel | become | remain | hold sb The president said the country could not be held bound by a treaty signed by the previous regime.","ADJ. absolutely | irrevocably | by law, contractually, legally Officials are bound by law to investigate any possible fraud. He was legally ","PREP. by We are legally bound by this decision. 3 travelling in a particular direction","VERBS be","ADV. homeward, outward","PREP. for tourists who are bound for Europe 4 bound up: closely connected"]},"media":{"uk":"media/ldoce/hwd/bre/f/b218new3.mp3","us":"media/ldoce/hwd/ame/d/ld41bound.mp3"},"examples":[{"en":"I am bound to say I disagree with you on this point.","cn":"我觉得有必要指出，在这一点上我不同意你的观点。"},{"en":"From that moment my life became inextricably bound up with hers.","cn":"从那一刻起，我的一生就和她结下不解之缘。"}],"oxford":{"phon":"baʊnd","pos":"adjective","senses":[{"en":"certain or likely to happen, or to do or be something","cn":"一定会；很可能会","ex":{"en":"There are bound to be changes when the new system is introduced.","cn":"引进新系统后一定会发生变化。"}},{"en":"forced to do something by law, duty or a particular situation","cn":"受（法律、义务或情况）约束（必须做某事）；有义务（做某事）","lab":"formal","ex":{"en":"We are not bound by the decision.","cn":"我们不受该决定的约束。"}},{"en":"prevented from going somewhere or from working normally by the conditions mentioned","cn":"因…受阻（或不能正常工作）","ex":{"en":"Strike-bound travellers face long delays.","cn":"因罢工滞留的旅客要耽搁很长时间。"}},{"en":"travelling, or ready to travel, in a particular direction or to a particular place","cn":"正旅行去（某地）；准备前往（某地）","ex":{"en":"homeward bound (= going home)","cn":"在回家途中"}},{"en":"to run with long steps, especially in an enthusiastic way","cn":"跳跃着跑","g":"[intransitive]","ex":{"en":"The dogs bounded ahead.","cn":"那些狗在前面蹦蹦跳跳地跑。"},"pos":"verb"},{"en":"to form the edge or limit of an area","cn":"形成…的边界（或界限）","g":"[transitive, usually passive]","lab":"formal","ex":{"en":"The field was bounded on the left by a wood.","cn":"那片地左边依傍着一片树林。"},"pos":"verb"},{"en":"a high or long jump","cn":"蹦跳；跳跃","ex":{"en":"The dog cleared the gate in one bound.","cn":"那狗一跳就越过了栅门。"},"pos":"noun"}]}},"boiler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指为建筑物提供集中供暖的）汽锅，锅炉","en":"A boiler is a device which burns gas, oil, electricity, or coal in order to provide hot water, especially for the central heating in a building."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a container for boiling water that is part of a steam engine, or is used to provide heating in a house 〔","cn":"蒸汽机内或室内供暖的〕锅炉"}]},"collocations":{"phrases":["ADJ. coal-fired, coke, electric, gas, gas-fired, oil-fired, solid-fuel, steam, water | central-heating","VERB + BOILER install, put in | service","BOILER + VERB come on I've just heard the hot water boiler come on. | go off | burst, explode","BOILER + NOUN system | suit"]},"media":{"uk":"media/ldoce/hwd/bre/a/boiler0205.mp3","us":"media/ldoce/hwd/ame/6/boiler.mp3"},"oxford":{"phon":"ˈbɔɪlə(r)","pos":"noun","senses":[{"en":"a container in which water is heated to provide hot water and heating in a building or to produce steam in an engine","cn":"锅炉；汽锅","ex":{"en":"a central heating boiler","cn":"中央供暖锅炉"}}]}},"bombard":{"collins":{"senses":[{"pos":"VERB 动词","cn":"连珠炮似的质问（或批评）；使大量面对","en":"If you bombard someone with something, you make them face a great deal of it. For example, if you bombard them with questions or criticism, you keep asking them a lot of questions or you keep criticizing them.","ex":{"en":"He bombarded Catherine with questions to which he should have known the answers","cn":"他明知故问地不断质问凯瑟琳。"}},{"pos":"VERB 动词","cn":"（用炮火或炸弹）猛烈轰击（或攻击）","en":"When soldiers bombard a place, they attack it with continuous heavy gunfire or bombs.","ex":{"en":"Rebel artillery units have regularly bombarded the airport","cn":"叛军的炮兵部队经常轰炸机场。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use a gun to fire bullets, or to kill or injure someone using a gun","cn":""},{"en":"to shoot bullets from a gun, or send an explosive object towards someone or something","cn":""},{"en":"to send a large rocket or missile into the air","cn":""}]},"vocab":{"pos":"1 v 2 n","senses":[{"en":"To bombard is to attack, whether physically (with something like missiles) or metaphorically (with something like questions)."}]},"collocations":{"phrases":["ADV. heavily The city has been heavily bombarded for the last three days. 2 direct a lot of things at sb","ADV. constantly, continually","PREP. with We're all constantly bombarded with television advertisements."]},"media":{"uk":"media/ldoce/hwd/bre/f/bombard0205.mp3","us":"media/ldoce/hwd/ame/3/bombard.mp3"},"examples":[{"en":"We have been bombarded with letters of complaint.","cn":"我们接二连三收到了大批的投诉信件。"},{"en":"The city came under heavy bombardment.","cn":"那座城市受到猛烈轰炸。"}],"oxford":{"phon":"bɒmˈbɑːd","pos":"verb","senses":[{"en":"to attack a place by firing large guns at it or dropping bombs on it continuously","cn":"轰炸；轰击","ex":{"en":"Madrid was heavily bombarded for several months.","cn":"马德里遭到了数月的猛烈轰炸。"}},{"en":"to attack somebody with a lot of questions, criticisms, etc. or by giving them too much information","cn":"大量提问；大肆抨击；提供过多信息","ex":{"en":"We have been bombarded with letters of complaint.","cn":"我们接二连三收到了大批的投诉信件。"}}]}},"bogus":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"假的；冒牌的；伪造的","en":"If you describe something as bogus, you mean that it is not genuine.","ex":{"en":"...their bogus insurance claim","cn":"他们伪造的保险索赔"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who pretends to be someone else in order to deceive people and gain something such as money or power","cn":""},{"en":"someone who pretends to have special skills or knowledge, for example as a doctor or teacher, when in fact they do not","cn":""},{"en":"pretending to have a particular job or position that you do not have, in order to do something dishonest or illegal","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Bogus means fake—a bogus dollar bill is counterfeit, a bogus Renoir was not painted by him, a bogus attempt at reconciliation would come from someone who never intended to end a fight."}]},"collocations":{"phrases":["VERBS be, look, seem | dismiss sth as 75 paintings which art experts dismiss as bogus","ADV. completely, entirely | largely"]},"media":{"uk":"media/ldoce/hwd/bre/b/bogus0205.mp3","us":"media/ldoce/hwd/ame/a/bogus.mp3"},"examples":[{"en":"bogus claims of injury by workers","cn":"工人们对受伤情况的虚报"},{"en":"a bogus doctor/contract","cn":"冒牌医生；伪造的合同"}],"oxford":{"phon":"ˈbəʊɡəs","pos":"adjective","senses":[{"en":"pretending to be real or true","cn":"假的；伪造的","ex":{"en":"a bogus doctor/contract","cn":"冒牌医生；伪造的合同"}}]}},"bombshell":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"意外的坏消息；出乎意料的消息","en":"A bombshell is a sudden piece of bad or unexpected news.","ex":{"en":"His resignation after thirteen years is a political bombshell","cn":"他任职13年后提出辞职，这在政治上轰动一时。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something very bad or unpleasant that happens to you and that you did not expect","cn":""},{"en":"an unpleasant event or piece of news that makes you shocked, upset, and disappointed","cn":""},{"en":"a piece of news which is extremely shocking and bad","cn":""}]},"collocations":{"phrases":["VERB + BOMBSHELL be, come as The news came as a bombshell. | drop Then she dropped the bombshell?she was pregnant.","BOMBSHELL + VERB come, drop"]},"media":{"uk":"media/ldoce/hwd/bre/d/bombshell0205.mp3","us":"media/ldoce/hwd/ame/e/bombshell.mp3"},"examples":[{"en":"She dropped a bombshell at the meeting and announced that she was leaving.","cn":"她在会上宣布了令人吃惊的消息，说她将要离开。"},{"en":"The news of his death came as a bombshell.","cn":"他去世的消息令人震惊。"}],"oxford":{"phon":"ˈbɒmʃel","pos":"noun","senses":[{"en":"an event or a piece of news which is unexpected and usually unpleasant","cn":"出乎意料的事情，意外消息（常指不幸）","ex":{"en":"The news of his death came as a bombshell.","cn":"他去世的消息令人震惊。"}},{"en":"a very attractive woman","cn":"美女","ex":{"en":"a blonde bombshell","cn":"金发美女"}}]}},"boom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（经济的）繁荣，景气","en":"If there is a boom in the economy, there is an increase in economic activity, for example in the amount of things that are being bought and sold.","ex":{"en":"An economic boom followed, especially in housing and construction","cn":"接着出现了经济繁荣，尤其是在房地产业和建筑业。"}},{"pos":"N-COUNT 可数名词","cn":"（数量的）增长；（频率的）加快；成功","en":"A boom in something is an increase in its amount, frequency, or success.","ex":{"en":"The boom in the sport's popularity has meant more calls for stricter safety regulations","cn":"该项体育运动的兴起意味着制定更加严格的安全规则的呼声更高了。"}},{"pos":"VERB 动词","cn":"（经济或生意）景气，繁荣","en":"If the economy or a business is booming, the amount of things being bought or sold is increasing.","ex":{"en":"By 1988 the economy was booming","cn":"到1988年经济一直很繁荣。"}},{"pos":"N-COUNT 可数名词","cn":"（船帆的）下桁；帆桁","en":"On a boat, the boom is the long pole which is attached to the bottom of the sail and to the mast and which you move when you want to alter the direction in which you are sailing."},{"pos":"N-COUNT 可数名词","cn":"浮木挡栅，水栅（用来阻挡溢出的油扩散）","en":"A boom is a large floating barrier that is used for stopping oil that has spilled from spreading."},{"pos":"VERB 动词","cn":"（人)吼叫；（大炮或大鼓）发隆隆声","en":"When something such as someone's voice, a cannon, or a big drum booms, it makes a loud, deep sound that lasts for several seconds.","ex":{"en":"'Ladies,' boomed Helena, without a microphone, 'we all know why we're here tonight.'","cn":"“女士们，”海伦娜大声喊道，没有用麦克风，“我们都知道今晚我们为什么来到这里。”"}},{"pos":"","cn":"","en":"→see: ;"},{"pos":"","cn":"","en":"相关词组：boom out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden very large increase in the amount or number of something","cn":""},{"en":"a sudden large increase in trade, profits or sales, with the result that a country, company, or industry becomes very successful. Boom is also used about a sudden increase in interest in something, with the result that it becomes very popular","cn":""},{"en":"a short sudden loud noise made by a gun, bomb etc","cn":""}]},"collocations":{"phrases":["ADJ. great | post-war | consumer, credit, economic, investment, spending | building, housing, property | oil | baby","VERB + BOOM cause, create, fuel, lead to The boom was fuelled by accelerated demand for consumer products.","BOOM + NOUN period, time, year | town","PREP. during/in a/the ~ He was born during the post-war baby boom. | ~ in a boom in house prices","PHRASES boom and bust/slump the ordinary business cycle of boom and bust 2 deep hollow sound","ADJ. big | deep | distant | sonic (= the explosive sound made when an aircraft flies faster than the speed of sound) We heard the sonic boom","VERB + BOOM hear","BOOM + VERB echo The deep boom of a foghorn echoed across the bay."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeboom.mp3","us":"media/ldoce/hwd/ame/8/boom1.mp3"},"examples":[{"en":"Living standards improved rapidly during the post-war boom.","cn":"在战后那段繁荣昌盛的时期里，生活水平得到了迅速提高。"},{"en":"By the 1980s, the computer industry was booming.","cn":"到 20 世纪 80 年代时，计算机行业迅猛发展。"}],"oxford":{"phon":"buːm","pos":"noun","senses":[{"en":"a sudden increase in trade and economic activity; a period of wealth and success","cn":"（贸易和经济活动的）激增，繁荣","sc":"in business/economy","ex":{"en":"Living standards improved rapidly during the post-war boom.","cn":"在战后那段繁荣昌盛的时期里，生活水平得到了迅速提高。"}},{"en":"a period when something such as a sport or a type of music suddenly becomes very popular and successful","cn":"（某种体育运动、音乐等）突然风靡的时期","g":"[usually singular]","sc":"popular period","ex":{"en":"The only way to satisfy the golf boom was to build more courses.","cn":"满足这场高尔夫球热的唯一途径是增建球场。"}},{"en":"a long pole that the bottom of a sail is attached to and that you move to change the position of the sail","cn":"帆桁","sc":"on boat"},{"en":"a loud deep sound","cn":"深沉的响声","g":"[usually singular]","sc":"sound","ex":{"en":"the distant boom of the guns","cn":"远处隆隆的炮声"}},{"en":"a floating barrier that is placed across a river or the entrance to a harbour to prevent ships or other objects from coming in or going out","cn":"水栅","sc":"in river/harbour"},{"en":"a long pole that carries a microphone or other equipment","cn":"吊杆；支架","sc":"for microphone"},{"en":"to make a loud deep sound","cn":"轰鸣；轰响","g":"[intransitive]","sc":"make loud sound","ex":{"en":"Outside, thunder boomed and crashed.","cn":"外面雷声隆隆，霹雳炸响。"},"pos":"verb"},{"en":"to say something in a loud deep voice","cn":"以低沉有力的声音说话","g":"[transitive, intransitive]","sc":"make loud sound","ex":{"en":"‘Get out of my sight!’ he boomed.","cn":"“别让我再见到你！”他低沉而有力地说。"},"pos":"verb"},{"en":"to have a period of rapid growth; to become bigger, more successful, etc.","cn":"迅速发展；激增；繁荣昌盛","g":"[intransitive]","sc":"of business/economy","ex":{"en":"By the 1980s, the computer industry was booming.","cn":"到 20 世纪 80 年代时，计算机行业迅猛发展。"},"pos":"verb"}]}}});
